INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2179150, 612130, 'Camarera/o', 'Hotel ibis', 'Olivier, es un restaurante, con locales en CABA y en PILAR.Actualmente nos encontramos en la busqueda de camareras/os para nuestros locales de CABA, que cumplan los siguientes requisitos:Requisitos: Un año de experiencia en empleos o tareas similares Que viva en la zona o aledañios Disponibilidad horaria de 7hs a 00hs (siendo solamente 8 horas de trabajo diarias, con descanso de almuerzo incluido)Beneficios: Uniforme Comedor de personalSi pensas que cumplís con dichos requisitos esperamos tu CV!', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 12:20:23', '09-04-2026 13:25:27', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 10, 2641, 1, NULL, 0, 0, NULL, 70, 'Avisos Classic', 'zonajobs', 'zonajobs', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2179150.html', '2026-04-10T07:05:55.102962');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225800, 2612300, 'Líder de Automatizaciones e IA - Mix (Onsite - Remoto)', 'Aliantec', '¿Qué hace la compañía?Empresa de servicios con larga trayectoria en el mercado, se encuentra ampliando su equipo. Se encargan de brindar servicios de transporte y distribución, operaciones portuarias, Warehousing, comercio exterior y soluciones de ecommerce, para sus clientes de áreas de retail, salud y cuidado personal, metalúrgica, entre otros¿Qué necesitás para ser parte del equipo?A nivel personal: Perfil curioso e innovador, con interés genuino por las nuevas tecnologías. Capacidad de liderazgo y gestión de equipos interdisciplinarios. Habilidades de comunicación y trabajo colaborativo. Orientación a resultados y pensamiento estratégico. Capacidad para interactuar con múltiples áreas del negocio y proveedores externos.A nivel técnico: Experiencia previa liderando proyectos tecnológicos o de innovación | Al menos 4 años. Experiencia en implementación de IA en proyectos de tecnología | Excluyente. Conocimientos en automatización, RPA. Experiencia en gestión de proyectos. Manejo de herramientas de gestión como Jira y Confluence. Inglés avanzado (excluyente), con capacidad para interactuar con proveedores internacionales. Se valorará experiencia en industria logística (no excluyente).¿Qué vas a hacer? Liderar y coordinar el equipo de Innovación Tecnológica. Definir y ejecutar el roadmap de innovación tecnológica de la compañía. Gestionar el portafolio de proyectos del área, priorizando iniciativas según impacto y viabilidad. Impulsar proyectos en distintas verticales: automatización (RPA, chatbots, IA), desarrollo de productos tecnológicos, tecnologías aplicadas a almacenes (RFID, robótica) y exploración de nuevas soluciones. Coordinar el trabajo con proveedores tecnológicos locales e internacionales. Acompañar la evaluación, diseño y validación de nuevas tecnologías y pruebas de concepto. Actuar como nexo entre las áreas de negocio y los equipos técnicos.¿Cuál es el desafío de la posición?El principal desafío del rol será liderar y consolidar el área de Innovación Tecnológica, dando continuidad y proyección a las iniciativas actuales, y diseñando un plan de dirección tecnológica alineado a las necesidades del negocio y al crecimiento de la compañía.¿Con qué herramientas trabajarás?Las herramientas con las que se trabajará serán: Herramientas de gestión de proyectos: Jira, Confluence. Plataformas de automatización y RPA a nivel conceptual (Power Automate, Automation Anywhere, entre otras). Tecnologías vinculadas a IA, automatización, IoT y soluciones cloud, según los proyectos.¿Cuándo y dónde trabajarás?Trabajarás de lunes a viernes de 9 a 18hs, bajo un esquema híbrido, debiendo asistir a las oficinas ubicadas en Zona Norte de la Provincia de Buenos Aires dos veces por semana.¿Qué ofrecen? Relación de dependencia directa. Prepaga para grupo familiar. Kit de bienvenida y muchos más!¿De qué fases consta el proceso de selección?Tendrás una primera entrevista con nuestra Recruiter, Mariana Herrero, para conocer tus experiencias laborales e intereses. Luego, con la empresa empleadora tendrás 1 instancia para conocer al equipo técnico, otra con Recursos Humanos, y una última presencial.', 0, 'Buenos Aires, Buenos Aires', 'Híbrido', 'Full-time', '09-04-2026', '09-04-2026 16:52:42', '09-04-2026 16:52:42', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 19, 2619, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_2612300_bum_v71b9694.jpg', 0, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'tecnologia', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225800.html', '2026-04-10T07:05:55.103203');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225824, 2612300, 'Coordinador de Sistemas - Mix (Onsite Remoto) - Palermo, CABA', 'Aliantec', '¿Qué hace la compañía?Empresa con sólida presencia en el mercado retail y proyección internacional, actualmente en proceso de expansión hacia nuevos mercados.¿Qué necesitás para ser parte del equipo?A nivel personal: Perfil operativo, con capacidad de liderazgo práctico. Buen manejo de la presión y de la comunicación con usuarios. Capacidad para ordenar, priorizar y tomar decisiones. Flexibilidad para adaptarse a un contexto de cambio.A nivel técnico: Experiencia previa coordinando y liderando equipos de Sistemas o IT. Conocimientos sólidos en SQL (excluyente) y Experiencia en Power BI (Tableros) Experiencia trabajando con ERP Experiencia en automatización de procesos y mejora continua. Conocimientos generales de infraestructura y sistemas. Capacidad para interactuar con proveedores tecnológicos.¿Qué vas a hacer?Como Coordinador de Sistemas deberás: Liderar y coordinar el equipo de Sistemas. Asegurar la estabilidad operativa de los sistemas actuales. Administrar y optimizar el ERP acompañando mejoras continuas. Desarrollar y mantener reportes y soluciones de BI / SQL para el negocio. Impulsar procesos de automatización y mejoras operativas. Gestionar proveedores de tecnología e infraestructura. Priorizar demandas, ordenar backlog y evitar el rebote constante de tareas. Actuar como referente técnico frente a usuarios internos, con buena comunicación y criterio. Documentar procesos y generar orden en un contexto de recursos limitados.¿Cuándo y dónde trabajarás?El esquema de trabajo es híbrido con 1 día de Home Office y 4 días on site en las oficinas de Palermo, Buenos Aires, en el horario de 9 a 18 hs de lunes a viernes.¿Con quién trabajarás?Con el equipo de tecnología, áreas internas y proveedores.¿Qué ofrecen? Relación de dependencia. Esquema híbrido de trabajo. Prepaga de primer nivel para el empleado y grupo familiar. Día de cumpleaños libre. Descuentos en la marca. Cuponera de descuentos en servicio, turismo, educación, tecnología, entre otras.¿De qué fases consta el proceso de selección?Tendrás una primera entrevista con nuestra Recruiter, Aldana Alvarenga, para conocer tus experiencias laborales e intereses. Posteriormente, una entrevista con HR de la empresa. Y por último, una entrevista técnica con el responsable del área.', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '09-04-2026', '09-04-2026 16:57:58', '09-04-2026 16:57:58', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 19, 2619, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_2612300_bum_v71b9694.jpg', 0, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'tecnologia', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225824.html', '2026-04-10T07:05:55.103339');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225791, 2612300, 'Tech Lead .Net - Mix (Onsite - Remoto) - 1803', 'Aliantec', '¿Qué hace la compañía?Empresa de servicios con larga trayectoria en el mercado, se encuentra ampliando su equipo. ¿Querés ser parte?¿Qué necesitás para ser parte del equipo?A nivel personal: Capacidad para gestionar un equipo de 6 personas, enfocado en mejorar el relacionamiento interno y con otras áreas. Fuerte orientación a la resolución de problemas complejos. Capacidad de decisión para definir estrategias sobre proyectos. Habilidad para actuar como nexo entre perfiles técnicos y stakeholders de negocio. Apertura a nuevas tecnologías. Autonomía, responsabilidad y compromiso.A nivel técnico: Experiencia mínima de 5 años de experiencia en posiciones de liderazgo técnico o gestión de equipos de desarrollo. Experiencia sólida habiendo trabajado con ecosistemas .Net | Excluyente Manejo de SQL Server. Contar con experiencia práctica en Microsoft Azure. Sólida experiencia en diseño de arquitecturas digitales, patrones de diseño y procesos de reingeniería de sistemas. Experiencia comprobable coordinando partners externos y controlando la calidad de entregas tercerizadas. Inglés avanzado. Graduados o estudiantes avanzados en Ingeniería en Sistemas o carreras afines (deseable).¿Qué vas a hacer? Liderar técnica y arquitectónicamente el desarrollo de aplicaciones. Definir y evolucionar la arquitectura de las soluciones, realizando reingeniería sobre sistemas existentes si es necesario. Gestionar el equipo de 6 personas, fomentando la mentoría y el coaching. Supervisar el trabajo de los equipos de desarrollo, asegurando cumplimiento de plazos, calidad y objetivos. Coordinar proveedores externos, evaluando la calidad de sus entregas y su alineación con el negocio. Promover prácticas de DevOps, automatización e incorporación progresiva de IA en el ciclo de vida del software.¿Cuál es el desafío de la posición?Te enfrentarás a un ecosistema basado en .NET donde tu mirada crítica será fundamental para liderar procesos de reingeniería, adoptando arquitecturas cloud-native, microservicios e Inteligencia Artificial. Tendrás la autoridad para decidir el futuro de cada proyecto bajo la visión de "make vs buy", evaluando cuándo potenciar el desarrollo in-house y cuándo gestionar proveedores estratégicos.¿Con qué herramientas trabajarás?Las herramientas con las que se trabajará serán: Ecosistema .NET (Core / Framework). Arquitecturas Cloud-native y Microservicios. Herramientas de Observabilidad y Seguridad. Plataformas de automatización de ciclo de vida de software (CI/CD)¿Con quién trabajarás?Reportarás directamente a la gerencia del área de Tecnología y tendrás a cargo un equipo directo de 6 personas (desarrolladores y especialistas técnicos). También interactuarás constantemente con proveedores estratégicos de IT y líderes de otras unidades de negocio.¿Cuándo y dónde trabajarás?Trabajarás de lunes a viernes de 9 a 18hs. El esquema de trabajo es híbrido, debiendo asistir a las oficinas ubicadas en Zona Norte de la Provincia de Buenos Aires dos veces por semana.¿Qué ofrecen? Relación de dependencia directa. Prepaga para grupo familiar. Kit de bienvenida y muchos más!¿De qué fases consta el proceso de selección?Tendrás una primera entrevista con nuestra Recruiter, Lorena Dos Santos, para conocer tus experiencias laborales e intereses.Luego, con la empresa empleadora tendrás una instancia para conocer al equipo técnico, una instancia con Recursos Humanos y una entrevista presencial con la gerencia.', 0, 'Olivos, Buenos Aires', 'Híbrido', 'Full-time', '09-04-2026', '09-04-2026 16:49:49', '09-04-2026 16:49:49', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 19, 2619, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_2612300_bum_v71b9694.jpg', 0, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'tecnologia', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225791.html', '2026-04-10T07:05:55.103494');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225783, 2612300, 'IT Support Coordinator Ssr - Mix (Onsite - Remoto) - 1805', 'Aliantec', '¿Qué hace la compañía?Empresa global líder en tecnologías de dispensación, dosificación y protección de productos, con foco en apoyar a marcas de salud y consumo en todo el mundo¿Qué necesitás para ser parte del equipo?A nivel personal: Comunicación efectiva con equipos remotos y multiculturales. Proactividad, autonomía y enfoque colaborativo.A nivel técnico: Experiencia de 3 años o más en roles de Soporte IT / IT Operations / ITSM | Excluyente. Sólidos conocimientos en herramientas ITSM (deseable ServiceNow). Conocimientos generales de infraestructura: ○ Windows / servidores ○ VMware (v7.0 deseable) ○ Backups / DR (Veeam deseable) ○ Redes (DNS, DHCP, LAN/WIFI, WAN/SDWAN) ○ Gestión de parches Inglés intermedio para comunicarte con equipos globales. Certificación ITIL (deseable).¿Qué vas a hacer?Como IT Support Coordinator Ssr serás el/ la responsable: Administrar el proceso de Incident Management y Service Request Management. Gestionar y dar seguimiento de tickets en ServiceNow, asegurando el cumplimiento de SLA. Actuar como punto de escalamiento para incidentes mayores o solicitudes críticas. Coordinar con equipos técnicos globales y proveedores externos (ej. SAP y especialistas regionales/internacionales). Supervisar incidentes y solicitudes para asegurar una correcta priorización y resolución. Elaborar reportes y seguimiento de KPIs del área. Impulsar mejoras continuas en procesos de soporte (incluyendo iniciativas de “shift-left”). Brindar soporte técnico de base para infraestructura y usuarios (hardware/software, accesos, conectividad).¿Cuándo y donde trabajarás?Trabajarás bajo un esquema híbrido, en las oficinas ubicadas en GBA Sur. El horario es de lunes a viernes de 8a 17 hs.¿Cuál es el desafío de la posición?Como IT Support Coordinator Ssr , serás el/la responsable de la operación diaria del proceso de soporte IT, garantizando la correcta gestión de incidentes y solicitudes de servicio, con foco en la continuidad operativa, el cumplimiento de SLA y la mejora continua del servicio.¿Qué ofrecen? Relación de dependencia directa Días de Home Office. Prepaga para vos y tu grupo familiar directo. Comedor en planta a cargo de la compañía. Bono anual. Ajustes salariales por inflación.¿De qué fases consta el proceso de selección?Tendrás una primera entrevista con nuestra Recruiter, Melina Rubio, para conocer tus experiencias laborales e intereses. Luego tendrás dos instancias más con la empresa empleadora, una con RRHH y la otra con el líder del área, donde podrás compartir tu experiencia y conocer más sobre los desafíos tecnológicos del rol.', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '09-04-2026', '09-04-2026 16:46:09', '09-04-2026 16:46:09', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 19, 108, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_2612300_bum_v71b9694.jpg', 0, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'tecnologia', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225783.html', '2026-04-10T07:05:55.103663');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225774, 2612300, 'Desarrollador Node Js Ssr - Mix (Onsite - Remoto) - 1807', 'Aliantec', '¿Qué hace la compañía?Empresa tecnológica con sólida proyección en el mercado, especializada en el desarrollo de soluciones SaaS para la gestión integral de flotas y equipos pesados en la industria de la construcción. Se destaca por su enfoque estratégico orientado a datos, innovación constante y compromiso con la optimización operativa y financiera de sus clientes.¿Qué necesitás para ser parte del equipo?A nivel personal: Capacidad para trabajar con requerimientos abiertos o en evolución. Buen criterio técnico para tomar decisiones y explicar trade-offs. Mentalidad de producto y foco en impacto real. Buena comunicación y predisposición para trabajar en equipo reducido. Autonomía, criterio técnico y capacidad de ejecución.A nivel técnico: Experiencia de +3 años en desarrollo Backend con Node.js participando en entornos productivos. Dominio avanzado de TypeScript y buenas prácticas asociadas. Experiencia sólida en diseño y modelado de bases de datos relacionales, preferentemente PostgreSQL, incluyendo optimización de queries y manejo eficiente de transacciones. Experiencia en diseño, desarrollo y documentación de APIs, idealmente bajo paradigma GraphQL. Sólidos conocimientos de principios de diseño de software, patrones de arquitectura backend y modelado de dominio. Manejo de Git y experiencia trabajando con flujos colaborativos (PRs, code review, branching strategies). Si cuentas con experiencia previa en productos SaaS, startups o entornos orientados a producto, ¡es un plus!¿Qué vas a hacer?Diseñar, desarrollar y evolucionar APIs backend robustas, seguras y escalables, asegurando alta performance y mantenibilidad. Implementar y modelar lógica de negocio compleja, vinculada a: - Gestión de uso, disponibilidad y trazabilidad de maquinaria. - Procesamiento de telemetría y eventos en tiempo real. - Generación de reportes, métricas y agregaciones de datos. - Sistemas de autenticación, autorización, roles y permisos. Diseñar y optimizar modelos de datos en PostgreSQL, garantizando integridad, consistencia y eficiencia en consultas de alto volumen. Participar activamente en decisiones de arquitectura, escalabilidad y performance, proponiendo mejoras técnicas continuas. Escribir código limpio, testeable y alineado a buenas prácticas (testing, code reviews, estándares de calidad). Colaborar en la definición técnica y estimación de nuevas funcionalidades, trabajando de forma cercana con producto y stakeholders. Identificar, diagnosticar y resolver problemas de performance, concurrencia y consistencia de datos. Contribuir al crecimiento técnico del equipo, promoviendo estándares, buenas prácticas y mejoras en los procesos de desarrollo.¿Cuál es el desafío de la posición?Como Desarrollador Node JS Ssr, tendrás el desafío de diseñar, desarrollar y evolucionar los servicios core de una plataforma SaaS orientada a datos, garantizando performance, escalabilidad y solidez técnica en cada solución. Ademas, liderarás la construcción de nuevas funcionalidades backend, optimizarás arquitecturas existentes y participarás activamente en decisiones técnicas clave,desde el diseño de APIs hasta la definición de estándares y buenas prácticas. Buscamos un perfil con mentalidad de ownership, foco en calidad de código y capacidad para transformar desafíos complejos en soluciones simples, robustas y escalables.¿Con quién trabajarás?Cuenta con un equipo altamente orientado a producto, con foco en calidad técnica, escalabilidad y desarrollo de soluciones que responden a desafíos reales del negocio en entornos industriales exigentes.¿Cuándo y dónde trabajarás?Trabajarás de lunes a viernes, de 9 hs a 18 hs, con flexibilidad para asistir a las oficinas ubicadas en Retiro (CABA).¿Qué ofrecen? Modalidad Contractor Salario en USD¿De qué fases consta el proceso de selección?Tendrás una primera entrevista con nuestra Recruiter, Melina Rubio, para conocer tus experiencias laborales e intereses. Luego, con la empresa empleadora tendrás una instancia para conocer al equipo y luego otra instancia técnica.', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '09-04-2026', '09-04-2026 16:41:39', '09-04-2026 16:41:39', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 19, 2621, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_2612300_bum_v71b9694.jpg', 0, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'tecnologia', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225774.html', '2026-04-10T07:05:55.103891');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225749, 2612300, 'Desarrollador Salesforce Sr. (Reglas de Negocio) - Mix (Onsite - Remoto) - Retiro - 1808', 'Aliantec', '¿Qué hace la compañía?Importante Banco Nacional de capitales privados con la mayor red de sucursales en Argentina. Brindan distintos servicios financieros a más de 4 millones de clientes, tanto en banca individuos como en banca empresas.¿Qué necesitás para ser parte del equipo?A nivel personal: Capacidad analítica para traducir procesos de negocio en lógica técnica. Habilidades de comunicación para interactuar con equipos de negocio y tecnología. Orientación a resultados. Proactividad y capacidad de trabajo colaborativo. Orientación al cumplimiento de estándares y calidad de datos.A nivel técnico: Al menos 4 años de experiencia trabajando en roles similares de customización de CRM y motores de decisión | Excluyente. Dominio de Salesforce Business Rules Engine (BRE) | Excluyente. Manejo avanzado de Flow Builder para automatización de procesos | Excluyente. Conocimientos en Apex para optimización de lógica de negocio | Excluyente. Experiencia en reportes y dashboards en Salesforce. Conocimiento de Financial Services Cloud (deseable) Experiencia en metodologías ágiles. Entendimiento de modelos de datos aplicados a CRM/CDP y marketing. Estudios: Estudiante avanzado o graduado/a en Sistemas, Ingeniería, Ciencias de Datos o carreras afines.¿Qué vas a hacer? Implementarás y mantendrás reglas de negocio utilizando Expression Sets, Decision Matrices y Decision Tables en BRE. Diseñarás y construirás flujos complejos en Flow Builder para automatizar la toma de decisiones en tiempo real. Desarrollarás componentes en Apex para extender y optimizar las capacidades del motor de reglas. Asegurarás la consistencia de datos entre Salesforce Core, Data Cloud y Marketing Cloud. Configurarás reportes y dashboards para monitorear la ejecución y performance de las reglas. Documentarás la lógica técnica y gestionarás el versionado de los motores de reglas. Colaborarás con equipos de negocio y tecnología para traducir requerimientos en soluciones escalables.¿Cuál es el desafío de la posición?Serás protagonista en la evolución del motor de decisiones de Banca Individuo, impactando directamente en la experiencia que vive el cliente cada vez que interactúa con el banco. Ya sea desde el motor de reglas (BRE) o desde la gestión integral de Salesforce Financial Services Cloud, el rol combina visión de negocio y profundidad técnica para transformar necesidades comerciales y analíticas en decisiones y experiencias concretas dentro del CRM.¿Con quién trabajarás?Trabajarás dentro de la gerencia de Marketing & BI de Banca Individuo, en un equipo que articula CRM, motor de decisiones y analítica avanzada. Tendrás interacción directa con referentes funcionales, equipo de Datos en GCP y perfiles técnicos de Salesforce, en un entorno colaborativo donde negocio y tecnología trabajan de forma integrada.¿Cuándo y dónde trabajarás?Trabajarás en un esquema híbrido asistiendo 3 días en las oficinas del cliente en la zona de Retiro y 2 días de Home Office, de lunes a viernes de 9-18 h¿Qué ofrecen? Relación de dependencia directa. Convenio Bancario. Día del bancario: feriado y bono. Descuentos en productos. Monto fijo de guarderías para madre y padres. Becas de grado y posgrado. Licencia por estudio. Más de 200 cursos y rutas de aprendizaje para capacitarte. Descuentos en SportClub. Campañas de vacunación. Descuento en Clínicas y consultas médicas virtuales. Kits escolares para tus hijos + regalo del día de las infancias Gratificación por matrimonio y por nacimiento.¿De qué fases consta el proceso de selección?Tendrás una primera entrevista con nuestra Recruiter, Rocío Albelo, para conocer tus experiencias laborales e intereses.Luego, participarás de dos entrevistas con nuestro cliente, conociendo al líder en primera instancia y a la Gerencia en segunda.', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '09-04-2026', '09-04-2026 16:34:05', '09-04-2026 16:34:05', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 19, 2621, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_2612300_bum_v71b9694.jpg', 0, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'tecnologia', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225749.html', '2026-04-10T07:05:55.104089');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225846, 2612300, 'Líder Técnico Full Stack (JAVA / React) Senior - Mix (Onsite - Remoto) - 1777', 'Aliantec', '¿Qué hace la compañía?Grupo empresario argentino con presencia nacional y trayectoria consolidada, con fuerte protagonismo en la industria bancaria y de servicios financieros, y operación en múltiples sectores estratégicos del país. Con foco en innovación, desarrollo regional y evolución tecnológica, continúa fortaleciendo sus plataformas digitales para acompañar el crecimiento del negocio y mejorar la experiencia de usuarios y clientes.Desde la Gerencia Corporativa de IT, se impulsa el desarrollo de soluciones modernas, escalables y seguras, en un entorno que combina desafíos técnicos, impacto real y trabajo colaborativo.¿Qué necesitás para ser parte del equipo?A nivel personal: Capacidad para liderar equipos técnicos, generando foco, orden y alineación con objetivos del negocio. Perfil proactivo, con visión integral para anticipar necesidades de evolución de plataformas. Excelente comunicación para articular con áreas de negocio, producto, arquitectura y otros equipos de ingeniería. Capacidad para priorizar, tomar decisiones y sostener estándares de calidad en entornos exigentes. Orientación a resultados, mejora continua y seguimiento de métricas técnicas. Autonomía y pensamiento estratégico para gestionar interdependencias entre sistemas y plataformas.A nivel técnico: Más de 5 años de experiencia liderando equipos técnicos con profundo conocimiento de desarrollo Full-Stack (Java/Spring Boot , React) con foco en plataformas digitales: Experiencia sólida en Java 17+. Experiencia con Spring Boot, Spring Data (JPA/Hibernate) y Spring Security. Conocimientos en Quarkus y/o Spring Cloud. Experiencia en diseño e implementación de APIs RESTful y gRPC. Dominio de TypeScript Experiencia en frontend con React 18 (Hooks, Context API, Server Components). Conocimientos de UI con librerías como Tailwind CSS, Material UI o Styled Components. Experiencia en optimización de performance web (SSR, SSG, ISR y Core Web Vitals). Experiencia con bases de datos relacionales y no relacionales, incluyendo Redis. Experiencia práctica con mensajería/eventos: Kafka (alto rendimiento) y/o RabbitMQ. Conocimiento e implementación de patrones: Pub/Sub, Event Sourcing y CQRS. Capacidad para modelar dominios complejos (DDD): Bounded Contexts, agregados y entidades.¿Qué vas a hacer? Definir y ejecutar la visión técnica de las plataformas de canales, asegurando alineación con objetivos del negocio y del producto. Liderar al equipo técnico en el desarrollo y evolución de plataformas, garantizando continuidad operativa y escalabilidad. Trabajar en conjunto con equipos de producto para evolucionar soluciones alineadas a la estrategia del producto. Gestionar y priorizar el backlog técnico, asegurando decisiones alineadas con KPIs operativos y de negocio. Supervisar la entrega técnica de los desarrollos, garantizando estándares de calidad, seguridad y performance. Monitorear KPIs técnicos de la plataforma y proponer mejoras continuas. Identificar sinergias e interdependencias con otras plataformas y equipos para maximizar el valor entregado. Actuar como referente técnico y punto de contacto clave para stakeholders, facilitando comunicación y toma de decisiones.¿Cuál es el desafío de la posición?Las personas que se incorporen, tendrán el desafío de definir y ejecutar la visión técnica de las plataformas técnica de canales, asegurando que cumpla con los objetivos y características definidas.Este rol implica priorizar esfuerzos, y colaborar estrechamente con las áreas de negocio para diseñar, construir y lanzar plataformas que se soporten y se alineen con la visión de los productos.Es responsable de la calidad técnica, la eficiencia del desarrollo y la implementación rigurosa de patrones de diseño, asegurando que las soluciones escalen y sean robustas, tanto en entornos Cloud Native como en infraestructuras On-Premise.¿Cuándo y dónde trabajarás?Trabajarás de lunes a viernes, de 9 a 18 hs, bajo un esquema híbrido, con presencialidad de 1 día por semana en las oficinas ubicadas en Capital Federal.¿Qué ofrecen? Relación de dependencia directa. Excelentes condiciones de contratación bajo convenio bancario. Modalidad: esquema híbrido. Cobertura de prepaga para vos y tu grupo familiar directo- Plataforma de bienestar de primer nivel. Importantes descuentos en instituciones educativas para para vos y tu familia. Formación constante para la posición y para el desarrollo profesional. Beneficio de guardería. Cotización preferencial en productos bancarios. Bonificación en plataforma de compras Club de Beneficios.¿De qué fases consta el proceso de selección?Tendrás una primera entrevista con la Recruiter, Aldana Alvarenga, para conocer tu experiencia, expectativas e intereses.Luego, el proceso continuará con la empresa empleadora a través de distintas instancias, orientadas a que puedas conocer al equipo técnico, a Recursos Humanos y a la gerencia.', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '09-04-2026', '09-04-2026 17:02:34', '09-04-2026 17:02:34', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 19, 2621, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_2612300_bum_v71b9694.jpg', 0, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'tecnologia', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225846.html', '2026-04-10T07:05:55.104308');
