INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2178888, 628677, 'Vendedor/a de Mostrador', 'B&B Consultores', '¡Atención Rosario!Desde B&B Consultores, acompañamos a Dr. Verde, un negocio en plena transformación hacia el mundo de la tecnología, que busca sumar a su equipo un Vendedor/a de Mostrador para su local en zona céntrica de Rosario.¿Qué vas a hacer? Atender y asesorar a clientes. Detectar necesidades y recomendar productos de tecnología (PCs, notebooks, accesorios, etc.). Responder consultas vía WhatsApp, redes sociales y plataformas de e-commerce. Manejar caja, cobranzas y facturación. Recibir mercadería, controlar inventario y ocuparse de la exhibición de productos. Requisitos: Experiencia en ventas (ideal tecnología, hogar y/o electro). Conocimiento en informática o formación técnica afín, preferentemente. Perfil dinámico y orientado al cliente.Jornada: Lunes a viernes: 9 a 13 hs y 13:30 a 18 hs. Sábados: 9:30 a 12:30 hs. Beneficios Oportunidad de sumarse a una empresa en crecimiento, capacitación, acompañamiento y la posibilidad de ser parte de un equipo en expansión.', 0, 'Rosario, Santa Fe', 'Presencial', 'Full-time', '06-04-2026', '06-04-2026 07:39:26', '06-04-2026 07:39:26', '2026-04-06', NULL, NULL, '2026-04-06T00:00:00-03:00', NULL, NULL, 1, 0, 6, 35, 1, 'https://imgzj.jobscdn.com/portal/img/empresas/1/static/logoMainPic_628677_bum_ve98665c.jpg', 0, 0, NULL, 1020, 'Aviso Select', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2178888.html', '2026-04-10T07:05:55.104470');
