INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224777, 1478000, 'BU747 SUPERVISOR DE MANTENIMIENTO | MULTINACIONAL EN EXPANSIÓN | SANTIAGO DEL ESTERO', 'CONA CONSULTORES EN RRHH', '🚀 ¡Nueva oportunidad laboral en Santiago del Estero!Supervisor de Mantenimiento – Planta Industrial MultinacionalDesde CONA Consultores acompañamos a una importante empresa multinacional en la apertura de su nueva planta productiva en Santiago del Estero, y estamos buscando un/a Supervisor/a de Mantenimiento para sumarse al proyecto.Si te motiva ser parte de un desafío en crecimiento, en una compañía de primer nivel, ¡esta es tu oportunidad!🔧 Responsabilidades principales Coordinar y controlar las tareas de mantenimiento edilicio y de equipos productivos. Garantizar el cumplimiento de normas de Calidad, Seguridad, Higiene y Medio Ambiente. Supervisar el orden y la limpieza del sector según estándares establecidos. Ejecutar y controlar el plan de mantenimiento preventivo y correctivo, junto a las áreas operativas. Controlar la utilización y preservación del herramental. Elaborar croquis de piezas y repuestos conforme a los procedimientos corporativos. Participar en proyectos de mejora continua que incrementen la eficiencia de los equipos. Coordinar y supervisar proveedores externos de obras y servicios. Gestionar cotizaciones de repuestos y servicios. Cumplir y hacer cumplir políticas, normas y procedimientos de seguridad y calidad.🎓 Requisitos Formación: Secundario técnico completo (Electromecánico o afines). Experiencia: Mínimo 3 años en mantenimiento industrial. Experiencia en gestión de pañol. Lectura de planos eléctricos y mecánicos. Conocimientos en contactores, guardamotores, variadores, PLC. Habilidad en montaje de reductores, reemplazo de rodamientos y soldaduras básicas. Manejo de instrumentos de medición (voltímetro, amperímetro). Manejo de Microsoft Office. Idioma inglés y/o italiano (valorado).💡 Competencias valoradas Liderazgo y trabajo en equipo. • Compromiso, autonomía y capacidad de gestión. • Visión preventiva y enfoque en seguridad. • Comunicación clara y efectiva. • Capacidad para identificar peligros y evaluar riesgos laborales.📋 Condiciones de contratación Jornada: Central full time, de 8 a 17 hs. Flexibilidad horaria para atender necesidades operativas. Modalidad: Presencial. Lugar: Santiago del Estero – La Banda, Parque Industrial.🌟 La empresa ofrece Comedor en planta / servicio de vianda. Prepaga de primer nivel. Paquete de beneficios corporativos. Oportunidades de crecimiento y desarrollo profesional. Ser parte del inicio de una nueva planta industrial en plena expansión.⚠️ Importante: En CONA Consultores siempre te contactaremos desde plataformas oficiales o mails corporativos. Nunca solicitamos fotos de DNI ni documentación personal. El empleador solo podrá pedirte la información estrictamente necesaria para el desempeño del trabajo (Ley 6471-21 GCBA).', 0, 'La Banda, Santiago del Estero', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 10:23:47', '09-04-2026 11:17:29', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 16, 70, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_1478000_bum_vcc157e48.jpg', 0, 0, 3.13, 70, 'Simples', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224777.html', '2026-04-10T07:05:55.104689');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224755, NULL, 'Supervisor/a de Mantenimiento para Empresa Multinacional de consumo masivo con planta en GBA sur', 'Confidencial', 'Empresa Multinacional líder en la Industría de consumo masivo busca Supervisor/a de Mantenimiento para su planta ubicada en zona sur de GBA - LONGCHAMPS.Nos orientamos a técnicos con sólida experiencia en mantenimiento electromecánico, eléctrico, electrónico PLC y mecánico a nivel industrial, lectura de planos, manejo de costos, conocimientos de equipos industriales grandes. Deberá ser idoneo en el área de mantenimiento y tener nociones de producción en industrias.(pymes o grandes) Se valorará haya ocupado posiciones de supervisor o encargado de mantenimiento, no exluyente.Valoraremos el conocimiento de industrias multinacionales, de consumo masivo, metalúrgicas, fundiciones, autopartistas u otras afines. Se requieren competencias: relaciones interpersonales, compromiso, trabajo en equipo, organización y capacidad de aprendizaje.Trabajara en ROTATIVO. Se ofrece puesto efectivo, muy buenas condiciones de contratación, capacitación en la Compañia y posibilidades de crecimiento y desarrollo en una Empresa en proceso de Expansión.', 1, 'Burzaco, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 10:08:37', '09-04-2026 10:08:37', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 16, 70, 1, NULL, NULL, NULL, NULL, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224755.html', '2026-04-10T07:05:55.104800');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118222885, 10165481, 'Telemarketer de Cobranzas', 'ASOCIACION MUTUAL DE LA ECONOMIA SOLIDARIA', 'BÚSQUEDA LABORAL: Operador/a de Cobranzas y Gestión de MoraAsociación Mutual de la Economía Solidaria (AMES), Mutual ubicada en Capital Federal, se encuentra en la búsqueda de perfiles para el área de Cobranzas telefónicas.Requisitos de la búsqueda: Experiencia comprobable en Call Center de cobranzas (Excluyente). Excelente dicción, capacidad de negociación y orientación a resultados. Perfiles proactivos, responsables y con marcada puntualidad. Contar con PC o Laptop propia en condiciones operativas. Residencia en CABA y disponibilidad de incorporación inmediata.Principales responsabilidades: Gestión de mora temprana y tardía vía telefónica y digital. Registro de gestiones en sistema interno y seguimiento de promesas de pago.Condiciones de contratación: Jornada laboral: 6 horas diarias (Lunes a Viernes). Zona de trabajo: Capital Federal (Microcentro). Modalidad: Hibrida.', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Part-time', '08-04-2026', '08-04-2026 10:37:25', '09-04-2026 09:24:04', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 25, 110, 1, NULL, 0, 0, NULL, 40, 'Destacados', 'bumeran', 'destacado', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118222885.html', '2026-04-10T07:05:55.104984');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2179299, 570364, 'Desarrollador Node Js Ssr - Mix (Onsite - Remoto) - 1807', 'Aliantec', '¿Qué hace la compañía?Empresa tecnológica con sólida proyección en el mercado, especializada en el desarrollo de soluciones SaaS para la gestión integral de flotas y equipos pesados en la industria de la construcción. Se destaca por su enfoque estratégico orientado a datos, innovación constante y compromiso con la optimización operativa y financiera de sus clientes.¿Qué necesitás para ser parte del equipo?A nivel personal: Capacidad para trabajar con requerimientos abiertos o en evolución. Buen criterio técnico para tomar decisiones y explicar trade-offs. Mentalidad de producto y foco en impacto real. Buena comunicación y predisposición para trabajar en equipo reducido. Autonomía, criterio técnico y capacidad de ejecución.A nivel técnico: Experiencia de +3 años en desarrollo Backend con Node.js participando en entornos productivos. Dominio avanzado de TypeScript y buenas prácticas asociadas. Experiencia sólida en diseño y modelado de bases de datos relacionales, preferentemente PostgreSQL, incluyendo optimización de queries y manejo eficiente de transacciones. Experiencia en diseño, desarrollo y documentación de APIs, idealmente bajo paradigma GraphQL. Sólidos conocimientos de principios de diseño de software, patrones de arquitectura backend y modelado de dominio. Manejo de Git y experiencia trabajando con flujos colaborativos (PRs, code review, branching strategies). Si cuentas con experiencia previa en productos SaaS, startups o entornos orientados a producto, ¡es un plus!¿Qué vas a hacer?Diseñar, desarrollar y evolucionar APIs backend robustas, seguras y escalables, asegurando alta performance y mantenibilidad. Implementar y modelar lógica de negocio compleja, vinculada a: - Gestión de uso, disponibilidad y trazabilidad de maquinaria. - Procesamiento de telemetría y eventos en tiempo real. - Generación de reportes, métricas y agregaciones de datos. - Sistemas de autenticación, autorización, roles y permisos. Diseñar y optimizar modelos de datos en PostgreSQL, garantizando integridad, consistencia y eficiencia en consultas de alto volumen. Participar activamente en decisiones de arquitectura, escalabilidad y performance, proponiendo mejoras técnicas continuas. Escribir código limpio, testeable y alineado a buenas prácticas (testing, code reviews, estándares de calidad). Colaborar en la definición técnica y estimación de nuevas funcionalidades, trabajando de forma cercana con producto y stakeholders. Identificar, diagnosticar y resolver problemas de performance, concurrencia y consistencia de datos. Contribuir al crecimiento técnico del equipo, promoviendo estándares, buenas prácticas y mejoras en los procesos de desarrollo.¿Cuál es el desafío de la posición?Como Desarrollador Node JS Ssr, tendrás el desafío de diseñar, desarrollar y evolucionar los servicios core de una plataforma SaaS orientada a datos, garantizando performance, escalabilidad y solidez técnica en cada solución. Ademas, liderarás la construcción de nuevas funcionalidades backend, optimizarás arquitecturas existentes y participarás activamente en decisiones técnicas clave,desde el diseño de APIs hasta la definición de estándares y buenas prácticas. Buscamos un perfil con mentalidad de ownership, foco en calidad de código y capacidad para transformar desafíos complejos en soluciones simples, robustas y escalables.¿Con quién trabajarás?Cuenta con un equipo altamente orientado a producto, con foco en calidad técnica, escalabilidad y desarrollo de soluciones que responden a desafíos reales del negocio en entornos industriales exigentes.¿Cuándo y dónde trabajarás?Trabajarás de lunes a viernes, de 9 hs a 18 hs, con flexibilidad para asistir a las oficinas ubicadas en Retiro (CABA).¿Qué ofrecen? Modalidad Contractor Salario en USD¿De qué fases consta el proceso de selección?Tendrás una primera entrevista con nuestra Recruiter, Melina Rubio, para conocer tus experiencias laborales e intereses. Luego, con la empresa empleadora tendrás una instancia para conocer al equipo y luego otra instancia técnica.', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '09-04-2026', '09-04-2026 16:41:52', '09-04-2026 16:41:52', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 19, 2621, 1, 'https://imgzj.jobscdn.com/portal/img/empresas/1/static/logoMainPic_570364_bum_v183b0a04.jpg', 0, 0, NULL, 1020, 'Aviso Select', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2179299.html', '2026-04-10T07:05:55.105176');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118219563, 444640, 'Operarios/as para carga y descarga de contenedores Zona Norte', 'Grupo Gestión', 'Importante centro de Distribucion ubicado en la Zona Norte, se encuentra en busqueda de Operarios/as de deposito para realizar tareas generales de deposito, de carga y descargaSe requiere contar con disponibilidad full time e inmediataTrabajo discontinuo, por convocatoriaEsperamos tu postulación!!!', 0, 'Tortuguitas, Buenos Aires', 'Presencial', 'Full-time', '06-04-2026', '06-04-2026 12:31:03', '07-04-2026 09:54:53', '2026-04-06', NULL, NULL, '2026-04-06T00:00:00-03:00', NULL, NULL, 6, 0, 3, 2638, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_444640_bum_vce78c1c9.jpg', 1, 0, 4.02, 70, 'Simples', 'bumeran', 'simple', 1, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118219563.html', '2026-04-10T07:05:55.105331');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118223054, 10116908, 'Diseñadora Gráfica SR - NÚÑEZ (CABA)', 'MJ Consultores', 'Para empresa Pyme ubicada en Núñez nos encontramos en la búsqueda de una Diseñadora Gráfica SR que resida en zonas aledañas.Responsabilidades Principales: Diseñar materiales de comunicación institucional, comercial y de apoyo área comercial (folletería, catálogos, presentaciones, materiales de capacitación, etc.). Adaptar piezas gráficas a distintos formatos y públicos, garantizando la correcta aplicación de la identidad visual de cada marca. Participar en el diseño y desarrollo de packaging para productos del portafolio local. Preparar archivos finales para impresión y coordinar con proveedores externos los procesos de producción (material POP, impresos, displays, cartelería, etc.). Colaborar estrechamente con el equipo de marketing y otras áreas internas para interpretar necesidades, proponer soluciones visuales y cumplir con los tiempos establecidos. Mantener actualizado el banco de materiales gráficos y plantillas corporativas. Asegurar la calidad técnica y estética de todas las piezas antes de su entrega o publicación.Requisitos del Puesto: Graduada/o en Diseño Gráfico o carrera afín. Experiencia mínima de 4 años en funciones de diseño dentro de áreas de marketing, agencias o estudios. Deseable experiencia previa en sectores de salud o consumo masivo. Dominio avanzado de Adobe Illustrator, Photoshop y/o InDesign (u otros programas de diseño equivalentes). Conocimientos de procesos de impresión y producción gráfica. Deseable experiencia en diseño de packaging. Se valorará contar con una excelente ortografía y redacción.MODALIDAD HIBRIDA 3 X 2 (3 dias presencial y 2 de HO), de 9 a 18 hs - Núñez', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '08-04-2026', '08-04-2026 11:48:42', '09-04-2026 12:50:24', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 31, 2587, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/0/0/1/0/1/1/6/9/0/8/logoMainPic_10116908.jpg', 0, 0, 4.25, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118223054.html', '2026-04-10T07:05:55.105486');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225702, 2073200, 'Asesor de servicios de chapa y pintura (Nuñez y alrededores)', 'GI GROUP Argentina', 'Unimos Buenas Personas, con Buenas Empresas.Somos una consultora de Recursos Humanos de origen italiano con más de 15 años en el país. Aportamos valor en la selección y tercerización responsable de recursos humanos.Trabajamos con empresas de primera línea, generalmente internacionales, buscando perfiles profesionales, técnicos y de alta gerencia. Proveemos servicios de seleccón, personal eventual y tercerización. Somos #SIMPLES / HUMANOS / EXPERTOSVÁLIDO PARA NUESTROS AVISOS EN CIUDAD DE BUENOS AIRES:Búsqueda laboral equitativa. El empleador solo podrá solicitarle la información estrictamente necesaria para el desempeño en el trabajo que se ofrece (Ley 6471). Para nuestro importante cliente concesionario dedicado a distribución de productos y vehículos de primera marca, ubicada en Nuñez, nos encontramos en la búsqueda de un Asistente de servicios de chapa y pintura, para sumar a su equipo de trabajo.Las principales responsabilidades serán:• Coordinar la inspección de los vehículos siniestrados.• Cotizar servicios de chapa y pintura.• Coordinar turnos del servicio de chapa y pintura.• Brindar atención al cliente e ingresar el vehículo al taller, de acuerdo con los procedimientos establecidos.• Solicitar los repuestos necesarios para los servicios de chapa y pintura.• Dar curso a las órdenes de reparación, gestionar los procesos involucrados y coordinar plazos de entrega.• Coordinar la entrega y el retiro de los vehículos.• Facturar y cobrar los servicios realizados. Requisitos: • Experiencia en posiciones similares en concesionarios de alta gama.• Residir en zonas aledañas a Núñez.• Disponibilidad horaria full-time.• Secundario técnico (no excluyente).• Experiencia y/o conocimiento en chapa y pintura; gestión de tiempos y volúmenes de trabajo.• Manejo de compañías de seguros. Beneficios Jornada Laboral: Lunes a Viernes de 8 a 18hs (1 hora de almuerzo) o de a 18hs (30 min de almuerzo). Convenio SMATA. Capacitaciones vinculadas al área.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 16:08:59', '09-04-2026 16:09:00', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 1, 22, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_2073200_bum_v6d4c351c.jpg', 1, 0, 3.14, 70, 'Simples', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225702.html', '2026-04-10T07:05:55.105654');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2179141, 569454, 'Diseñadora Gráfica SR - NÚÑEZ (CABA)', 'MJ Consultores', 'Para empresa Pyme ubicada en Núñez nos encontramos en la búsqueda de una Diseñadora Gráfica SR que resida en zonas aledañas.Responsabilidades Principales: Diseñar materiales de comunicación institucional, comercial y de apoyo área comercial (folletería, catálogos, presentaciones, materiales de capacitación, etc.). Adaptar piezas gráficas a distintos formatos y públicos, garantizando la correcta aplicación de la identidad visual de cada marca. Participar en el diseño y desarrollo de packaging para productos del portafolio local. Preparar archivos finales para impresión y coordinar con proveedores externos los procesos de producción (material POP, impresos, displays, cartelería, etc.). Colaborar estrechamente con el equipo de marketing y otras áreas internas para interpretar necesidades, proponer soluciones visuales y cumplir con los tiempos establecidos. Mantener actualizado el banco de materiales gráficos y plantillas corporativas. Asegurar la calidad técnica y estética de todas las piezas antes de su entrega o publicación.Requisitos del Puesto: Graduada/o en Diseño Gráfico o carrera afín. Experiencia mínima de 4 años en funciones de diseño dentro de áreas de marketing, agencias o estudios. Deseable experiencia previa en sectores de salud o consumo masivo. Dominio avanzado de Adobe Illustrator, Photoshop y/o InDesign (u otros programas de diseño equivalentes). Conocimientos de procesos de impresión y producción gráfica. Deseable experiencia en diseño de packaging. Se valorará contar con una excelente ortografía y redacción.MODALIDAD HIBRIDA 3 X 2 (3 dias presencial y 2 de HO), de 9 a 18 hs - Núñez', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 11:54:37', '08-04-2026 13:46:42', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 31, 2587, 1, 'https://imgzj.jobscdn.com/portal/img/empresas/1/static/logoMainPic_569454_bum_v2db202f6.jpg', 0, 0, NULL, 1020, 'Aviso Select', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2179141.html', '2026-04-10T07:05:55.105802');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2178853, 658286, 'Encargado de servicio de alimentaciòn, Nutricionista', 'Betina Stancanelli', 'Importante Instituciòn de salud de CABA se encuentra en la bùsqueda de 1 ENCARGADO DE SERVICIO DE ALIMENTACIÒN para su turno SADOFE.Tareas:Gestión Operativa: Supervisar y controlar el servicio de alimentación en todas sus etapas.Planificar y gestionar el flujo de trabajo (mosaicos y comandas) a través del sistema de gestión (Sistema Felix).Calidad y Seguridad Alimentaria: Asegurar la correcta implementación de las Buenas Prácticas de Manufactura (BPM). -Analizar y supervisar el cumplimiento de los menús pautados, controlando la calidad y cantidad de la materia prima y los platos finales.Gestión de Equipo: Coordinar, capacitar y acompañar al personal operativo a cargo, fomentando un clima de trabajo colaborativo y eficiente.Control Administrativo: Informar de manera diaria las novedades del personal y del servicio, tanto en formato físico como digital, asegurando la trazabilidad de la gestión.Enfoque al Residente: Velar por el cumplimiento de los estándares de servicio para garantizar una experiencia alimentaria óptima y segura para cada paciente.Requisitos:Estudios: - Lic. en Nutrición (excluyente contar con título y matrícula habilitante vigente)Otros conocimientos: - Manejo de herramientas informáticas. - Sistemas de gestión de alimentación.Experiencia mìnima: 2 años en posiciones de supervisión en servicios gastronómicos industriales o institucionales (clínicas, hospitales o residencias)Ofrecemos:Relaciòn de dependenciaHorario: SADOFE 7 a 21 hs', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '04-04-2026', '04-04-2026 11:39:26', '08-04-2026 12:27:37', '2026-04-04', NULL, NULL, '2026-04-04T00:00:00-03:00', NULL, NULL, 1, 0, 23, 2657, 1, NULL, 0, 0, NULL, 70, 'Avisos Classic', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2178853.html', '2026-04-10T07:05:55.105941');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118222860, 13379431, 'Dirección de obra', 'Proyecto Sur', 'BÚSQUEDA LABORAL – DIRECTOR DE OBRA Nos encontramos en la búsqueda de un DIRECTOR DE OBRA para incorporarse a nuestro equipo y participar en el seguimiento y coordinación de proyectos. Principales responsabilidades: * Seguimiento y control de planos en todas las fases del proyecto * Supervisión de contratistas en obra * Cálculo y cómputo de materiales * Coordinación y seguimiento de proveedores y contratistas * Elaboración de cómputos y presupuestos • Registro de información de obra y actualización de documentación técnica * Elaboración y corrección de planos en AutoCAD ( 2D y 3D), Revit y SketchUp Requisitos: * Graduado/a de Arquitectura o Ingeniería Civil * Manejo avanzado de AutoCAD * Experiencia en dirección o supervisión de obra * Conocimientos en cómputo y cálculo de materiales * Capacidad para trabajar en equipo y resolver problemas técnicos en obra * Licencia de conducir vigente Se valorará: * Buenas habilidades de organización y seguimiento * Experiencia previa en proyectos similares * Disponibilidad inmediata Modalidad de trabajo: * Jornada completa – presencial Modalidad de contratación: Contratado', 0, 'Florencio Varela, Buenos Aires', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 14:37:21', '09-04-2026 12:02:05', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 4, 2642, 1, NULL, 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118222860.html', '2026-04-10T07:05:55.106082');
