3:14:59', '09-04-2026 23:14:59', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 30, 2581, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_171580_bum_vdb1240d3.jpg', 0, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118226413.html', '2026-04-10T07:05:55.106607');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118223816, 13381134, 'Analista Técnico de Obras - Florida', 'IngeJons', 'Nos encargamos del proceso de búsqueda, selección y contratación de personal técnico para fabricas y empresas de ingeniería. Realizamos procesos de evaluación técnica de acuerdo a las necesidades del puesto a cubrir. Cubrimos posiciones para diferentes niveles en áreas de Producción, Mantenimiento, Calidad, Operaciones, Procesos, ingeniería, Supply Chain, Customer Service, Logística, Seguridad & Higiene, Compras y Ventas Técnicas. Importante empresa especializada en obras de ingeniería y construcción incorpora un Analista Técnico de Obras. Tendrá como objetivo evaluar técnica y económicamente obras del sector farmacéutico, participar en licitaciones, realizar cómputos y presupuestos, y brindar soporte al equipo de obras y proyectos.Nos orientamos a un perfil organizado, analítico y resolutivo, con buena comunicación y criterio para generar soluciones. ️ Principales responsabilidades Analizar pliegos, planos y documentación técnica. Realizar cómputos y presupuestos completos de obras. Hacer cálculos básicos estructurales (flexión, compresión). Leer y revisar planos eléctricos, termomecánicos y estructurales. Relevar obras y evaluar la viabilidad del proyecto. Solicitar y comparar cotizaciones de proveedores. Elaborar informes técnicos y cronogramas (Project). Dar soporte técnico al equipo de obra durante la ejecución. Ordenar documentación y seguimiento post-licitación. Requisitos Formación: estudiantes avanzados de Arquitectura o Ingeniería Civil; también se considerarán perfiles técnicos afines (Técnico electromecánico, Maestro Mayor de Obras, Técnico en Mantenimiento Industrial, etc.) Experiencia: mínimo 2 años en obras, presupuestos o áreas técnicas. Conocimientos en instalaciones termomecánicas, eléctricas y sanitarias. Lectura de planos unifilares, tableros, cómputos y cálculos básicos estructurales. Manejo avanzado de Excel, AutoCAD y Microsoft Project. Experiencia en industria farmacéutica o industrial (deseable). Horario: lunes a viernes de 8 a 17 hs (presencial) y algunos sábados de 08 a 14hs (remoto) Licencia de conducir vigente y residencia en AMBA. La empresa ofrece Crecimiento y proyección dentro del área técnica. Equipo joven, dinámico y con fuerte enfoque en ingeniería farmacéutica. Requisitos:', 0, 'Florida Oeste, Buenos Aires', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 15:19:04', '08-04-2026 15:19:04', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 4, 2390, 1, NULL, 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118223816.html', '2026-04-10T07:05:55.106718');
