ires', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 13:00:44', '09-04-2026 12:37:55', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 1, 22, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_1127240_bum_vd8d10d9e.jpg', 1, 1, 4.08, 70, 'Simples', 'bumeran', 'simple', 1, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118223363.html', '2026-04-10T07:05:55.107473');
