INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118219974, 13369501, 'Oficial Albañil', 'LUIS FRONTERA', 'Oficial Albañil Resumen del Puesto Estamos en la búsqueda de un Oficial Albañil con experiencia comprobable en colocación y albañilería en general. Se valorará la proactividad y el compromiso con la calidad del trabajo. Responsabilidades Realizar trabajos de albañilería en general, incluyendo colocación de ladrillos, revoques, contrapisos, etc. Interpretar planos y especificaciones técnicas. Mantener el orden y la limpieza del área de trabajo. Colaborar con otros oficios en la obra. Cumplir con las normas de seguridad e higiene. Requisitos Experiencia previa demostrable como Oficial Albañil. Conocimientos sólidos en técnicas de construcción y materiales. Capacidad para trabajar en equipo y seguir instrucciones. Responsabilidad y compromiso con las tareas asignadas. Disponibilidad para trabajar en proyectos de construcción.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '06-04-2026', '06-04-2026 14:52:27', '06-04-2026 14:52:27', '2026-04-06', NULL, NULL, '2026-04-06T00:00:00-03:00', NULL, NULL, 1, 0, 22, 36, 1, NULL, 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118219974.html', '2026-04-10T07:05:55.107874');
