INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224715, 1118240, 'Oficial Electricista / Instrumentista - La Plata', 'Cubi HR', 'En CUBI HR – Capacidad de Conectar® nos encontramos en la búsqueda de un Oficial Electricista / Instrumentista para sumarse al equipo de nuestro cliente: Gleba, un reconocido Holding de Servicios Agroambientales con una sólida trayectoria en el mercado.Gleba forma parte del holding internacional Anasac y cuenta con un equipo local de más de 120 colaboradores comprometidos con la innovación, la calidad y la sostenibilidad.Nuestra búsqueda se orienta a una posición técnica y operativa, orientada al mantenimiento de instalaciones eléctricas industriales y sistemas de instrumentación y control de maquinaria de producción. Principales responsabilidades del rol: Ejecutar el mantenimiento correctivo y preventivo en las disciplinas de instrumentación y control de maquinaria de producción. Realizar mantenimiento de instalaciones eléctricas industriales de baja tensión. Intervenir sobre máquinas de producción como envasadoras y etiquetadoras. Configurar, calibrar y reparar equipos e instrumentos de control de campo. Trabajar en conjunto con el área mecánica para garantizar la continuidad operativa de las máquinas. Diagnosticar fallas técnicas en sistemas eléctricos, de control e instrumentación. Requisitos: Para esta posición se requiere contar con: Formación como Técnico electromecánico, electricista o electrónico. Experiencia comprobable en configuración, calibración y reparación de máquinas de producción, PLC, instrumentación y control de campo, motores e instalaciones eléctricas industriales en baja tensión. Conocimientos en control neumático. Residencia en La Plata o zona sur de AMBA (excluyente) Movilidad propia (preferente) Lugar de trabajo: La Plata (Melchor Romero) Jornada laboral: Presencial, en jornada fija de 8hs. de Lunes a Viernes (con posibilidad realizar horas extras si deseara) Beneficios ​​​​​​ Te contamos algunos de los beneficios de esta posición: Kit escolar Comedor en Planta Seguro de vida adicional', 0, 'La Plata, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 08:55:45', '09-04-2026 08:55:45', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 22, 36, 1, NULL, 0, 0, NULL, 2013, 'Simples Hiring Room 30-60', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224715.html', '2026-04-10T07:05:55.108053');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224605, 13373357, 'Oficial de mantenimiento zona Garin', 'vril', 'Nos encontramos en busqueda de un perfil de mantenimiento para una empresa del rubro plastico en la zona de Garin. Tareas a realizar: Experiencia excluyente en mantenimiento preventivo, correctivo y predictivo en sistemas mecánicos, eléctricos y neumáticos. Mantenimiento Preventivo: Ejecutar mantenimiento preventivo en compresoras impresoras y equipos auxiliares de planta. Mantenimiento Correctivo: Diagnosticar y reparar fallas mecánicas, eléctricas y neumáticas en equipos de compresión e impresión, en línea de producción, para restablecer condiciones operativas en el menor tiempo posible. Diagnóstico técnico y análisis de fallas: Analizar desvíos operativos (presión, temperatura, variadores, PLC, calidad de impresión) para identificar causa raíz y proponer acciones correctivas. Requisitos: Secundario completo: Tecnico electromecanico Manejo de pc nivel intermedio 3 años de experiencia en posiciones similares Movilidad propia', 0, 'Garin, Buenos Aires', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 22:29:11', '08-04-2026 22:29:12', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 16, 70, 1, NULL, 0, 0, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224605.html', '2026-04-10T07:05:55.108121');
