', 1, 'Escobar, Buenos Aires', 'Presencial', 'Full-time', '07-04-2026', '07-04-2026 10:35:27', '07-04-2026 10:36:19', '2026-04-07', NULL, NULL, '2026-04-07T00:00:00-03:00', NULL, NULL, 5, 0, 3, 2638, 1, NULL, NULL, NULL, NULL, 70, 'Simples', 'bumeran', 'simple', 1, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118221035.html', '2026-04-10T07:05:55.110195');
