6', '06-04-2026 10:06:26', '2026-04-06', NULL, NULL, '2026-04-06T00:00:00-03:00', NULL, NULL, 1, 0, 16, 32, 1, NULL, 0, 0, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118219210.html', '2026-04-10T07:05:55.110322');
