INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224725, 475280, 'Operario de Mantenimiento Electrico', 'Laboratorios Raffo', 'Adium es una compañía farmacéutica líder en Latinoamérica con 50 años de experiencia y crecimiento sostenido en la región. Nuestro propósito es acercar tratamientos innovadores para mejorar la calidad de vida en Latinoamérica. A través de sólidas alianzas, somos licenciantes de más de una decena de compañías multinacionales de innovación, lo que nos permite acercar terapias y tratamientos de vanguardia para enfrentar las enfermedades más desafiantes del mundo. Contamos con centros productivos en 5 países: Argentina, Brasil, México, Paraguay y Uruguay, donde investigamos, desarrollamos y elaboramos más de 120 millones de unidades de productos propios de alta calidad. Esto nos permite ampliar el acceso a la salud, mejorando la vida de millones de personas en toda la región. Para obtener más información sobre el grupo Adium: https://adiumpharma.com/ Ejecutar las tareas eléctricas/electrónicas de los Mantenimiento de los equipos de manufactura y servicios según Procedimientos Operativos Asiste y efectúa las actividades de organización, coordinación y seguimiento de tareas del área de Mantenimiento) Mantenimiento y operación de grupos electrógenos y UPS Brindar asistencia a servicios generales, dar soporte al manejo y operación del sistema HVAC, agua caliente/fría y vapor, HVAC confort. Manejo de documentación (Log books, ordenes de trabajo, documentación técnica. Colabora con el seguimiento de actividades referidos a Controles de cambio y Desvios de Calidad Identifica y participa activamente en el diseño, coordinación e implementación de oportunidades de mejora y proyectos de gran impacto en la compañía Colabora en actividades relacionadas a Seguridad e Higiene: inspecciones planificadas, auditorias LOTO, redacción de procedimientos, etc Realiza seguimiento de reparaciones y/o fabricación de partes tanto de clientes internos como proveedores externos. Participar prácticas de GEO: 5S, Resolución de Problemas: Análisis de causa raiz Requisitos: Será excluyente contar con analítico del secundario completo. Conocimiento en maquinas de procesos productivos y maquinas de acondicionamiento y de servicios en industrias farmaceuticas, alimenticia y/o cosméticas. (Excluyente) Conocimientos GMP (Excluyente) Conocimientos de electrónica (Deseable) Beneficios 21 dias de Vacaciones Refrigerios Comedor en planta', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 09:26:57', '09-04-2026 09:26:57', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 22, 2610, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/0/0/0/0/4/7/5/2/8/0/logoMainPic_475280.jpg', 1, 0, NULL, 10, 'Home', 'bumeran', 'home', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224725.html', '2026-04-10T07:05:55.110475');
