ial', 'Full-time', '08-04-2026', '08-04-2026 18:10:05', '09-04-2026 12:51:09', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 30, 0, 3, 2638, 1, NULL, 0, 0, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224220.html', '2026-04-10T07:05:55.110697');
