INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118223837, 256360, 'Recepcionista part time', 'Fleni', '📢¡Te estamos buscando!En FLENI nos encontramos en la búsqueda de un/a Recepcionista part time para incorporar al equipo en nuestra sede de Belgrano.Nuestra búsqueda se orienta a perfiles con experiencia en atención al paciente y tareas administrativas, con marcada orientación al servicio.🔍¿Cuáles serán tus responsabilidades?La posición implica brindar atención al paciente a través de los distintos canales de contacto de la institución, gestionando turnos, consultas y requerimientos tanto del área médica como administrativa. Entre sus tareas se incluyen la validación y carga de datos en sistema, realización de prefacturación y presupuestos, así como la gestión de agendas médicas (confirmaciones, cancelaciones y reprogramaciones).💡¿Qué esperamos de vos?* Experiencia en posiciones similares.* Buen manejo de herramientas informáticas.* Excelentes habilidades de comunicación y trato con pacientes.🕐Lunes a viernes de 16.00 a 20.00 hs📍¿Dónde estamos? Montañeses 2325, Belgrano.Si te sentís identificado/a con el puesto y cumplís con los requisitos, ¡postulate para que podamos conocerte!', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 15:29:28', '08-04-2026 16:04:49', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 26, 2380, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_256360_bum_vb26b490.jpg', 1, 0, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118223837.html', '2026-04-10T07:05:55.111260');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118220218, 2205320, 'Promovendedor Part time', 'Suministra', 'Importante cadena de hipermercados se encuentra en la búsqueda de personal para desarrollarse como vendedor/a PART TIME de los productos financieros (tarjeta) que la empresa ofrece a sus clientes. Las vacantes a cubrir son para desarrollarse en la zona de La Plata aunque también se requerirá visitar locales o zonas aledañas a la mencionada Requisitos Sexo: indistinto Secundario finalizado sin adeudar materias y con analítico en mano (o certificado de titulo en trámite 2026) Disponibilidad para turnos rotativos que cambian semanalmente, fines de semana y feriados. Experiencia en venta (Ideal de productos intangibles - tarjetas - créditos - etc) Actitud proactiva y con muchas ganas de aprender Residir en la zona o cercanías', 0, 'La Plata, Buenos Aires', 'Presencial', 'Part-time', '06-04-2026', '06-04-2026 16:43:57', '06-04-2026 16:43:57', '2026-04-06', NULL, NULL, '2026-04-06T00:00:00-03:00', NULL, NULL, 1, 0, 6, 35, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_2205320_bum_v84d969b6.jpg', 1, 0, 4.05, 70, 'Simples', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118220218.html', '2026-04-10T07:05:55.111322');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224727, 13508887, 'Administrativo Estación de Servicio Part-Time', 'COMBUSTIBLES DEL NORTE S.A.', 'CN GRUPO nace como una empresa familiar y cuenta con más 35 años de trayectoria, mas de 270 colaboradores y 11 bases operativas distribuidas en puntos estratégicos de Salta y Región I y V de Chile.En el transcurso de nuestro desarrollo empresario hemos ido diversificando negocios, apostando siempre a la innovación, al desarrollo profesional de nuestros equipos y a las relaciones estratégicas con nuestros proveedores, clientes y comunidad. ¡Sumate a un equipo donde tus ideas y tu impacto cuentan!Buscamos Administrativo Part Time, Estación de Servicio Tartagal . Realizar cierres de cajas diarios. Preparar reportes administrativos y colaborar en conciliaciones. Gestión de cuentas corrientes. Depósitos bancarios. Control de cargas y cierres, siguiendo los procesos establecidos. Colaborar en auditorías internas. Requisitos: Residencia en Tartagal (excluyente) Formación en administración, contabilidad o carreras afines 1 a 2 años en tareas administrativas, de control o soporte operativo. Manejo de Excel y sistemas de gestión.', 0, 'Tartagal, Salta', 'Presencial', 'Part-time', '09-04-2026', '09-04-2026 09:29:58', '09-04-2026 09:29:58', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 1, 22, 1, NULL, NULL, NULL, NULL, 2013, 'Simples Hiring Room 30-60', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224727.html', '2026-04-10T07:05:55.111391');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118219796, 13510488, 'Responsable de implementación de Software (Part-Time) REMOTO', 'musapp', 'Responsable de Implementación (Part-Time)Resumen del PuestoEstamos en la búsqueda de un estudiante de Ciencias Económicas con interés en iniciarse en el ámbito tecnológico, aplicando sus conocimientos en procesos de negocio reales. Esta es una excelente oportunidad para adquirir experiencia en una empresa de desarrollo de software en crecimiento.Responsabilidades Capacitar a nuevos clientes para el uso de la aplicación. Apoyar en la gestión y optimización de procesos internos. Utilizar herramientas digitales para el análisis y seguimiento de información. Contribuir con la edición básica de material audiovisual para comunicación interna o externa. Mantener una comunicación fluida con los diferentes equipos de trabajo.Requisitos Estudiante de carreras como Administración, Contabilidad o afines. Demostrar buen criterio administrativo. Manejo de herramientas digitales y ofimáticas. Conocimientos básicos en edición de video (ej. CapCut, Canva). Habilidades de comunicación. Se valorará el interés por aprender sobre sistemas, procesos de negocio y ventas. Proactividad y ganas de aprender y crecer profesionalmente.Condiciones Modalidad de trabajo part-time ( 2 horas diarias, por la mañana). Remuneración: base mensual más componente variable por implementación.Posibilidad de crecimiento dentro de la organización! Trabajo 1 0 0% REMOTO', 0, 'Córdoba, Córdoba', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 11:47:27', '08-04-2026 11:47:27', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 25, 2571, 1, NULL, NULL, NULL, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118219796.html', '2026-04-10T07:05:55.111468');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118221213, 13122092, 'Recepcionista Part Time para importante Centro de Estética', 'Fimedical', '¡Únete al Equipo de Fimedical!En Fimedical estamos buscando una recepcionista talentosa y entusiasta que quiera desarrollarse en un entorno innovador y de alta calidad.🔹 Posición: Recepcionista🔹 Ubicación: Vicente López🔹Disponibilidad horaria part time por la tarde y sábados de por medio.🔹 Responsabilidades:Responder llamados, atención personalizada, otorgar turnosManejo de agendasManejo de Caja, transacciones posnet.🔹 Requisitos:Experiencia en atención al cliente.Secundario completo, de preferencia con idioma Inglés.Mujeres entre 20 y 40 años con excelente presencia.Actitud proactiva y excelentes habilidades interpersonales y de comunicación.Capacidad para trabajar en equipo y adaptarse a un entorno dinámico.Preferente manejo sistema SIAP (no excluyente)🔹 Ofrecemos:Formación continua y oportunidades de desarrollo profesional.Un ambiente de trabajo colaborativo y motivador.Acceso a tecnología de punta y procedimientos innovadores.Oportunidades de crecimiento dentro de una empresa en expansión.Si te apasiona la estética y quieres ser parte de un equipo comprometido con la excelencia, ¡queremos conocerte! Envía tu CV y una carta de presentación a¡Esperamos tu postulación!', 0, 'Vicente López, Buenos Aires', 'Presencial', 'Part-time', '07-04-2026', '07-04-2026 12:05:18', '07-04-2026 12:15:07', '2026-04-07', NULL, NULL, '2026-04-07T00:00:00-03:00', NULL, NULL, 1, 0, 26, 2380, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13122092_bum_v8d395d6b.jpg', 0, 0, NULL, 70, 'Simples', 'bumeran', 'simple', 1, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118221213.html', '2026-04-10T07:05:55.111551');
