, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118222478.html', '2026-04-10T07:05:55.111668');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118221358, 13187387, 'Perfumera/Dermoconsejera Part Time Turno Tarde', 'FARMACIA ROMY SA', 'Somos Farmacia Romy. Contamos con una trayectoria de más de 40 años, atendiéndote siempre... los 365 días junto a vos.En nuestra farmacia vas a encontrar:• Asesoramiento profesional responsable• Atención personalizada• Honestidad, lealtad y solidaridad• Productos medicinales de todos los laboratorios.• Un area de perfumeria con personal altamente capacitado en productos de cuidado personal, además de las principales y más reconocidas marcas de belleza y cosmética.Atendemos a todas las obras sociales Nos encontramos en la busqueda de una persona para sumarse al equipo del area de perfumeria. La persona que ocupe la posicion se encargará de la venta en mostrador de: Productos de dermocosmetica (Isdin, Euserin, La Roche-Posay, entre otros) Perfumeria masiva Fragancias nacionales e importadas AccesoriosBuscamos a una persona dinamica proactiva, con marcado perfil de servicio y comercial. Y por sobre todo, muchas ganas de aprender!Jornada PART TIME turno tarde con un franco semanal los dias jueves. Requisitos: Perfil y actitud comercial Conocimientos en lineas de dermocosmetica Conocimientos en tipos de piel para el correcto asesoramiento Experiencia previa en ventas', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Part-time', '07-04-2026', '07-04-2026 12:46:00', '07-04-2026 12:46:00', '2026-04-07', NULL, NULL, '2026-04-07T00:00:00-03:00', NULL, NULL, 1, 0, 23, 2651, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13187387_bum_v1f991a14.jpg', 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118221358.html', '2026-04-10T07:05:55.111807');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225559, 13345666, 'Pasante de Selección', 'JUAN SERIAL DE LA TORRE', 'Nos encontramos en búsqueda interna para la posición de Pasante de Selección.Responsabilidades: Carga de vacantes en Hiring Room y Linkedin. Lectura, evaluación y filtrado de CVs. Screening telefónico con el posible candidato. Asistencia a los selectores en los proceso de selección. Requisitos: Estudiante de la carrera de Recursos Humanos o carreras afines. Experiencia previa en el área (deseable). Manejo de Google Workplace o Paquete Office.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 15:02:03', '09-04-2026 15:02:03', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 17, 2565, 1, NULL, 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225559.html', '2026-04-10T07:05:55.111889');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118223782, 13110138, 'Pastelero /a Senior', 'TABANO DIEGO FERNANDO', 'Para importante empresa gastronómica se encuentra en la búsqueda de Pasteleros/as Senior. Ubicación: Planta en Capital Federal Turno: Tarde – de lunes a sábados, de 14:00 a 22:00 hs Requisitos del perfil Más de 5 años de experiencia comprobable en pastelería profesional. Experiencia idealmente adquirida en hoteles de primera línea y/o en empresas gastronómicas de volumen, tales como cadenas de producción, cafeterías de especialidad o locales con producción centralizada. Sólido dominio de masas hojaldradas. Manejo de máquina laminadora (excluyente). Se valorará especialmente la experiencia en elaboración de macarrones, una de las técnicas más complejas y distintivas de la pastelería. Buscamos personas Con alto nivel técnico y atención al detalle. Organizadas, responsables y con capacidad para trabajar en contextos de producción exigentes. Apasionadas por la pastelería de calidad y la mejora continua. Requisitos:', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 15:04:32', '08-04-2026 15:04:32', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 10, 2350, 1, NULL, 1, 0, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118223782.html', '2026-04-10T07:05:55.111969');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2179093, 515256, 'Chef Pastelero Ejecutivo - PARAGUAY', 'Umano HR', '¡Oportunidad para Chef Pastelero Ejecutivo en reconocida cadena gastronómica en Asunción, Paraguay!Nuestro cliente, una reconocida cadena gastronómica, está en la búsqueda de un Chef Pastelero Ejecutivo, responsable de liderar y desarrollar el área de pastelería a nivel cadena, aportando innovación, estandarización y excelencia en cada punto de venta.Principales responsabilidades: Diseñar y desarrollar la propuesta integral de pastelería y repostería para toda la cadena, alineada a la identidad de la marca y la estacionalidad de los productos. Estandarizar recetas, procesos y presentaciones, asegurando consistencia en todos los locales. Asegurar la producción y despacho en tiempo y forma, garantizando estándares de calidad, presentación y costos. Determinar costos de recetas y productos a comercializar. Supervisar la correcta ejecución de procesos y procedimientos en cada unidad de negocio. Liderar, capacitar y desarrollar a los equipos de pastelería de todos los locales. Detectar oportunidades de mejora e innovación continua en la oferta.Requisitos: Ser profesional gastronómico graduado, con especialización en pastelería. Contar con experiencia previa liderando equipos en hoteles, cadenas gastronómicas o restaurantes de primer nivel. Perfil creativo, estratégico, organizado y con fuerte orientación a resultados.📍 Lugar de trabajo: Paraguay🕐 Horario laboral: Full Time (9 hs diarias) con 4 francos mensualesOfrecemos: Vivienda Alumuerzo / Cena ViáticosSi querés liderar la pastelería de una marca reconocida a nivel cadena y dejar tu huella creativa en cada sucursal, ¡postulá ahora!Ref: Chef Pastelero Ejecutivo Paraguay', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '07-04-2026', '07-04-2026 19:04:58', '07-04-2026 19:04:58', '2026-04-07', NULL, NULL, '2026-04-07T00:00:00-03:00', NULL, NULL, 1, 0, 10, 2350, 1, 'https://imgzj.jobscdn.com/portal/img/empresas/1/static/logoMainPic_515256_bum_v1e6e7e12.jpg', 1, 0, NULL, 1020, 'Aviso Select', 'zonajobs', 'zonajobs', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2179093.html', '2026-04-10T07:05:55.112069');
