INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224712, NULL, 'Personal para de Depósito (Control)', 'Confidencial', 'Nos encontramos en la búsqueda de una colaborador para incorporarse al área de depósito, desempeñándose en funciones de control de inventario y/o recepción de mercadería.Requisitos: Secundario completo (excluyente). Experiencia previa en tareas de logística, depósito o almacén. Manejo de sistemas de gestión (WMS) y herramientas informáticas, especialmente Excel. Capacidad de organización y atención al detalle.Se valorará: Conocimientos en recepción, despacho y control de mercadería. Experiencia en conteos cíclicos de inventario. Perfil proactivo, responsable y orientado a resultados.Principales tareas: Control de ingreso y egreso de mercadería. Verificación de documentación y stock. Registro de movimientos en sistema. Participación en inventarios y auditorías internas.Ofrecemos: Incorporación inmediata. Buen clima laboral. Posibilidades de desarrollo dentro de la empresa.Zona de trabajo: Moreno.', 1, 'Moreno, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 08:07:18', '09-04-2026 10:53:31', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 3, 2638, 1, NULL, NULL, NULL, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224712.html', '2026-04-10T07:05:55.112633');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118221816, 13284646, 'empleada administrativa/secretaria', 'Yamila PAGURA', 'Empleada administrativa y secretaria. atención cliente, tanto telefónicamente como por watsap. Organizacion integral del area administrativa del estudio. seguimiento reclamos administrativos, y trámites variados. El horario es de 10 a 18 con pausa para almuerzo. La oficina está frente a tribunales, y el trabajo es presencial. se requiere experiencia previa en un cargo administrativo. preferentemente haber trabajado en un estudio jurídico.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '07-04-2026', '07-04-2026 15:41:45', '08-04-2026 13:13:46', '2026-04-07', NULL, NULL, '2026-04-07T00:00:00-03:00', NULL, NULL, 1, 0, 26, 2370, 1, NULL, 0, 0, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118221816.html', '2026-04-10T07:05:55.112689');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118219358, 465870, 'Selector/a reclutador/a de personal', 'ARCHLATAM', 'Para importante empresa de Córdoba nos encontramos en la búsqueda de reclutadores, con experiencia comprobable.Debera realizar el screening del proceso de reclutamiento y selección, filtrar currículums, evaluar perfiles de candidatos, para identificar aquellos que mejor se ajusten a los requisitos, necesidades y valores de la empresa y sus clientes, con el fin de contribuir a la provisión del capital humano para el rol de Representantes de experiencia al Cliente.Principales Tareas:Filtrar currículums, evaluando los perfiles de postulantes para identificar a aquellos/as que mejor se ajusten a los requisitos y valores de la empresa y cumplan los requisitos solicitados.Cargar y gestionar de la base de datos de postulantes.Realizar entrevistas telefónicas, siguiendo los cuestionarios provistos, indagando y verificando requisitos duros y habilidades blandas solicitadas.Realizar propuestas de condiciones laborales genéricas o específicasIdentificar a los candidatos con potencial de avanzar a la siguiente instancia.Gestionar la agenda de entrevistas y convocar a los/las postulantes pre-seleccionados a entrevistas grupales, individuales, pruebas técnicas y otras instancias de ser necesario.Envío de mensajes con a los/las postulantes, a través de medios telefónicos, mails o mensajería instantánea (como Whatsapp o Whappi).Debe ser comprometido/a, responsable, con ganas de aprender y crecer, ordenadas/os. Con ganas de adquirir experiencia, predispuestos/as y flexibles.Deben ser personas analiticas con excelente dicción y gran capacidad de escucha activa.Requisitos:Egresados o estudiantes de carreras como: Recursos Humanos, relaciones laborales, psicología, que esten buscando sumar experiencia laboral o relacionada a reclutamiento y selección.Pueden ser Tecnicaturas o Licenciaturas.', 0, 'Córdoba, Córdoba', 'Presencial', 'Full-time', '06-04-2026', '06-04-2026 11:23:47', '09-04-2026 11:11:29', '2026-04-06', NULL, NULL, '2026-04-06T00:00:00-03:00', NULL, NULL, 1, 0, 17, 2565, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_465870_bum_v85320d5b.jpg', 0, 0, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118219358.html', '2026-04-10T07:05:55.112780');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2178987, 524103, 'Personal de Limpieza y Cocina', 'Galidon', 'Personal de Limpieza y Cocina Resumen del Puesto Estamos en la búsqueda de personal proactivo y responsable para desempeñarse en tareas de limpieza general y apoyo en cocina. El candidato ideal deberá poseer una gran capacidad de organización y atención al detalle para mantener un ambiente de trabajo óptimo y contribuir al buen funcionamiento del área de cocina. Responsabilidades Realizar la limpieza y desinfección de todas las áreas del establecimiento, incluyendo salones, baños y cocinas. Mantener la vajilla, utensilios y equipos de cocina limpios y en orden. Colaborar en tareas básicas de preparación de alimentos según sea necesario. Gestionar la correcta disposición de residuos. Asegurar el orden y la limpieza general del espacio de trabajo. Requisitos Experiencia previa en puestos de limpieza o ayudante de cocina (no excluyente). Capacidad para seguir instrucciones y procedimientos de limpieza e higiene. Actitud proactiva y disposición para el trabajo en equipo. Responsabilidad y compromiso con las tareas asignadas. Flexibilidad horaria.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '07-04-2026', '07-04-2026 09:42:48', '07-04-2026 09:42:48', '2026-04-07', NULL, NULL, '2026-04-07T00:00:00-03:00', NULL, NULL, 1, 0, 22, 2609, 1, 'https://imgzj.jobscdn.com/portal/img/empresas/1/static/logoMainPic_524103_bum_v5ee0d0e1.jpg', 0, 0, NULL, 2001, 'Freemium', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2178987.html', '2026-04-10T07:05:55.112856');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225699, 2612300, 'Desarrollador PHP - Laravel Ssr - Híbrido - 1819', 'Aliantec', '¿Qué hace la compañía?Es una empresa de tecnología que desarrolla soluciones de gestión empresarial en la nube (ERP), orientadas a PyMEs y emprendedores de Latinoamérica.Su plataforma permite centralizar la operación del negocio en un único sistema, facilitando la gestión de procesos clave como facturación electrónica, control de stock en tiempo real, administración de precios, compras y ventas. Además, ofrece integración con los principales ecommerce y marketplaces del mercado, promoviendo una operación más conectada, eficiente y escalable. Se trata de una solución accesible desde cualquier dispositivo, diseñada para simplificar la gestión diaria y optimizar la toma de decisiones en empresas en crecimiento.¿Qué necesitás para ser parte del equipo?A nivel personal: Buenas relaciones interpersonales. Trabajo en equipo y en entornos dinámicos. Creatividad, Proactividad y Flexibilidad. Habilidades para resolución de problemas.A nivel técnico: Más de 3 años de experiencia comprobable como Desarrollador Back End en empresas Saas. | Excluyente. Experiencia sólida en PHP 8 / Laravel 9. | Excluyente. Conocimientos y experiencia en: - Patrones de diseño. - API Rest. - PHP Unit. Manejo de Base de datos no relacionales (Redis, MongoDB, Elasticsearch). | Excluyente. Manejo de base de datos relacionales (MSSQL, MySQL, PostgreSQL). | Excluyente. Conocimientos/experiencia en Nginx / CLI. | Deseable. Profesional universitario de las carreras de ingeniería en sistemas, informática, telecomunicaciones o afín. | Deseable.¿Qué vas a hacer? Desarrollar nuevas funcionalidades solicitadas por el equipo de producto. Analizar mejores prácticas de codificación. Estimar y relevar necesidades técnicas. Prever posibles cambios de infraestructura que requieran los desarrollos. Aplicar las mejores soluciones para programar acciones y funciones. Mantener siempre una actitud de autoaprendizaje y actualización de conocimientos, estudiando los lenguajes de programación vigentes. Indagar las necesidades de los clientes y ofrecer las mejores soluciones en forma de proyectos factibles. Identificar problemas en la cadena productiva, analizando todos los procesos, para definir dónde se generó y cómo solucionarlo. Proponer soluciones en etapas tempranas para evitar problemas. Optimizar las aplicaciones para un mejor flujo y rendimiento. Realizar y/o apoyar en los despliegues a producción. Atender y solucionar bugs reportados por el área de soporte y servicio al cliente.¿Con quién trabajarás?Trabajarás en una de las células del área de IT conformado por un Líder y otros colegas Desarrolladores Backend y Frontend.¿Con qué herramientas trabajarás?PHP, Laravel, MS SQL, Jira, Git, Confluence, Redis, MongoDB. Github y metodología Scrum.¿Cuándo y dónde trabajarás?Trabajarás en el horario de 9 a 18 hs, en un esquema híbrido asistiendo dos días a las oficinas ubicadas en Parque Patricios - martes y miércoles - y 3 días de home office.¿Qué ofrecen? Relación de dependencia directa con la empresa. Prepaga de primer nivel. Día de cumpleaños libre + regalo especial. Viernes Flex: 1 viernes al mes con media jornada. 21 días de vacaciones. Happy Summer: 2 fines de semana largos libres en verano. Tarjeta prepaga con crédito mensual. Club de beneficios con descuentos exclusivos. Descuentos en Educación IT.¿De qué fases consta el proceso de selección?Tendrás una primera entrevista con nuestra recruiter, Rocío Albelo, para conocer tus experiencias laborales e intereses. Luego, participarás de dos entrevistas con nuestro cliente, conociendo primero a RH y luego una segunda instancia técnica con el Líder del equipo.', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '09-04-2026', '09-04-2026 16:08:11', '09-04-2026 16:08:11', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 19, 2621, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_2612300_bum_v71b9694.jpg', 0, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'tecnologia', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225699.html', '2026-04-10T07:05:55.112989');
