INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118220194, 2614150, 'Vendedor/a Presencial', 'CERAMISUR SA', 'Vendedor/a Presencial Resumen del Puesto Estamos en la búsqueda de un/a Vendedor/a Presencial con un perfil proactivo, excelente trato con clientes, compromiso y gran capacidad de trabajo en equipo. Buscamos a alguien que se sume a un entorno dinámico y en crecimiento. Responsabilidades Atención y asesoramiento integral a clientes en salón. Gestión y cierre de ventas. Seguimiento de consultas y oportunidades comerciales. Fidelización de clientes. Colaboración activa con el equipo para alcanzar objetivos comunes. Requisitos Mínimo 4 años de experiencia comprobable en ventas. Se valorará experiencia en rubros de construcción o terminaciones. Conocimientos en diseño para asesoramiento estético y funcional. Manejo de herramientas de comunicación digital (mensajería, correo electrónico, redes). Excelente presencia y habilidades de comunicación. Capacidad para trabajar de forma autónoma y en equipo.', 0, 'Florencio Varela, Buenos Aires', 'Presencial', 'Full-time', '06-04-2026', '06-04-2026 16:34:25', '06-04-2026 16:37:31', '2026-04-06', NULL, NULL, '2026-04-06T00:00:00-03:00', NULL, NULL, 1, 0, 6, 35, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_2614150_bum_vae9170a4.jpg', 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118220194.html', '2026-04-10T07:05:55.114549');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118221656, NULL, 'Coordinador/a Administrativo/a - Presencial', 'Confidencial', 'Empresa Pyme dedicada al consumo masivo, con más de 50 años en el mercado, se encuentra en la búsqueda de un Coordinador/a para el área de administración.Dentro de las principales responsabilidades se encuentran:*Coordinación del ciclo de facturación, pago a proveedores, cobranzas*Conciliación bancaria y de cuentas (clientes y proveedores) - EXCLUYENTE*Liderazgo de equipo*Nexo con el estudio contable externo*Mejora de procesos administrativosCómo principales requisitos se destacan:*Estudiante avanzado o recibido de carreras de ciencias económicas o afines.*Excel intermedio/avanzado (excluyente). Se realizará ejercicio práctico durante el proceso de entrevistas.*Uso de sistema de gestiónHorario 9-18 hs Lunes a Sabado', 1, 'Vicente López, Buenos Aires', 'Presencial', 'Full-time', '07-04-2026', '07-04-2026 14:09:02', '09-04-2026 11:31:37', '2026-04-07', NULL, NULL, '2026-04-07T00:00:00-03:00', NULL, NULL, 1, 0, 1, 22, 1, NULL, NULL, NULL, NULL, 70, 'Simples', 'bumeran', 'simple', 1, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118221656.html', '2026-04-10T07:05:55.114659');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118226354, 319880, 'Coordinador/a de Experiencia y Staff (Cine). Presencial Neuquén', 'Randstad Argentina', '¡Esta propuesta te puede interesar! Coordinador/a de Experiencia y Staff (Cine) Ubicación Excluyente: Neuquén Capital (Presencial) Si posees experiencia previa en retail o fast food y buscas un rol de liderazgo dinámico y operativo, donde la gestión de equipo se combina con la acción directa en el servicio, ¡te invitamos a postularte! Misión Principal Garantizar la correcta ejecución operativa y la excelencia en el servicio a través de un liderazgo 360°. Esto implica coordinar al equipo de trabajo y, al mismo tiempo, participar activamente en la operación diaria, asegurando que cada cliente disfrute de una experiencia de primer nivel desde la línea de fuego. Responsabilidades Clave Como Coordinador/a, serás el referente directo de un equipo de 10 a 20 personas, bajo una modalidad polifuncional, encargándote de: Liderar con el ejemplo participando en las diferentes dinámicas de trabajo (boletería, candy, salas), garantizando la aplicación del modelo de atención de la compañía. Supervisar al personal asignado, gestionando tareas, descansos y objetivos, manteniendo siempre la cercanía con la operación real del turno. Controlar insumos y gestionar la producción de snacks para atender la demanda, interviniendo directamente en los procesos cuando el flujo de clientes lo requiera. Verificar el correcto funcionamiento de equipos, orden en bodegas y cumplimiento estricto de las normas de Seguridad e Higiene. Participar en la formación de nuevos colaboradores mediante el acompañamiento en las tareas operativas diarias. Ser responsable por el attendance y percap del turno, optimizando las ventas a través de una presencia constante en el área de servicio. Requisitos Indispensables Formación: Título Secundario Completo (Excluyente). Experiencia: Mínimo 8 meses en posiciones operativas o de coordinación en Retail, Fast Food o Entretenimiento. Se valorará especialmente a quienes provengan de entornos de alto volumen de ventas y atención directa. Disponibilidad Horaria: Horarios rotativos (tarde/noche/cierres). Se otorgan 6 francos mensuales. Perfil 360°: Buscamos a alguien proactivo, con gran capacidad de adaptación a diferentes tareas y que disfrute del contacto constante con el cliente y el trabajo de campo. Propuesta de Valor Posición bajo el convenio de Multipantalla como Oficial Calificado. Integración a una empresa líder con un ambiente de trabajo dinámico. Oportunidad de desarrollo y crecimiento profesional en base a desempeño. Si consideras que reunís los requisitos para el puesto y te gustan los desafíos, no lo dudes…. ¡Postulate! Sobre Randstad En Randstad nos moviliza ayudar a las personas y a las organizaciones a desarrollar todo su potencial. Ese es el compromiso que asumimos como compañía en todo el mundo, un compromiso que nos impulsa a ir más allá para lograr que nuestros clientes y candidatos alcancen el éxito. ¿Cómo lo hacemos?, combinando nuestra pasión por las personas con el poder de la tecnología, creando experiencias más humanas, que nos permitan ser una fuente de inspiración y apoyo para quienes nos eligen. Porque estamos convencidos de que mejores personas hacen mejores.', 0, 'Neuquén, Neuquén', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 21:07:39', '10-04-2026 04:03:50', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 22, 36, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_319880_bum_vff58225f.jpg', 1, 0, 4.27, 70, 'Simples', 'bumeran', 'simple', 1, 0, 1, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118226354.html', '2026-04-10T07:05:55.114888');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118219431, 13502297, 'PREVENTISTA ASESOR', 'RED MOVIL SRL', 'Resumen del PuestoEstamos buscando un Preventista dinámico y orientado al cliente para unirse a nuestro equipo. El candidato ideal será responsable de visitar nuestra cartera de clientes, controlar el stock fisico, reponer mercadería, controlar el estado de la publicidad impresa, mantener a los clientes informados de las nuevas promociones y mantener una excelente relación con la clientela.Requisitos EXCLUYENTE: tener movilidad propia (motocicleta o automovil) EXCLUYENTE: Vivir en la localidad de ESCOBAR- GARIN- ING MASCHWITZ, provincia de BS AS. Secundario completo (excluyente). Buena presencia y excelente dicción (excluyente). Perfil marcadamente orientado a la atención al cliente (excluyente). Se valorara experiencia previa en trabajos de preventista o vendedor/a puerta a puerta. Se valorará buen manejo de aplicaciones y e-mail.Responsabilidades Visitar clientes diariamente según la ruta asignada. Controlar el stock físico en cada visita. Utilizar una aplicación para registrar la reposición de mercadería.JORNADA DE 4HS POR LA MAÑANA DE LUNES A VIERNES', 0, 'Escobar, Buenos Aires', 'Presencial', 'Por Horas', '06-04-2026', '06-04-2026 12:01:54', '08-04-2026 10:04:11', '2026-04-06', NULL, NULL, '2026-04-06T00:00:00-03:00', NULL, NULL, 1, 0, 6, 35, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13502297_bum_vd66f23ee.jpg', NULL, NULL, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118219431.html', '2026-04-10T07:05:55.115011');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224801, NULL, 'Vendedor B2B - Preventista', 'Confidencial', 'Laboratorio líder en productos de higiene hospitalaria y personal, se encuentra en la búsqueda de una Vendedora Preventista para desarrollar y potenciar la zona de Capital Federal.Somos una PYMe que centra su búsqueda en perfiles comerciales con marcada autonomía, excelentes relaciones interpersonales y enfoque en resultados.Principales responsabilidades: Gestión en calle: Visita diaria a farmacias, ortopedias y pañaleras. Desarrollo de cartera: Captación de nuevos puntos de venta y fidelización de clientes actuales. Asesoramiento técnico: Capacitar al personal del punto de venta sobre los beneficios y usos del producto. Cumplimiento de objetivos: Ejecución de las metas de ventas mensuales y reporte de gestión.¿Qué buscamos? Experiencia: Mínimo 1 año en ventas B2B o preventa especialmente la experiencia en el rubro farmacéutico o consumo masivo. (Excluyente) Perfil: Marcada actitud proactiva, capacidad de negociación y excelente presencia. Habilidades: Organización para el manejo de hoja de ruta y autogestión. Residencia: Preferentemente en CABA.Ofrecemos: Posición efectiva en jornada completa. Incorporación inmediata a un laboratorio sólido y en expansión. Remuneración acorde al puesto + incentivos por cumplimiento de objetivos.', 1, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 14:40:09', '09-04-2026 14:44:40', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 6, 35, 1, NULL, NULL, NULL, NULL, 70, 'Simples', 'bumeran', 'simple', 1, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224801.html', '2026-04-10T07:05:55.115124');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224739, 10060311, 'PREVENTISTA/COMERCIAL IND. ALIMENTICIA', 'MMG Servicios Eventuales', 'Buscamos PREVENTISTAS con experiencia en Ind. ALIMENTICIA y EJECUTIVO COMERCIAL de productos de higiene personalPrincipales responsabilidades Visitar a los clientes asignados y gestionar cartera de Clientes Promover la venta y correcta exhibicion de productos Toma de pedidos y seguimiento comercial Desarrollo de nuevos clientes Relevacion de informacion del Mercado y la CompetenciaRequisitos Experiencia previa como preventista, conocimiento en empresas de alimentos / rubro farmacias o consumo masivo Movilidad propia, preferentemente Perfil Comercial y proactivo Moadalidad a tiempo completo Zona de trabajo: CABA', 0, 'Pilar, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 09:51:40', '09-04-2026 09:51:40', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 2, 0, 6, 35, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/0/0/1/0/0/6/0/3/1/1/logoMainPic_10060311.jpg', 0, 0, 4.33, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224739.html', '2026-04-10T07:05:55.115217');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118223858, 10116631, 'Analista de control de procesos', 'LAROCCA NEUMATICOS S A', '🚀 Estamos buscando Analista de control de procesos En Larocca Neumáticos, con más de 80 años de trayectoria en el mercado, buscamos incorporar un Analista de control de procesos en nuestra sede de Flores (CABA).🎯 Objetivo del puestoControlar y optimizar los procesos operativos de la empresa, identificando oportunidades de mejora y estableciendo controles que aseguren su correcto funcionamiento. Asimismo, elaborar reportes de cumplimiento y desarrollar instructivos y/o normas cuando sea necesario. También participará activamente en la elaboración de reportes de gestión destinados a la Dirección.📌 Principales responsabilidades Realizar relevamientos a través de entrevistas, con el objetivo de comprender en profundidad los procesos correspondientes al circuito a analizar. Realizar pruebas de control para validar los procesos, tales como arqueos, inventarios, revisión de comprobantes, pruebas de ventas y de remitos, entre otras. Recopilar información de diversas fuentes con el fin de validar las definiciones obtenidas en los relevamientos y en las pruebas de control. Elaborar un análisis detallado de los relevamientos realizados y de la información recopilada, identificando desvíos o problemáticas a resolver. Proponer, en conjunto con el equipo, alternativas de corrección o mejora de los procesos, basadas en la experiencia, la lógica y la creatividad. Diseñar y modelizar los puntos de control necesarios para el seguimiento y la evolución futura de los procesos. Elaborar y documentar los instructivos y procedimientos necesarios para implementar las mejoras o controles propuestos. Comunicar las sugerencias de mejora y obtener su validación por los sectores involucrados y la Gerencia. Participar activamente en la elaboración de información de gestión periódica para la Dirección, especialmente en aquellas áreas donde el proceso de generación de dicha información aún no se encuentre estructurado.✅ Requisitos • Edad: Entre 25 y 35 años. • Zona de residencia: CABA. • Experiencia de 2 a 5 años en áreas contables, control de procesos y auditoría interna. • Se valorará formación universitaria/terciaria en carreras afines como: Lic en administración y Contador • Conocimiento en herramientas informáticas: Excel (excluyente)🧩 Competencias clave ✔ Planificación y organización ✔ Capacidad para trabajar en equipo ✔ Autonomía y efectividad en el autocontrol de sus tareas ✔ Orientación al cliente interno y externo. ✔ Buena comunicación Oral y Escrita. 📍 Modalidad: Presencial – Flores (CABA) Jornada: Full Time de lunes a viernes de 8:30 a 18 hs. La mayoría de sus funciones se desarrollarán en las oficinas de Flores; no obstante, deberá asistir con cierta regularidad a la zona logística ubicada en Carlos Spegazzini. Se recomienda contar con movilidad propia para facilitar estos traslados. Asimismo, existe la posibilidad de realizar viajes laborales dentro de Argentina, de manera esporádica y por períodos breves (por ejemplo, a Salta o Bahía Blanca). ⏳ 📩 Si querés formar parte de una empresa con trayectoria, estabilidad y proyección, postulate por este medio o enviá tu CV a indicando remuneración pretendida.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 15:37:36', '09-04-2026 11:44:26', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 1, 88, 1, NULL, 1, 0, NULL, 40, 'Destacados', 'bumeran', 'destacado', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118223858.html', '2026-04-10T07:05:55.115431');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225707, 13491473, 'Ingeniero de Automatización e Integración de Datos y Procesos (Foco en innovación)', 'AVANZARE RH', 'Estamos acompañando a una empresa de servicios de ingeniería y consultoría técnica para industria en la incorporación de un perfil clave para liderar su transformación digital y evolución operativa.Buscamos a alguien que combine visión de negocio + capacidad técnica, con foco en automatización, integración de sistemas y gestión de datos, con impacto directo en el negocio y reporte a Dirección.🚀 El desafíoLa compañía se encuentra en un proceso de modernización, donde hoy conviven múltiples herramientas y criterios de información entre áreas.Tu rol será liderar la evolución hacia un modelo integrado, automatizado y data-driven, con fuerte foco en: Integración de sistemas mediante APIs Automatización de flujos de información Estandarización y estructuración de datos Generación de información confiable para la toma de decisiones🎯 Principales responsabilidades Analizar y rediseñar procesos con foco en automatización e integración Diseñar e implementar automatizaciones end-to-end Desarrollar e integrar sistemas mediante APIs (REST), Webhooks y flujos automatizados Orquestar flujos de datos entre múltiples herramientas y plataformas Definir la arquitectura de datos organizacional Estandarizar criterios de registro y estructuras de información Diseñar la arquitectura tecnológica de automatizaciones Documentar desarrollos y gestionar repositorios de código Desarrollar dashboards operativos y KPIs para Dirección🧠 Requisitos clave (excluyentes) +5 años de experiencia (ideal 5 a 10 años) Experiencia real implementando automatizaciones e integraciones Python avanzado Experiencia sólida en integración de sistemas Manejo de APIs REST, Webhooks, JSON SQL y manejo sólido de datos Experiencia con herramientas como Make, Zapier, Power Automate o n8n Bases de datos (PostgreSQL, MySQL u otras)➕ Valorado Power BI / Tableau / Looker Experiencia en entornos industriales, logísticos o de servicios técnicos Conocimientos en BPM, Lean o mejora continua Background en ingeniería o sistemas🧩 Perfil Pensamiento sistémico Fuerte orientación a eficiencia Capacidad de ejecución (hands-on) Buen manejo de stakeholders Mentalidad de mejora continua📍 Condiciones Ubicación: Colegiales Modalidad: Full time Reporte directo a Dirección Rol con alto nivel de autonomía e impacto⚠️ No es para vos si… Buscás un rol exclusivamente de desarrollo sin interacción con negocio Sos analista de datos sin foco en implementación Tenés un perfil teórico sin experiencia ejecutando soluciones Estás en etapa inicial de carrera', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '09-04-2026', '09-04-2026 16:12:50', '09-04-2026 16:12:50', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 19, 34, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13491473_bum_vace25612.jpg', NULL, NULL, NULL, 1020, 'Aviso Talento', 'bumeran', 'tecnologia', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225707.html', '2026-04-10T07:05:55.115621');
