INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224766, NULL, 'Supervisor de Producción', 'Confidencial', 'Importante Empresa IndustrialincorporaráSupervisor de Producción – Turnos RotativosNos encontramos en la búsqueda de una persona con formación secundaria técnica, que cuente con al menos 3 años de experiencia en posiciones similares desarrollada en empresas industriales.Será deseable contar con conocimientos en buenas prácticas de manufactura, TPM y Normas ISO.La posición será el responsable de liderar el equipo de personas del turno asignado. Mediante los recursos de fábrica, el objetivo es cumplir con el programa de producción en tiempo y forma, asegurando la calidad de los productos y la seguridad del personal / activos.Sus principales responsabilidades serán: Evaluar los factores que influyen en la producción, tomar las acciones correctivas y preventivas adecuadas en caso que lo requiera. Supervisar las condiciones de los materiales de servicio (máquinas y equipos, insumos, productos, herramientas). Asegurar el flujo de información y producto para el cumplimiento del programa de producción semanalmente. Evaluar y desarrollar a los colaboradores a su cargo para el logro de los objetivos. Chequear que la producción cumpla con las especificaciones establecidas por el cliente. Elaborar informes de resultados, entre otras.El esquema de trabajo es presencial, con horarios rotativos en 3 turnos (mañana, tarde y noche)', 1, 'Gregorio de Laferrere, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 10:16:34', '09-04-2026 10:16:34', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 16, 32, 1, NULL, NULL, NULL, NULL, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224766.html', '2026-04-10T07:05:55.115869');
