 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13193659_bum_v4151be05.jpg', 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118221935.html', '2026-04-10T07:05:55.115979');
