INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118223697, 13402349, 'Marketing & Project Manager (Remoto)', 'The Sampling Experience', 'Buscamos un perfil de Marketing & Project Manager (Freelance, full time y 1 0 0% remoto) para liderar la gestión de campañas de sampling y activaciones de marca.Serás responsable de la planificación, coordinación y ejecución de campañas, trabajando con partners (oficinas, gimnasios, universidades, eventos, etc.) y asegurando una correcta ejecución.El rol también incluye una parte comercial: generación de leads, contacto con potenciales clientes y seguimiento de oportunidades.Responsabilidades: Gestión de campañas end to end Coordinación con partners y seguimiento de activaciones Control de ejecución, timings e incidencias Contacto con clientes y partners Generación de leads y apoyo comercial Gestión de bases de datos (Excel, Apollo, etc.)Buscamos: perfil organizado, resolutivo, proactivo y con buena comunicación escrita.Condiciones: freelance, full time y 1 0 0% remoto.', 0, 'Mar del Plata, Buenos Aires', 'Remoto', 'Full-time', '09-04-2026', '09-04-2026 12:32:00', '10-04-2026 04:42:15', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 14, 30, 1, NULL, 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 1, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118223697.html', '2026-04-10T07:05:55.116214');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118222065, 413550, 'Project Finance- Organismos multilaterales de crédito', 'HuCap', '¿Te apasiona el mundo de las finanzas y querés ser el motor de la transformación agroindustrial? Estamos en la busqueda de un profesional que será el puente entre la inversión internacional y el desarrollo sostenible en el campo. 🎯 Tu Misión: Gestionar el ciclo de financiamiento de proyectos, garantizando la rendición de cuentas ante organismos internacionales (UE, Fondos Verdes) y transformando la estrategia de sostenibilidad en modelos financieros exitosos. 📝 Tus principales desafíos: • Gestión de Fondos: Estructuración técnica y accountability con organismos globales. 🌍 • Análisis Pro: Evaluar la factibilidad económica de proyectos de sostenibilidad. 📊 • Voz del Área: Disertar en jornadas técnicas y organizar eventos del sector. 🎤 • Agenda Dinámica: Responder con agilidad a cambios climáticos o políticos con informes técnicos. 📉 🔎 ¿Qué buscamos? • Formación: Graduados en Finanzas, Economía, Administración Agraria o afines. 🎓 • Experiencia: 2 a 3 años en Project Finance (excluyente sector Agro o Forestal preferentemente). 🏗️ • Idiomas: Inglés nivel intermedio (lectura y redacción técnica). • Habilidades: Gran capacidad de oratoria y manejo del lenguaje del nicho agropecuario. 🚜 • Disponibilidad: Para viajes breves al interior (1 o 2 veces al mes). ✈️ • Modalidad Presencial en Palermo 🌟 ¿Qué ofrecemos? • 🏥 Salud: Swiss Medical para vos y tu grupo familiar. • 🏋️ Bienestar: Gimnasio 100% bonificado. • 🍱 Almuerzo: Sistema de viandas (80% cubierto por la empresa). • 🚀 Crecimiento: Integración en un área joven con alta visibilidad ante la dirección. Si cumplís con el perfil y buscás un entorno dinámico y con propósito, ¡queremos conocerte!', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '07-04-2026', '07-04-2026 16:45:19', '08-04-2026 09:53:24', '2026-04-07', NULL, NULL, '2026-04-07T00:00:00-03:00', NULL, NULL, 1, 0, 1, 25, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_413550_bum_vd6162bb4.jpg', 0, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118222065.html', '2026-04-10T07:05:55.116374');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225929, 2073200, 'Promovendedor Vía Pública - Córdoba Capital', 'GI GROUP Argentina', 'Tu futuro, nuestra pasión.Somos una consultora de Recursos Humanos de origen italiano con más de 15 años en el país. Aportamos valor en la selección y tercerización responsable de recursos humanos.Trabajamos con empresas de primera línea, generalmente internacionales, buscando perfiles profesionales, técnicos y de alta gerencia. Proveemos servicios de seleccón, personal eventual y tercerización. Somos #SIMPLES / HUMANOS / EXPERTOS VÁLIDO PARA NUESTROS AVISOS EN CIUDAD DE BUENOS AIRES:Búsqueda laboral equitativa. El empleador solo podrá solicitarle la información estrictamente necesaria para el desempeño en el trabajo que se ofrece (Ley 6471). Estamos en búsqueda de Promotores para nuestro importante cliente, dedicado a ofrecer servicios de movilidad y entrega a través de una plataforma tecnológica.El objetivo de esta posición será:Atraer, persuadir y activar a dueños de autos particulares para convertirlos en conductores, actuando como el principal embajador de la marca en campo para acelerar el crecimiento de la plataforma a través de un enfoque proactivo de ventas y un excelente servicio.Algunas de tus responsabilidades serán:● Gestionar el Funnel de Adquisición: Ser dueño del proceso completo, desde la prospección en frío y el primer contacto hasta la recopilación de documentos y la activación final del conductor.● Brindar Soporte y Asistencia: Actuar como el principal punto de contacto para los leads, resolviendo dudas de forma presencial o digital para garantizar un proceso de registro sin fricciones.● Generar Inteligencia de Mercado: Recopilar y reportar activamente información sobre la competencia y las oportunidades en el campo para ayudar a optimizar la estrategia. Requisitos: Buscamos talentos que residan excluyentemente en ciudad de Córdoba.Formación: Secundacio completo (Excluyente). Idealmente con formación adicional de tecnicaturas o terciarios.Experiencia: Mínimo dos años comprobables en ventas de campo, reclutamiento en campo o roles similares de adquisición de clientes a cara a cara (B2C).Experiencia en prospección en frío y negociación. Indispensable el manejo de tecnología y aplicaciones móviles a nivel usuario experto.Habilidades interpersonales y dinamismo. Manejo de objeciones y resolución de conflictos. Flexibilidad para ajustarse a nuevos procesos y a un entorno de trabajo dinámico.El perfil deberá tener marcada orientación al cliente, iniciativa y proactividad y atención al detalle. Beneficios Horario de trabajo: Full time de lunes a viernes.Modalidad de trabajo: 100% presencial.Lugar de trabajo: CórdobaContratación por Consultora.Oportunidad de pertenecer a un equipo en expansión y desarrollarte profesionalmente en una compañía reconocida en el mercado.', 0, 'Córdoba, Córdoba', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 17:34:25', '09-04-2026 17:34:26', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 6, 35, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_2073200_bum_v6d4c351c.jpg', 1, 0, 3.14, 70, 'Simples', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225929.html', '2026-04-10T07:05:55.116558');
