INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118220982, 13032081, 'Dibujante Proyectista Electrico', 'Consultora: Rosaura Borlandelli', 'Atencion Tecnicos/Ingenieros ⚡ Buscamos Dibujante Proyectista Eléctrico ( AUTOCAD 2/ EPLAN / SIEMENS) Lugar: Villa Ballester (Presencial). Rubro: Ingeniería y Fabricación Electromecánica. ¿Sos un experto en diseño de tableros eléctricos y buscás un desafío donde tu criterio técnico sea clave para la producción? ¡Sumate a nuestro equipo de Ingeniería! Empresa líder en fabricación de tableros de BT/MT y obras electromecánicas busca incorporar un Dibujante Proyectista Eléctrico. para sus oficinas en Villa Ballester. 🎯 Tu misión: Serás el responsable de transformar requerimientos técnicos en planos constructivos precisos (Unifilares, Funcionales y Topográficos), garantizando que el equipo de producción tenga toda la información necesaria para una fabricación eficiente y sin errores. 📝 Tus principales tareas: Diseño de esquemas eléctricos (unifilares, funcionales y topográficos). Especificación técnica y cómputo de materiales. Interrelación constante con el sector de Producción para optimizar la ejecución de los diseños. ✅ ¿Qué buscamos? Dominio Técnico: Experiencia sólida en diseño de tableros de Baja Tensión (BT). Software: Manejo avanzado de AutoCAD 2D (excluyente) y conocimientos de EPLAN. Valoramos experiencia en implementación de proyectos a esta plataforma). Componentes: Familiaridad con la línea de productos SIEMENS (protecciones, maniobra, etc.). Experiencia: Mínimo 2 años en proyectos eléctricos de tableros (Perfil orientado a Producto). Residencia: Preferentemente zona Villa Ballester o zonas aledañas (San Martín, Munro, Caseros, Florida). • Trabajo presencial, jornada full time de lunes a viernes de 8 a 18 hs', 0, 'Villa Ballester, Buenos Aires', 'Presencial', 'Full-time', '07-04-2026', '07-04-2026 10:07:02', '09-04-2026 11:15:50', '2026-04-07', NULL, NULL, '2026-04-07T00:00:00-03:00', NULL, NULL, 1, 0, 31, 2588, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13032081_bum_v1ce82d44.jpg', 0, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118220982.html', '2026-04-10T07:05:55.117077');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118218665, NULL, 'Key Account Manager para proyectos de Pantallas LED', 'Confidencial', 'BÚSQUEDA: Key Account Manager – Pantallas LED (Proyectos B2B)¿Contás con experiencia en soluciones tecnológicas y desarrollo de negocios B2B? Estamos seleccionando un/a Key Account Manager para liderar proyectos de pantallas LED en segmentos corporativos, retail, educación y sector público para nuestro cliente integrador de soluciones tecnológicas. ¿Cuál será tu desafío? Desarrollar y gestionar oportunidades comerciales en proyectos de pantallas LED (Pro-AV / Digital Signage) Detectar y generar nuevas oportunidades en integradores, retail y organismos públicos Relevar necesidades del cliente y diseñar soluciones técnicas a medida Elaborar propuestas comerciales y presupuestos (con capacitación técnica a cargo de la empresa) Gestionar el ciclo completo de venta: prospección, negociación y cierre Construir relaciones de largo plazo con clientes clave¿Qué buscamos? Experiencia mínima de 3 años en ventas B2B de proyectos tecnológicos o de infraestructura Experiencia o conocimiento en Pro-AV, Seguridad Electrónica o Cartelería Digital (excluyente) Cartera de contactos activa en integradores, retail, educación o cuentas corporativas en Argentina Perfil autónomo, orientado a resultados y con visión estratégica del negocio Habilidades de negociación y cierre', 1, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '04-04-2026', '04-04-2026 09:46:05', '07-04-2026 07:06:47', '2026-04-04', NULL, NULL, '2026-04-04T00:00:00-03:00', NULL, NULL, 2, 0, 6, 35, 1, NULL, NULL, NULL, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118218665.html', '2026-04-10T07:05:55.117160');
