1/0/7/4/logoMainPic_10191074.jpg', 1, 0, NULL, 40, 'Destacados', 'bumeran', 'destacado', 1, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118220716.html', '2026-04-11T07:05:54.572446');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118220924, 13437844, 'AT. PÚBLICO TURISMO 100% REMOTO DESDE TU TELÉFONO FLEXIBLE SIN HORARIOS', 'BARILOCHE BLISS', 'Atención TURISMO ALQUILERES TEMPORALES - 1 0 0% Remoto DESDE TU TELÉFONO / SOMOS BARILOCHE BLISSResumen del PuestoEn BARILOCHE BLISS Estamos en la búsqueda de un profesional para la Atención a Huéspedes en el sector de alojamientos turísticos. El rol principal será la gestión de reservas y la comunicación fluida con los huéspedes a través de diversas plataformas y herramientas de mensajería. 1 0 0% REMOTO DESDE TU TELÉFONO con contacto eventual PRESENCIAL (Ej. Gestionar algún cobro en efectivo, pero es poco usual).Responsabilidades Gestionar reservas y consultas de huéspedes. Coordinar ingresos y egresos de alojados. Manejar cancelaciones y modificaciones de reservas. Resolver incidencias y problemas que puedan surgir durante la estancia de los huéspedes, siguiendo procedimientos establecidos. Mantener una comunicación clara y efectiva con los huéspedes. Gestionar cobro de reservas y registrarlasRequisitos Excelentes habilidades de comunicación verbal y escrita. Alta capacidad de resolución de problemas y proactividad. Responsabilidad y organización en la gestión de tareas. Autonomía y capacidad para trabajar de forma remota. Orientación a resultados, con énfasis en el tiempo de respuesta y la calidad del servicio. Experiencia previa en roles de atención al cliente o gestión de alojamientos será valorada.BUSCANOS COMO BARILOCHE BLISS', 0, 'San Carlos de Bariloche, Río Negro', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 14:16:51', '08-04-2026 17:36:32', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 25, 2571, 1, NULL, 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118220924.html', '2026-04-11T07:05:54.572693');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2178873, 570364, 'Python Lead Engineer - Remoto - 1728', 'Aliantec', '¿Qué hace la compañía?Compañía nativa digital con presencia global de gran escala de ingeniería, diseño e innovación, con sedes ubicadas en 18 países entre América, Asia y Europa. Cuenta con un equipo de más de 20 mil profesionales que forman parte de nuevos desafíos y proyectos de vanguardia.¿Qué necesitás para ser parte del equipo? +7 años de experiencia hands-on con Python. Experiencia sólida en desarrollo backend y construcción de APIs escalables. Experiencia con SQL, Pandas y PySpark. Experiencia liderando iniciativas técnicas y mentorando equipos. Experiencia trabajando en entornos cloud (preferentemente AWS). Fuerte conocimiento en control de versiones (Git). Inglés avanzado oral y escrito (excluyente). Familiaridad con frameworks y herramientas como: FastAPI, Flask, Docker - Deseable. Conocimientos o experiencia en AI/ML Engineering (PyTorch, TensorFlow, OpenAI, etc.) - Deseable.¿Qué vas a hacer?Buscamos un/a Python Lead Engineer para liderar el diseño, prototipado e implementación de soluciones escalables que soporten analítica en tiempo real y procesos batch. La posición tendrá un rol estratégico dentro del equipo, trabajando de manera transversal con áreas de ingeniería, producto y analytics, y liderando el desarrollo de infraestructura backend orientada a datos, con impacto directo en el rendimiento del producto y la toma de decisiones del negocio.Además, será responsable de mentorizar perfiles Semi Senior, impulsar buenas prácticas de desarrollo y contribuir activamente a la cultura de datos del equipo.Como Python Lead Engineer tendrás a cargo: Diseñar y desarrollar APIs backend escalables en Python. Liderar iniciativas técnicas end-to-end, desde el diseño hasta el despliegue en producción. Desarrollar proyectos full stack de punta a punta. Construir herramientas internas para optimizar procesos y soportar servicios de streaming. Diseñar y mantener pipelines y soluciones de procesamiento de datos (batch y real-time). Trabajar en conjunto con equipos de Ingeniería, Producto y Analytics. Participar activamente en ceremonias ágiles (Scrum), reuniones técnicas y coordinación con el equipo. Asegurar estándares de calidad, performance y buenas prácticas. Mentorizar y acompañar el crecimiento técnico de Data Engineers y Developers del equipo.¿Cuándo y dónde trabajarás?Trabajarás bajo un esquema 100% remoto de Lunes a Viernes de 9 a 18 hs desde cualquier parte del país.¿Con quién trabajarás?Vas a ser parte del equipo IT de la compañía y estarás en pleno contacto con los clientes de la misma.¿Qué ofrecen? Sueldo split: gran porcentaje de la remuneración en dólares. Contrato directo con la Empresa. 100% remoto. Prepaga de primer nivel para vos y tu grupo familiar. Plataforma de cursos gratuitos. Licencia de paternidad/maternidad extendida. Descuentos en entidades educativas privadas. Tarjeta de descuentos: ropa, comida, viajes, etc. Inglés in Company. Plan de carrera interno en diferentes ramas IT. Proyectos multidisciplinarios.¿De qué fases consta el proceso de selección?El proceso de selección se desarrolla en varias etapas. En primer lugar, tendrás una entrevista con nuestras Recruiters, Aldana Alvarenga, donde conversaremos sobre tu experiencia laboral y tus intereses.Luego, continuarás con una instancia inicial junto al equipo de Recursos Humanos de la empresa empleadora. Posteriormente, se prevén hasta cuatro entrevistas adicionales con el cliente asignado: la primera con el líder del equipo, la segunda y tercera con diferentes managers y, finalmente, una última reunión orientada a conocer al equipo y el proyecto en mayor detalle.', 0, 'Capital Federal, Buenos Aires', 'Remoto', 'Full-time', '04-04-2026', '04-04-2026 21:34:51', '04-04-2026 21:34:51', '2026-04-04', NULL, NULL, '2026-04-04T00:00:00-03:00', NULL, NULL, 1, 0, 19, 2621, 1, 'https://imgzj.jobscdn.com/portal/img/empresas/1/static/logoMainPic_570364_bum_v183b0a04.jpg', 0, 0, NULL, 1020, 'Aviso Select', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2178873.html', '2026-04-11T07:05:54.572908');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118220307, 1013630, 'Analista QA con Tosca Semi Senior', 'ACCIONA IT', 'En Acciona IT nos encontramos en búsqueda de un profesional para desempeñarse como Analista QA con Tosca Semi Senior para una importante empresa multinacional.Responsabilidades Analizar requerimientos funcionales y no funcionales de los proyectos del Banco. Diseñar, crear y mantener casos de prueba utilizando Tricentis Tosca. Automatizar pruebas de regresión, integración y end-to-end. Participar en las ceremonias ágiles: refinamientos, planning, dailies y retrospectivas. Ejecutar pruebas manuales y automatizadas, documentando resultados y desviaciones. Reportar y gestionar defectos en herramientas de seguimiento (Jira o similar). Asegurar la calidad de las entregas y validar criterios de aceptación. Trabajar en conjunto con desarrolladores, producto y negocio para asegurar el correcto alcance funcional.RequisitosObligatorios: +3 años de experiencia en roles de QA Analyst / QA Automation. Experiencia comprobable con Tosca (Tricentis) para diseño y ejecución de pruebas. Experiencia en automatización de pruebas (idealmente UI y/o API). Conocimientos sólidos de herramientas de gestión de versiones (Git). Experiencia trabajando en metodologías ágiles (Scrum). Conocimientos en análisis funcional y técnicas de diseño de casos de prueba.Deseables: Experiencia previa en proyectos del sector bancario o financiero. Manejo de herramientas complementarias: Jira, Confluence, Jenkins o pipelines de CI/CD. Conocimientos de SQL para validación de datos. Experiencia en pruebas API (Postman, Swagger, SoapUI).Tecnologías del ecosistema (plus) Tosca GIT CI/CD (Jenkins, GitLab CI, Azure DevOps, etc.) SQL Herramientas de testing bancario (plus)Esquema hibrido en Chacarita, CABA ( 2 a 3 dias por semana)Puesto relación de dependencia con Acciona IT, con los siguientes beneficios:Prepaga de alto nivelPrograma de referidos.Regalo por cumpleaños.Regalo por fechas especiales.People Care (Seguimiento personalizado)', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '06-04-2026', '06-04-2026 17:20:47', '10-04-2026 14:08:12', '2026-04-06', NULL, NULL, '2026-04-06T00:00:00-03:00', NULL, NULL, 1, 0, 19, 2626, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_1013630_bum_v9c1aa214.jpg', 1, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'tecnologia', 1, 1, 0, NULL, 'https://certificaciones.greatplacetowork.com.ar/acciona-it', 'https://www.bumeran.com.ar/empleos/1118220307.html', '2026-04-11T07:05:54.573019');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2179306, 570364, 'Líder Técnico Full Stack (JAVA / React) Senior - Mix (Onsite - Remoto) - 1777', 'Aliantec', '¿Qué hace la compañía?Grupo empresario argentino con presencia nacional y trayectoria consolidada, con fuerte protagonismo en la industria bancaria y de servicios financieros, y operación en múltiples sectores estratégicos del país. Con foco en innovación, desarrollo regional y evolución tecnológica, continúa fortaleciendo sus plataformas digitales para acompañar el crecimiento del negocio y mejorar la experiencia de usuarios y clientes.Desde la Gerencia Corporativa de IT, se impulsa el desarrollo de soluciones modernas, escalables y seguras, en un entorno que combina desafíos técnicos, impacto real y trabajo colaborativo.¿Qué necesitás para ser parte del equipo?A nivel personal: Capacidad para liderar equipos técnicos, generando foco, orden y alineación con objetivos del negocio. Perfil proactivo, con visión integral para anticipar necesidades de evolución de plataformas. Excelente comunicación para articular con áreas de negocio, producto, arquitectura y otros equipos de ingeniería. Capacidad para priorizar, tomar decisiones y sostener estándares de calidad en entornos exigentes. Orientación a resultados, mejora continua y seguimiento de métricas técnicas. Autonomía y pensamiento estratégico para gestionar interdependencias entre sistemas y plataformas.A nivel técnico: Más de 5 años de experiencia liderando equipos técnicos con profundo conocimiento de desarrollo Full-Stack (Java/Spring Boot , React) con foco en plataformas digitales: Experiencia sólida en Java 17+. Experiencia con Spring Boot, Spring Data (JPA/Hibernate) y Spring Security. Conocimientos en Quarkus y/o Spring Cloud. Experiencia en diseño e implementación de APIs RESTful y gRPC. Dominio de TypeScript Experiencia en frontend con React 18 (Hooks, Context API, Server Components). Conocimientos de UI con librerías como Tailwind CSS, Material UI o Styled Components. Experiencia en optimización de performance web (SSR, SSG, ISR y Core Web Vitals). Experiencia con bases de datos relacionales y no relacionales, incluyendo Redis. Experiencia práctica con mensajería/eventos: Kafka (alto rendimiento) y/o RabbitMQ. Conocimiento e implementación de patrones: Pub/Sub, Event Sourcing y CQRS. Capacidad para modelar dominios complejos (DDD): Bounded Contexts, agregados y entidades.¿Qué vas a hacer? Definir y ejecutar la visión técnica de las plataformas de canales, asegurando alineación con objetivos del negocio y del producto. Liderar al equipo técnico en el desarrollo y evolución de plataformas, garantizando continuidad operativa y escalabilidad. Trabajar en conjunto con equipos de producto para evolucionar soluciones alineadas a la estrategia del producto. Gestionar y priorizar el backlog técnico, asegurando decisiones alineadas con KPIs operativos y de negocio. Supervisar la entrega técnica de los desarrollos, garantizando estándares de calidad, seguridad y performance. Monitorear KPIs técnicos de la plataforma y proponer mejoras continuas. Identificar sinergias e interdependencias con otras plataformas y equipos para maximizar el valor entregado. Actuar como referente técnico y punto de contacto clave para stakeholders, facilitando comunicación y toma de decisiones.¿Cuál es el desafío de la posición?Las personas que se incorporen, tendrán el desafío de definir y ejecutar la visión técnica de las plataformas técnica de canales, asegurando que cumpla con los objetivos y características definidas.Este rol implica priorizar esfuerzos, y colaborar estrechamente con las áreas de negocio para diseñar, construir y lanzar plataformas que se soporten y se alineen con la visión de los productos.Es responsable de la calidad técnica, la eficiencia del desarrollo y la implementación rigurosa de patrones de diseño, asegurando que las soluciones escalen y sean robustas, tanto en entornos Cloud Native como en infraestructuras On-Premise.¿Cuándo y dónde trabajarás?Trabajarás de lunes a viernes, de 9 a 18 hs, bajo un esquema híbrido, con presencialidad de 1 día por semana en las oficinas ubicadas en Capital Federal.¿Qué ofrecen? Relación de dependencia directa. Excelentes condiciones de contratación bajo convenio bancario. Modalidad: esquema híbrido. Cobertura de prepaga para vos y tu grupo familiar directo- Plataforma de bienestar de primer nivel. Importantes descuentos en instituciones educativas para para vos y tu familia. Formación constante para la posición y para el desarrollo profesional. Beneficio de guardería. Cotización preferencial en productos bancarios. Bonificación en plataforma de compras Club de Beneficios.¿De qué fases consta el proceso de selección?Tendrás una primera entrevista con la Recruiter, Aldana Alvarenga, para conocer tu experiencia, expectativas e intereses.Luego, el proceso continuará con la empresa empleadora a través de distintas instancias, orientadas a que puedas conocer al equipo técnico, a Recursos Humanos y a la gerencia.', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '09-04-2026', '09-04-2026 17:02:19', '09-04-2026 17:02:19', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 19, 2621, 1, 'https://imgzj.jobscdn.com/portal/img/empresas/1/static/logoMainPic_570364_bum_v183b0a04.jpg', 0, 0, NULL, 1020, 'Aviso Select', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2179306.html', '2026-04-11T07:05:54.573176');
