ULL, 50, 0, 6, 35, 1, NULL, 0, 0, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118222766.html', '2026-04-11T07:05:54.573250');
