, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 17, 48, 1, NULL, 0, 0, NULL, 70, 'Simples', 'bumeran', 'simple', 1, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118223937.html', '2026-04-11T07:05:54.573613');
