1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13187387_bum_v1f991a14.jpg', 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118221376.html', '2026-04-11T07:05:54.575405');
