'2026-04-11T07:05:54.575544');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118226948, 13345666, 'Repositor y Preparador de Pedidos para CABA (Por Temporada)', 'JUAN SERIAL DE LA TORRE', 'Para importante Mayorista de Librería, ubicada en el barrio de San Cristóbal busca Repositor/Preparador de Pedidos y Embalador por temporada Principales Tareas y Responsabilidades: Control diario del stock físico. Carga y descarga de mercadería. Orden y limpieza. Preparación de Pedidos. Embalar mercadería. Requisitos: - Proactivo y responsable.- Preferentemente entre 20 a 35 años de edad.- Con experiencia mínima de 1 año en reposición, embalaje, preparación de pedidos y depósito.Nos orientamos a personas organizadas, responsable, alto nivel de compromiso y trabajo en equipo.La empresa ofrece contratación directa por convenio de Comercio y posibilidades de efectivización una vez terminada la temporada de verano.Jornada laboral de lunes a viernes de 8 a 17:30 y sábados de 8 a 12horas.Enviar su CV con foto a Beneficios La empresa ofrece contratación directa por convenio de Comercio y posibilidades de efectivización una vez terminada la temporada de verano.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 13:36:27', '10-04-2026 13:36:27', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 3, 2638, 1, NULL, 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118226948.html', '2026-04-11T07:05:54.575623');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118227219, 13145345, 'REPRESENTANTE TÉCNICO DE VENTAS', 'Capital Humano Agro', 'Para empresa nacional con destacada trayectoria en el mercado nacional e internacional, dedicada a la producción y comercialización de bioinsumos, fertilizantes, coadyuvantes y otras especialidades para el agro, seleccionaremos un/a Ingeniero/a Agrónomo para desempeñarse como Representante Técnico de Ventas en la zona Centro Sur de Córdoba y Sur de Santa Fe.El objetivo de la posición es liderar la zona asignada y ejecutar los procesos de comercialización de manera eficiente, rentable y sostenida, para alcanzar los objetivos de la empresa.Sus principales tareas serán: Ejecutar las estrategias de comercialización, definida por la empresa. Definir, juntamente con la gerencia, la Red de Distribución necesaria para el cumplimiento de los objetivos de venta. Resolver los problemas comerciales y administrativos que surjan con los Distribuidores. Cumplir con los reportes solicitados por la gerencia. Organizar y llevar a cabo charlas y/o lotes demostrativos. Mantener las cuentas corrientes dentro de los parámetros de cobro estipulados, documentación y facturación en tiempo y forma. Control de stock consignado en manos de los distribuidores (revisión remitos pendientes de facturar vs. Stock real). Participar de las reuniones periódicas de ventas coordinadas desde la gerencia. Generar información relevante de la zona (precios-productos –oportunidades de mejora). Reporte mensual y seguimiento del presupuesto de ventas acordado. Proponer planes de acción correctivos cuando fuera necesario para alcanzar los objetivos planteados. Cargar los pedidos de los Distribuidores. Informar los remitos a facturar. Informar las devoluciones a retirar. Tomar los reclamos e informarlos al responsable de Control de Calidad. Gestionar las cobranzas. Estimar las ventas zonales para la próxima campaña FORECAST de VentasSus principales responsabilidades serán: Lograr el nivel de participación en el mercado, acorde a los objetivos, en su zona de trabajo. Ejecutar los planes de trabajo en tiempo y forma. Resolver los problemas que surjan de la comercialización de los productos. Asegurar que los Distribuidores cumplan las pautas comerciales definidas. Cumplir con las políticas crediticias vigentes. Asegurar la disponibilidad de información a los Distribuidores y trasmitir las políticas de precios y crediticias para cumplir con los objetivos. Generación de demanda junto con el Distribuidor. Relacionamiento con Asesores técnicos y productores de la zona. Crear vínculos de confianza con Distribuidores Estratégicos.El profesional a incorporar reportará directamente a la Gerencia de Ventas y deberá interactuar con el área de Administración y Logística, recibiendo las capacitaciones necesarias con el área Técnica y de Marketing.La zona a cubrir es amplia, considerando el Centro y Sur de Córdoba – desde Villa María- Río Tercero hacia el sur- Las ciudades ideales de residencia actual del posible candidato son: Río Cuarto, La Carlota, Río Tercero, Villa María, Monte Buey y otras localidades de la zona.Orientamos la búsqueda a un/a candidato profesional Ingeniero Agrónomo, con una trayectoria de ventas de por lo menos 2 a 3 años en posición similar desempeñados en la zona a cubrir. Deberá ser una persona con marcada actitud comercial, orientado al logro de los objetivos y marcado enfoque en Distribuidores y generación de demanda en grupos de Asesores/Productores referentes en la zona. Deberá estar dispuesto a realizar frecuentes viajes, en muchos casos pernoctando 2 o 3 noches fuera de su hogar. Dispondrá de movilidad, viáticos, celular y Obra Social pre paga.Consideramos que es una buena oportunidad laboral para una persona dinámica y emprendedora, con un desafío muy importante a desarrollar dentro de una empresa reconocida y con productos de primer nivel. Requisitos:', 0, 'Río Cuarto, Córdoba', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 15:30:37', '10-04-2026 15:30:37', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 30, 2636, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13145345_bum_ve2928e89.jpg', 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227219.html', '2026-04-11T07:05:54.575777');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118220285, 571220, 'Representante de Ventas Comercial', 'Multigol.', 'En Multigol, somos la plataforma que transforma el ahorro en realidades tangibles. Nos dedicamos a facilitar el acceso a autos, motos e importantes sumas de dinero en efectivo a través de un sistema de cuotas accesibles y capitalización mensual.Nuestra misión es clara: brindamos una alternativa inteligente para que nuestros clientes vean crecer sus ahorros mes a mes mediante intereses competitivos y la posibilidad de cumplir sus sueños a través de los sorteos mensuales de la Lotería de la Ciudad de Buenos Aires (LotBA). Con una red de agencias en expansión, somos el puente entre el esfuerzo de la gente y sus grandes objetivos.¿Qué buscamos?En pleno proceso de crecimiento, buscamos talentos con ADN comercial que quieran ser protagonistas de esta expansión. Si te apasionan las ventas y buscás un entorno dinámico, ¡te estamos buscando! Unite a la Red de Organizadores Líder de Multigol: Liderá tu propio éxitoEn Multigol, transformamos el ahorro en realidades tangibles mediante sistemas de capitalización de vanguardia. Buscamos socios estratégicos con visión comercial que deseen profesionalizarse y desarrollar una unidad de negocios independiente con el respaldo de una marca líder en el mercado. Requisitos: Visión Empresarial: Capacidad de inversión para infraestructura inicial (Oficina/Local). Liderazgo Comprobado: Experiencia liderando y reclutando equipos de alto desempeño. Trayectoria: Mínimo 5 años en ventas (se valorará especialmente la experiencia en intangibles). Autonomía: Movilidad propia Secundario completo (excluyente). Mentalidad proactividad y alineación con nuestra planificación estratégica de éxito. Beneficios Respaldo y Legalidad: Gestión de matrícula y soporte para vos y tus Productores Asesores Independientes. Rentabilidad Superior: Esquema de comisiones de alto impacto basado en objetivos. Vanguardia Tecnológica: Acceso a CRM de última generación para la optimización de datos y prospección. Capacitación Continua: Formación técnica y comercial de alto rendimiento. Escalabilidad: Plan de carrera comprobable y crecimiento dentro de nuestra estructura nacional.', 0, 'Tucumán, Tucumán', 'Presencial', 'Full-time', '06-04-2026', '06-04-2026 17:09:18', '06-04-2026 17:09:18', '2026-04-06', NULL, NULL, '2026-04-06T00:00:00-03:00', NULL, NULL, 1, 0, 6, 35, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_571220_bum_v16f3754e.jpg', 0, 0, NULL, 2013, 'Simples Hiring Room 30-60', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118220285.html', '2026-04-11T07:05:54.575871');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225423, 13024816, 'Representante Comercial Rubro Metalúrgico - Moreno', 'Ceta Capital Humano', 'Desde Cata Capital Humano, estamos trabajando en la búsqueda de un Representante Comercial para importante empresa metalúrgica, ubicada en Parque Industrial del Oeste.La búsqueda está orientada a una persona con marcado perfil comercial, negociador y resolutivo, con buen manejo de relaciones interpersonales, buena presencia, excelente comunicación, autogestión y empatía. Requisitos: Principales responsabilidades: Atención/fidelización de la cartera de clientes actuales, como así también detectar y captar nuevos clientes para incrementar los revenues en la cartera existente. Atención/gestión de los requerimientos/reclamos de los clientes. Generación de KPI`S y reportes que permitan el adecuado seguimiento de la gestión de ventas. Promoción de productos y presentaciones con los clientes. Monitoreo y anticipación de situaciones del mercado en cuanto a novedades/tendencia/problemáticas que impacten en un resultado positivo comercial. Cobranza mensual, conciliación de cuentas de clientes con el área financiera de la empresa. Disponibilidad para realizar viajes en el país.Requisitos: Experiencia comprobable en ventas mayor a 5 años en empresas de consumo masivo atendiendo grandes cuentas de marcas directas. (Excluyente) Ingles Intermedio. Manejo de Excel (excluyente) Registro de conducir vigente Jornada de trabajo: lunes a viernes de 08:00hs a 17:00hs. Dedicación Full time. Lugar de residencia: GBA-Zona oeste o aledaños Beneficios Salario a convenirPrepaga: OSDE 210, para el titular.Contratación directa por la empresa.Beneficios (descuento en productos)Comedor: No se cuenta con el servicio, pero si las instalaciones acordes a todo lo necesario.', 0, 'Moreno, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 14:14:05', '09-04-2026 14:14:05', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 6, 23, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13024816_bum_vff8e6e29.jpg', 1, 0, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225423.html', '2026-04-11T07:05:54.575952');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118223871, 13072346, 'Representante Comercial venta de maderas y materiales de construccion', 'Valerio Oliva maderas', 'Representante Comercial de CampoResumen del PuestoEstamos en la búsqueda de un Representante Comercial de Campo proactivo y con gran capacidad de gestión para expandir nuestra base de clientes. El candidato ideal poseerá habilidades de negociación y orientación a resultados, con experiencia en el desarrollo de relaciones comerciales.Responsabilidades Identificar y contactar potenciales clientes para ofrecer nuestros productos/servicios. Desarrollar y mantener una cartera de clientes activa y rentable. Presentar propuestas comerciales y negociar términos y condiciones. Realizar seguimiento de ventas y asegurar la satisfacción del cliente. Cumplir con los objetivos de ventas establecidos.Requisitos Experiencia comprobable en ventas y desarrollo de negocios. Excelentes habilidades de comunicación, interpersonales y de negociación. Orientación a resultados y capacidad para trabajar de forma autónoma. Disponibilidad para viajar y desplazarse según las necesidades del rol. Se valorará la experiencia en el sector.', 0, 'Godoy Cruz, Mendoza', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 15:46:46', '09-04-2026 14:43:25', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 6, 23, 1, NULL, 0, 0, NULL, 750, 'Aviso Express', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118223871.html', '2026-04-11T07:05:54.576020');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118227345, 2585810, 'Jefe de Mantenimiento', 'Cook Master SRL', 'Somos una empresa líder en alimentación y servicios de consultoría alimentaria. Brindamos soluciones a la medida de cada cliente, ofreciéndole un estilo y atención personalizados.Somos una empresa joven pero contamos con más de 40 años de experiencia desarrollándonos en el ámbito gastronómico, y con el paso de los años hemos avanzado en nuestra forma de pensar y de establecer nuestro único objetivo: Garantizar una Alimentación de Calidad a grandes comunidades. Cook Master SRL está en búsqueda de un JEFE DE MANTENIMIENTO para unirse a nuestro equipo de ZONA SUR. Si eres una persona metódica y ordenada, orientada a resultados y con habilidades en administración, esta oportunidad puede ser perfecta para ti. Responsabilidades:- Coordinar el trabajo correctivo y preventivo de las cuadrillas- Controlar y asignar prioridades-Realizar evaluaciones técnicas del área-Capacitar al equipo de trabajo-Gestionar novedades de los colaboradores de las cuadrillas.- Visitar y estar en contacto con los servicios para detectar áreas de mejora-Trabajar en conjunto con los sectores que intervienen en el circuito.-Trabajar de acuerdo al SGI ( Calidad-Medioambiente-Seguridad y Salud) Si cumples con los requisitos y te motiva ser parte de nuestra empresa, no dudes en postularte para esta posición de Jefe de Mantenimiento en Cook Master SRL. Esperamos tu solicitud y te contactaremos para una entrevista.En Cook Master creemos que la diversidad nos enriquece y la inclusión nos fortalece.Como empresa B, estamos comprometidos con generar oportunidades laborales equitativas, valorando cada historia, cada talento y cada perspectiva.Todas las personas son bienvenidas a postularse, sin distinción de género, edad, origen, orientación sexual, discapacidad, identidad o trayectoria. Requisitos: Requisitos:- Manejo avanzado del paquete Office, especialmente de Excel.- Capacidad de planificación y organización, para cumplir con los plazos y objetivos establecidos.- Conocimiento técnico de Refrigeración (Freezers / Heladeras / Aires Acond / Cámaras de frio) y de equipamiento mecánico (Hornos / maquinas de las panaderías / etc)- Flexibilidad y adaptación a los cambios. tenemos mas de 40 centros (Cocinas) desde donde brindamos nuestros servicios.-Tener capacidad Organizativa y de negociación- Contar con +2 años de experiencia en puestos similares.- Contar con titulo Universitario /Ingeniería/Arquitectura o afines (Excluyente)- Contar con vehículo propio (Excluyente) Beneficios Beneficios:- Remuneración competitiva acorde a tu experiencia y habilidades.- Prepaga Galeno Plata para titular y grupo familiar, hijos menores de 21 años.- Reintegro de gastos de combustible, estacionamiento y peajes contra presentación de comprobantes y kilometraje realizado para los gastos de movilidad inherentes a la función.-Cobertura de gastos de seguro y mantenimiento según convenio automotor- Comedor en planta y/o Servicios', 0, 'San Isidro, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 16:30:44', '10-04-2026 16:30:44', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 10, 2350, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_2585810_bum_ve3fdcb36.jpg', 0, 0, NULL, 2013, 'Simples Hiring Room 30-60', 'bumeran', 'simple', 0, 0, 0, NULL, 'https://certificaciones.greatplacetowork.com.ar/cook-master', 'https://www.bumeran.com.ar/empleos/1118227345.html', '2026-04-11T07:05:54.576162');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118226495, 613620, 'Jefe de Contabilidad', 'Molino Cañuelas', '🎯Objetivo del puesto 👉🏻 Cumplir con las obligaciones legales, con la información contable. 👉🏻Brindar a la dirección información sobre el desempeño de los negocios, finanzas y otros con impacto en el flujo de caja. 👉🏻Resguardar el patrimonio a través del control administrativo de las distintas áreas 👉🏻Liderar el equipo de trabajo (Priorizar y coordinar tareas, Capacitar al equipo con las normas contables. Controlar los resultados mensuales.) 👉🏻Generar reportes contables a dirección y gerencias. ✅ Requisitos 🔹Formación: Contador Público (excluyente). 🔹Experiencia: Tener o haber tenido equipo a cargo Mínimo 2 años en posiciones similares. 🔹Conocimientos técnicos: Excel (nivel intermedio/avanzado). Sistemas de gestión contable. Normativa impositiva y manejo de portales fiscales.', 0, 'Cañuelas, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 10:00:17', '10-04-2026 10:26:06', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 1, 58, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/0/0/0/0/6/1/3/6/2/0/logoMainPic_613620_bum_ve2f1d6e1.jpg', 0, 0, 4.53, 70, 'Simples', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118226495.html', '2026-04-11T07:05:54.576324');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118226474, 13329580, 'SUPERVISOR DE SEGURIDAD', 'Global Protection Service S.A.', 'Importante empresa de servicios incorporará un Supervisor de Operaciones Zonales, para desempeñarse en la zona de CABA y Pcia. De Buenos Aires. Nos orientamos en personas con sólida experiencia en funciones de coordinación y manejo de personal. Debe residir en Ramos Mejía o aledaños.Debe poseer registro de conductor (excluyente)Secundario (Excluyente)Preferentemente estudios terciarios/universitarios en carreras afines o retirados de FFAA/FFSS. La posición requiere plena disponibilidad de horarios.Un franco semanal, turnos de 8hs.Incorporación inmediata y estabilidad laboral.', 0, 'Ramos Mejía, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 10:26:39', '10-04-2026 10:26:39', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 22, 36, 1, NULL, 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118226474.html', '2026-04-11T07:05:54.576408');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118226416, 13510965, 'Supervisor de Producción', 'FABIAN GERVASONI', 'Supervisor de ProducciónResumen del PuestoBuscamos un Supervisor de Producción con formación en Ingeniería en Alimentos o carreras afines, para unirse a nuestro equipo. El candidato ideal poseerá experiencia comprobada en la supervisión de líneas de producción continua dentro de industrias alimenticias, específicamente en la fabricación de productos cárnicos o en frigoríficos.Responsabilidades Supervisar y coordinar las operaciones diarias de la línea de producción continua. Asegurar el cumplimiento de los estándares de calidad y seguridad alimentaria. Gestionar y motivar al personal a cargo. Optimizar los procesos productivos para mejorar la eficiencia y reducir costos. Colaborar con otros departamentos para garantizar el flujo de trabajo y la entrega oportuna de productos. Implementar y supervisar las buenas prácticas de manufactura.Requisitos Título universitario en Ingeniería en Alimentos o disciplina relacionada. Experiencia previa como supervisor de producción en industrias de chacinados o frigoríficos. Conocimiento de procesos de fabricación en línea continua. Sólidos conocimientos en normativas de calidad y seguridad alimentaria. Capacidad de liderazgo y gestión de equipos. Habilidades analíticas y de resolución de problemas. Disponibilidad para trabajar en turnos rotativos si fuera necesario.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 10:23:44', '11-04-2026 02:00:26', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 16, 32, 1, NULL, NULL, NULL, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 1, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118226416.html', '2026-04-11T07:05:54.576488');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225625, 13510924, 'JEFE DE OBRA', 'PENTAMAR S.A.', 'Sus principales responsabilidades serán: Dirigir la planificación técnica, económica y operativa de la obra asignada. Coordinar y supervisar al personal técnico y operativo de obra. Gestionar recursos materiales, maquinaria y contratistas. Monitorear avances, reportar indicadores y elaborar partes diarios. Velar por el cumplimiento de las normativas de Seguridad e higiene. Actuar como referente técnico ante clientes, inspectores y organismos regulatorios. Participar en certificaciones, reuniones técnicas y gestiones administrativas. Resolver imprevistos operativos con criterio y escalar decisiones estratégicas cuando corresponda.Requisito excluyente:- Ingeniero Civil / Industrial /Mecánico / Recursos Hídricos o afines RECIBIDO.- Disponibilidad para trabajar, de ser necesario por las condiciones de obra, en jornada completa de 7 a 1 9hs con régimen de trabajo continuo.- Disponibilidad para cambiar de domicilio, dentro o fuera del país, según las obras disponibles.- Experiencia mínima de 5 años en gestión de obras públicas o privadas.Conocimientos requeridos del puesto:- Planificación de obra, lectura de planos, gestión de costos, normativa técnica y de Seguridad e Higiene, herramientas digitales (Office, AutoCAD, Proyect).Habilidades personales:- Liderazgo operativo, resolución de problemas, comunicación clara, trabajo en equipo, empatía y criterio.- Priorizaremos Profesionales dispuestos a aprender sobre operación de dragas y proactivos.Ofrecemos:Prepaga OSDE, gastos de movilidad cubiertos, Formación en Dragas y oportunidad de crecimiento profesional.INDICAR REMUNERACION NETA PRETENDIDA.', 0, 'Tigre, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 10:21:18', '10-04-2026 10:21:18', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 4, 2558, 1, NULL, NULL, NULL, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225625.html', '2026-04-11T07:05:54.576581');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225160, 13110602, 'Líder de Producto', 'Bumeran Selecta', 'Emergencia S.A. es una empresa con más de 40 años de trayectoria y dedicación en el sector salud, la institución ha evolucionado para ser mucho más que un servicio de emergencias. Se define como un equipo comprometido con la atención médica de alta calidad, orientado a generar un impacto real en la vida de las personas. Su misión integra tecnología de vanguardia con un enfoque profundamente humano, trabajando diariamente para garantizar que cada paciente reciba un cuidado personalizado y de excelencia. Nos encontramos en la búsqueda de un Lider de Producto con perfil analítico, estratégico y con visión de negocio para incorporarse a el equipo de Emergencias S.A. Segmento Contigo Salud.Serás Lider de producto del segmento " Salud, Bienestar a individuos". Su misión será gestionar su rentabilidad, garantizar la satisfacción del cliente y, sobre todo, identificar qué nuevas oportunidades nos ofrece el mercado para seguir creciendo. Gestión de Rentabilidad: Controlar márgenes, validar promociones y diseñar estrategias de mejora continua (upgrades y simplificación de catálogo). Evolución del Portfolio: Liderar el lanzamiento de nuevos planes y optimizar los productos existentes sumando funcionalidades que el mercado demanda. Articulación Clave: Ser el nexo entre IT, Facturación y proveedores externos para asegurar que la calidad del servicio sea excelente. Visión de Negocio: Investigar tendencias locales e internacionales para detectar oportunidades y definir estrategias de pricing competitivas. Análisis Post-Lanzamiento: Medir el éxito de cada iniciativa y ajustar la estrategia en base a resultados reales. Modalidad de trabajo: 4x1 Lunes a Viernes de 9 a 18hs. Zona: Coghlan - CABA. Sexo y Edad: Indistinto. Requisitos: Formación: Profesionales graduados en Administración de Empresas, Comercialización, Ingeniería Industrial o carreras afines con visión de negocios. Experiencia: Mínimo de 4 años de trayectoria en áreas de Producto, habiendo liderado equipos de trabajo (excluyente). Expertise funcional: Experiencia sólida gestionando carteras de productos o en posiciones de Business Intelligence y Análisis Comercial. Mentalidad Analítica: Capacidad técnica para interpretar grandes volúmenes de datos y transformarlos en decisiones estratégicas de negocio. Metodologías: Conocimiento sólido en gestión de proyectos (PMI o metodologías Agile). Herramientas de Gestión: Manejo fluido de plataformas como JIRA, Trello o similares. Dominio Técnico: Manejo avanzado de Office 365 (especialmente Excel para el análisis de márgenes y rentabilidad). Competencias Valoradas (Deseables): Visualización de Datos: Conocimientos en Power BI para el armado de tableros de control. (Deseable) Visión de Mercado: Experiencia previa en detección de tendencias y desarrollo de nuevos negocios. Habilidades Blandas: Buscamos un perfil con fuerte capacidad de influencia, negociación y liderazgo, capaz de articular soluciones con áreas de IT, Operaciones y proveedores externos. Beneficios Bono anual por objetivos. Prepaga para el titular y grupo familiar. Modalidad Hibrida. Dia libre de Cumpleaños. Viernes Flex en verano. Horario Flex en inicio escolar. Obsequios y beneficios corporativos.', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '09-04-2026', '09-04-2026 12:42:41', '09-04-2026 12:42:41', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 6, 2628, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13110602_bum_vab9a2cbb.jpg', 1, 0, 3.7, 10, 'Home', 'bumeran', 'home', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225160.html', '2026-04-11T07:05:54.576708');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118226009, 13024816, 'Responsable de Inventarios', 'Ceta Capital Humano', '🚀 ¡Súmate a una empresa en crecimiento!En Ceta Capital Humano nos encontramos en la búsqueda de un/a Responsable de Inventario, Pañol y Abastecimiento para una importante empresa ubicada en Zona Oeste, GBA.Nos orientamos a perfiles organizados, metódicos y con experiencia en gestión de stock, abastecimiento interno y control de materiales en entornos productivos.🎯 Objetivo de la posición:Gestionar y controlar el inventario de materiales, insumos y herramientas, asegurando su correcta recepción, registro, almacenamiento y disponibilidad para la operación, garantizando la confiabilidad del stock físico y sistémico, la adecuada administración del pañol y el abastecimiento oportuno a producción en línea con la planificación, contribuyendo a la eficiencia y continuidad operativa del taller.📌 Principales responsabilidades: Controlar la recepción, verificación y registro de materiales e insumos • Mantener la consistencia entre el stock físico y el sistema • Garantizar el abastecimiento oportuno a producción según planificación • Administrar el pañol (entrega, devolución y control de herramientas) • Gestionar solicitudes de compra y reposición de materiales • Realizar inventarios periódicos y reportar desvíos • Controlar movimientos internos y reservas de materiales • Participar en la gestión de scrap y recortes • Mantener el orden del sector bajo metodología 5S • Informar desvíos o faltantes que impacten en la operación🎓 Formación requerida: • Secundario completo técnico (excluyente)✅ Requisitos: • Experiencia mínima de 2 años en posiciones vinculadas a gestión de inventarios, almacenes, pañol, deposito o abastecimiento • Manejo de sistema de gestión SAP (excluyente) • Manejo de Excel Intermedio (excluyente)💼 Competencias que valoramos: • Organización y atención al detalle • Responsabilidad y compromiso • Proactividad • Trabajo en equipo • Compromiso con la trazabilidad y el control📍 Condiciones: Modalidad: presencial Jornada: lunes a viernes de 06:00 a 16:00 Zona de trabajo: Zona Oeste, GBA🎁 Importantes beneficiosSi cumplís con los requisitos y querés sumarte a un equipo en crecimiento, ¡esperamos tu postulación! 🚀', 0, 'Castelar, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 18:03:10', '09-04-2026 18:03:10', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 3, 2638, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13024816_bum_vff8e6e29.jpg', 1, 0, NULL, 70, 'Simples', 'bumeran', 'simple', 1, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118226009.html', '2026-04-11T07:05:54.576837');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225556, NULL, 'Jefe de Deposito', 'Confidencial', 'Importante distribuidora ubicada en Moreno se encuentra en la búsqueda de un Jefe de Depósito para incorporar a su equipo de trabajo.🔹 Responsabilidades principales: Supervisar la operatoria diaria del depósito. Coordinar recepción, almacenamiento y despacho de mercadería. Gestionar y liderar equipos de trabajo. Controlar stock e inventarios. Optimizar procesos logísticos y operativos.🔹 Requisitos: 5 años o mas de experiencia comprobable en posiciones similares. Capacidad de liderazgo y organización. Perfil proactivo y orientado a resultados. Conocimiento de sistema Digip WMS o similar. Liderazgo. Conducción, Gestión y Coordinación del Personal del Depósito.🔹 Condiciones: Relación de Dependencia. Full time.🔹 Se ofrece: Incorporación inmediata. Buen clima laboral.', 1, 'Moreno, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 15:01:34', '09-04-2026 16:18:29', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 3, 2638, 1, NULL, NULL, NULL, NULL, 70, 'Simples', 'bumeran', 'simple', 1, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225556.html', '2026-04-11T07:05:54.576912');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224767, 13509888, 'Encargado de campo', 'Maria Julia Conti', 'Somos una consultora integrada por un grupo de profesionales especializados en la gestión de los recursos humanos. NOS nace como un emprendimiento independiente, con el objetivo de brindar al mercado una propuesta personalizada abocada a obtener resultados óptimos en la gestión y el desarrollo del capital humano, trabajando con compromiso, seriedad, transparencia y responsabilidad. Visión: Brindar un servicio especializado, trabajar con cada una de nuestras empresas-clientes de modo personalizado, a fin de poder cubrir de manera eficiente las necesidades y demandas particulares de cada cliente. Misión: Ofrecer soluciones integrales, colocando el foco en el capital humano de las organizaciones. Valores: Teniendo como valores principales la excelencia en la calidad de nuestros procesos, compromiso con nuestro trabajo, ética profesional y confidencialidad con el cliente. Nos encontramos en la búsqueda de un ENCARGADO DE CAMPO. Para establecimiento agropecuario ubicado en la localidad de Del Campillo, Provincia de Córdoba.Si te apasiona el trabajo en el campo y tenés experiencia coordinando equipos y procesos productivos, esta oportunidad es para vos.LA MISIÓN DEL PUESTO SERÁ:Coordinar y controlar las tareas necesarias para implementar el plan de producción en su totalidad y mantener la estructura del campo, garantizando el buen funcionamiento y mantenimiento de equipos y maquinarias. Coordinar y atender las necesidades del equipo del trabajo a su cargo y reportar a la administración toda información relevante.PRINCIPALES TAREAS*Proceso de siembra:Iniciar la siembra cuando estén dadas las condiciones de humedad siguiendo las indicaciones de las ordenes de trabajo (lote, hibrido/variedad, densidad, dosis, prescripción, etc).Calibrar las máquinas.Controlar la profundidad, distribución espacial (maíz) y cantidad total usada por loteSacar muestras de semilla de bolsones.Organizar la logística de siembra (inoculación, manejo de semillas/fertilizantes)*Proceso de cosecha:Indicar por cual lote comenzar a cosecharControlar pérdidas y calidad de grano en cosechaOrganizar la logística / carga de camionesTomar muestras de humedad por camiónInformar al balancero humedad y origen del camión (lote/bolsón).Dirigir donde confeccionar silobolsas.*Logística de combustible.*Proceso de Stock: controlar y llevar al día las planillas de stock e informar al Resp. de logística según plan de información los siguientes stocks: combustible, granos, semillas, agroquímicos, fertilizantes, silobolsas. repuestos, granos.*Mantenimiento de maquinarias.*Planificar y coordinar las tareas de conservación de estructura (caminos, parque, instalaciones, etc.).*Controlar las labores de los contratistas.*Gestión de residuos.*Emitir reportes a la administración según necesidad. Si te interesa asumir un rol clave en la gestión integral del campo, con autonomía y responsabilidad en la toma de decisiones operativas, te invitamos a postularte.Buscamos una persona comprometida, organizada y con capacidad de liderazgo, que quiera desarrollarse en una empresa agropecuaria en crecimiento. Requisitos: VALORAMOS ESPECIALMENTE Experiencia previa en posiciones similares al menos 3 años. Conocimientos en siembra, cosecha y manejo de maquinaria Capacidad de liderazgo y organización Manejo básico de Excel / sistemas de gestión Formación terciaria o universitaria en carreras agropecuarias o afines. Carnet de conducir - Movilidad Propia. Beneficios CONDICIONES DE TRABAJO:Lugar de trabajo Del Campillo, provincia de Córdoba. Posibilidad de residir en el campo o en localidades cercanas. Relación de dependencia + salario competitivo. Disponibilidad full time.', 0, 'Del Campillo, Córdoba', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 10:17:41', '09-04-2026 10:17:41', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 16, 2602, 1, NULL, NULL, NULL, NULL, 2013, 'Simples Hiring Room 30-60', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224767.html', '2026-04-11T07:05:54.577036');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224760, 13024816, 'Supervisor de mantenimiento', 'Ceta Capital Humano', '🚀 ¡Súmate a una empresa en crecimiento!Nos encontramos en la búsqueda de un Supervisor de Turno para una importante empresa del rubro alimenticio, ubicada en Zona Oeste.Nos orientamos a perfiles con experiencia en entornos productivos, liderazgo de equipos y capacidad para gestionar la operación diaria en planta.🎯 Objetivo de la posición:Planificar y coordinar las actividades de mantenimiento de planta, garantizando la operatividad de las líneas de producción, en cumplimiento con los estándares de seguridad alimentaria, normas SHE y el presupuesto definido.📌 Principales responsabilidades: Definir y supervisar el plan de mantenimiento, asegurando el cumplimiento de los indicadores claves. Elaborar el presupuesto del área de mantenimiento y realizar el seguimiento del gasto, garantizando el control de costos y la previsibilidad financiera. Seleccionar, gestionar y evaluar proveedores de servicios, asegurando la calidad y cumplimiento de los trabajos realizados. Autorizar la adquisición de materiales y servicios, conforme a las políticas de compras de la compañía. Promover el trabajo en equipo e implementar las políticas corporativas, contribuyendo a la mejora continua.🎓 Formación requerida: Formación técnica o universitaria en Ingeniería (Industrial, Electromecánica o afines) (Excluyente)✅ Requisitos: Experiencia en supervisión dentro de plantas industriales (idealmente alimenticias). Conocimientos en normas y prácticas de calidad e inocuidad dentro de entornos productivos. Manejo de herramientas informáticas y sistemas de gestión.💼 Competencias que valoramos: Liderazgo • Trabajo en equipo • Resolución de problemas • Organización • Proactividad • Orientación a resultados📍 Condiciones: Modalidad presencial • Lugar de trabajo: Zona oeste, GBA • Días y horario: lunes a viernes 08:00 a 17:00.🎁 Importantes Beneficios.📩 Si te interesa formar parte de una compañía dinámica dentro de la industria alimenticia, ¡te invitamos a postularte!', 0, 'Ituzaingó, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 10:11:45', '09-04-2026 10:48:40', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 16, 70, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13024816_bum_vff8e6e29.jpg', 1, 0, NULL, 70, 'Simples', 'bumeran', 'simple', 1, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224760.html', '2026-04-11T07:05:54.577142');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225795, 13051395, 'Jefe de Ventas', 'Saiba Recursos Humanos', 'Nuestro cliente, una importante empresa dedicada a la importación, exportación, distribución y comercialización de productos de transmisión de potencia y transporte, incorporará:Jefe de VentasBuscamos profesionales graduados o próximos a graduarse de carreras de Ingeniería, preferentemente Mecánica, Industrial o afines, con sólida experiencia en venta en canal industrial de diversos tipos de industrias con interacción en las áreas de mantenimiento, compras indirectas de repuestos e ingeniería de proyectos. Manejo de cartera activa de clientes y conocimiento del mercado. Tengan muy buen manejo de herramientas digitales e idioma inglés avanzado. Cuenten con disponibilidad para viajar. Las principales responsabilidades que tendrá asignadas son:Diseñar e implementar la estrategia de ventas B2B alineada a los objetivos del negocio.Gestionar y desarrollar una cartera propia de clientes activa, asegurando crecimiento sostenido.Identificar oportunidades de negocio en el mercado industrial y fortalecer la presencia comercial.Confeccionar y realizar seguimiento de indicadores de gestión y resultados comerciales.Trabajar en conjunto con la dirección comercial en la evolución del modelo de negocio, asegurando prácticas comerciales alineadas a valores de la compañía.Valoramos candidatos proactivos, con iniciativa y capacidad para establecer relaciones comerciales, que combine habilidades de liderazgo y trabajo en equipo con autonomía en la gestión. Con fuerte orientación a resultados, destacándose por su compromiso, ética profesional y confiabilidad.La empresa está ubicada en Zona Sur, CABA, y la modalidad de trabajo es híbrida.', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '09-04-2026', '09-04-2026 16:51:33', '10-04-2026 09:22:18', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 6, 23, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/0/0/1/3/0/5/1/3/9/5/logoMainPic_13051395_bum_vb3b6d5e1.jpg', 0, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225795.html', '2026-04-11T07:05:54.577223');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224853, 517210, 'Responsable de Finanzas', 'de Elizalde - Desarrollo del Talento', 'Importante empresa nacional dedicada a la importación y comercialización de una amplia gama de herramientas manuales y eléctricas, equipos de construcción y productos para actividades al aire libre, con presencia en Argentina, México y Uruguay, y proyección de crecimiento y expansión. Buscamos un/a Responsable de Finanzas con visión estratégica y capacidad ejecutiva para profesionalizar la gestión financiera y acompañar el crecimiento del negocio.La misión principal será liderar la transición hacia un área financiera de alto rendimiento, brindando claridad y soporte técnico a los dueños para la toma de decisiones críticas.Tus responsabilidades principales incluirán: Profesionalización del área: Diseñar e implementar procesos financieros sólidos y escalables. Planificación Estratégica: Elaboración y seguimiento de Cash Flow, P&L (Estado de Resultados) y Forecast dinámicos. Análisis de Negocios: Evaluar la rentabilidad de nuevas unidades de negocio y proyectos de inversión. Gestión de Tesorería: Control de cuentas bancarias y ejecución de pagos. Business Intelligence: Generar reportes e indicadores clave (KPIs) que transformen datos en información útil para la dirección. Requisitos: La búsqueda se orienta a alguien que combine el rigor técnico con la agilidad que requiere el comercio internacional y digital.Requisitos Excluyentes: Formación: Profesional graduado de carreras de Ciencias Económicas (Contador Público, Lic. en Administración, Lic. en Economía o afines). Conocimientos Técnicos: Dominio sólido de normas contables de México. Experiencia: Trayectoria previa en posiciones de similares responsabilidades, con capacidad para armar reportes desde cero. Requisitos Deseables: Experiencia en E-commerce: Se valorará especialmente a quienes vengan de sectores de venta online, acostumbrados a la vorágine, el dinamismo y el volumen de transacciones de este rubro. Beneficios Se ofrecen excelentes condiciones de contratación, ambiente colaborativo de trabajo, posibilidades de poner tu impronta y ser un socio estratégico del negocio.Trabajo híbrido en Castelar o zona Norte.', 0, 'Castelar, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 11:00:58', '10-04-2026 14:35:12', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 1, 25, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_517210_bum_v56bd8b8b.jpg', 0, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224853.html', '2026-04-11T07:05:54.577318');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118226458, NULL, 'Encargado de Compras Restaurante de Categoria', 'Confidencial', 'Importante restaurante de categoría, ubicado en Los Cardales, se encuentra en la búsqueda de un/a Encargado/a de Compras para gestionar de forma integral el abastecimiento del establecimiento.Buscamos un perfil con experiencia en gastronomía (excluyente), organizado, proactivo y con capacidad de anticiparse a las necesidades del negocio, trabajando en contacto directo con las áreas de stock y facturación.🔹 Responsabilidades Gestión integral de compras gastronómicas. Contacto, seguimiento y negociación con proveedores. Retiro de mercadería y control de calidad, cantidades y precios. Control de stock y previsión de faltantes. Coordinación permanente con las áreas de facturación y control de stock. Organización de pedidos según consumo y demanda del restaurante. Carga y seguimiento de información en sistemas.🔹 Requisitos Experiencia previa como Encargado/a de Compras en gastronomía (excluyente). Conocimiento del funcionamiento de restaurantes de categoría. Buen manejo de Excel y sistemas de gestión. Perfil proactivo, responsable, organizado y resolutivo. Capacidad de planificación y negociación. Movilidad propia (excluyente).🔹 Condiciones Jornada: Lunes a viernes o martes a sábado (a definir según demanda). Modalidad: Presencial. Zona de trabajo: Los Cardales. Remuneración acorde a la experiencia y responsabilidades. Estabilidad laboral en un proyecto gastronómico consolidado.', 1, 'Los Cardales, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 07:40:46', '10-04-2026 11:16:47', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 10, 2350, 1, NULL, NULL, NULL, NULL, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118226458.html', '2026-04-11T07:05:54.577401');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118222768, NULL, 'Analista Contable Sr para Restaurante en Los Cardales', 'Confidencial', 'Restaurante de categoria ubicado en Los Cardales, busca incorporar una Analista Contable Sr con experiencia previa comprobable.Dentro de sus tareas debera :. Ejecutar conciliaciones bancarias y de cuentas corrientes de clientes, proveedores e impuestos, asegurando la exactitud de los registros contables. Dar soporte a la operación diaria Gestionar la contabilidad general de la empresa, garantizando el cumplimiento de las normativas vigentes y las buenas prácticas contables. Elaborar balances, estados contables e informes financieros, brindando soporte en la toma de decisiones. Preparar, revisar y presentar las liquidaciones impositivas mensuales y anuales ante los organismos correspondientes Supervisar y verificar la correcta imputación de las operaciones contables en el sistema, manteniendo la integridad y consistencia de la información registrada. Seguimiento de temas societariosPresencial: lunes a viernes de 9 a 18hs.Se trabaja algunos dias en oficina en Martinez y uno o dos dias en Los CardalesSe ofrecen buenas condiciones de contratacion', 1, 'Los Cardales, Buenos Aires', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 07:50:00', '10-04-2026 09:57:44', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 1, 58, 1, NULL, NULL, NULL, NULL, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118222768.html', '2026-04-11T07:05:54.577471');
