INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2179292, 570364, 'Analista Técnico Funcional de Pasivas - Híbrido - Retiro - 1816', 'Aliantec', '¿Qué hace la compañía?Importante banco nacional de capitales privados con la mayor red de sucursales en Argentina. Brindan distintos servicios financieros a más de 4 millones de clientes, tanto en banca individuos como en banca empresas.¿Qué necesitás para ser parte del equipo?A nivel personal: Buen manejo de comunicación oral / escrita. Experiencia para trabajar en equipo. Autonomía Buena predisposición para el aprendizaje permanente de nuevas tecnologías.A nivel técnico: Contar con más de 3 años de experiencia como Analista Funcional de sistemas bancarios de PASIVAS. | Excluyente. Experiencia en Sistemas relacionado a módulo Pasivas | Excluyente. Experiencia en conceptos relacionados a las cuentas bancarias. Experiencia en análisis funcional y técnico para brindar soluciones escalables y robustas. Experiencia en documentación, especificación técnica para desarrollos de software. Experiencia en Soporte a Producción. Experiencia en SQL. Será deseable contar con experiencia trabajando con JIRA. Ser estudiante o egresado de carreras de formación en informática, Análisis de sistemas, Tecnología de la Información o carreras afines.¿Qué vas a hacer? Análisis funcional y técnico de las iniciativas planteadas por el Usuario, relacionadas a Cuentas (Cajas de Ahorro - Cuentas Corrientes - Paquetes de Productos). Participar en la planificación y ejecución de proyectos de implementación de las iniciativas solicitadas. Entender procesos y necesidades del usuario. Definir los requerimientos técnico-funcionales y brindar soluciones adecuadas para soportar dichos requerimientos. Participar activamente en el relevamiento y diseño de soluciones integradas. Funcionar como nexo entre el usuario, los equipos técnicos y proveedores. Dar soporte al usuario. Evaluar, monitorear y solucionar problemas. Preparar documentación de alcance, funcional, plan de pruebas y despliegue. Realizar pruebas unitarias e integrales. Dar soporte a los Usuarios en etapa de pruebas.¿Cuál es el desafío de la posición?El objetivo del puesto será brindar soporte integral al área de Pasivas, colaborando en la resolución de incidentes y desbloqueo de errores en los procesos productivos tanto batch como online.¿Con quién trabajarás?Trabajarás junto al equipo de Pasivas, compuesto por diversos analistas.¿Cuándo y dónde trabajarás?Trabajarás en un esquema híbrido asistiendo 3 días en las oficinas del cliente en la zona de Retiro y 2 días de Home Office, de lunes a viernes de 9-18 h¿Qué ofrecen? Relación de dependencia directa. Prepaga Galeno Oro. Convenio Bancario. Día del bancario: feriado y bono. Descuentos en productos. Monto fijo de guarderías para madres y padres. Becas de grado y posgrado. Licencia por estudio. Más de 200 cursos y rutas de aprendizaje para capacitarte. Descuentos en SportClub. Campañas de vacunación. Descuento en clínicas y consultas médicas virtuales. Kits escolares para tus hijos + regalo del día de las infancias Gratificación por matrimonio y por nacimiento.¿De qué fases consta el proceso de selección?Tendrás una primera entrevista con nuestras recruiters, Carla Carrizo y Rocío Albelo, para conocer tus experiencias laborales e intereses.Luego, participarás de dos entrevistas con nuestro cliente, conociendo al líder en primera instancia y a la Gerencia en segunda', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '09-04-2026', '09-04-2026 16:25:42', '09-04-2026 16:25:42', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 19, 2618, 1, 'https://imgzj.jobscdn.com/portal/img/empresas/1/static/logoMainPic_570364_bum_v183b0a04.jpg', 0, 0, NULL, 1020, 'Aviso Select', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2179292.html', '2026-04-11T07:05:54.578630');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2179296, 570364, 'Desarrollador Salesforce Sr. (Reglas de Negocio) - Mix (Onsite - Remoto) - Retiro - 1808', 'Aliantec', '¿Qué hace la compañía?Importante Banco Nacional de capitales privados con la mayor red de sucursales en Argentina. Brindan distintos servicios financieros a más de 4 millones de clientes, tanto en banca individuos como en banca empresas.¿Qué necesitás para ser parte del equipo?A nivel personal: Capacidad analítica para traducir procesos de negocio en lógica técnica. Habilidades de comunicación para interactuar con equipos de negocio y tecnología. Orientación a resultados. Proactividad y capacidad de trabajo colaborativo. Orientación al cumplimiento de estándares y calidad de datos.A nivel técnico: Al menos 4 años de experiencia trabajando en roles similares de customización de CRM y motores de decisión | Excluyente. Dominio de Salesforce Business Rules Engine (BRE) | Excluyente. Manejo avanzado de Flow Builder para automatización de procesos | Excluyente. Conocimientos en Apex para optimización de lógica de negocio | Excluyente. Experiencia en reportes y dashboards en Salesforce. Conocimiento de Financial Services Cloud (deseable) Experiencia en metodologías ágiles. Entendimiento de modelos de datos aplicados a CRM/CDP y marketing. Estudios: Estudiante avanzado o graduado/a en Sistemas, Ingeniería, Ciencias de Datos o carreras afines.¿Qué vas a hacer? Implementarás y mantendrás reglas de negocio utilizando Expression Sets, Decision Matrices y Decision Tables en BRE. Diseñarás y construirás flujos complejos en Flow Builder para automatizar la toma de decisiones en tiempo real. Desarrollarás componentes en Apex para extender y optimizar las capacidades del motor de reglas. Asegurarás la consistencia de datos entre Salesforce Core, Data Cloud y Marketing Cloud. Configurarás reportes y dashboards para monitorear la ejecución y performance de las reglas. Documentarás la lógica técnica y gestionarás el versionado de los motores de reglas. Colaborarás con equipos de negocio y tecnología para traducir requerimientos en soluciones escalables.¿Cuál es el desafío de la posición?Serás protagonista en la evolución del motor de decisiones de Banca Individuo, impactando directamente en la experiencia que vive el cliente cada vez que interactúa con el banco. Ya sea desde el motor de reglas (BRE) o desde la gestión integral de Salesforce Financial Services Cloud, el rol combina visión de negocio y profundidad técnica para transformar necesidades comerciales y analíticas en decisiones y experiencias concretas dentro del CRM.¿Con quién trabajarás?Trabajarás dentro de la gerencia de Marketing & BI de Banca Individuo, en un equipo que articula CRM, motor de decisiones y analítica avanzada. Tendrás interacción directa con referentes funcionales, equipo de Datos en GCP y perfiles técnicos de Salesforce, en un entorno colaborativo donde negocio y tecnología trabajan de forma integrada.¿Cuándo y dónde trabajarás?Trabajarás en un esquema híbrido asistiendo 3 días en las oficinas del cliente en la zona de Retiro y 2 días de Home Office, de lunes a viernes de 9-18 h¿Qué ofrecen? Relación de dependencia directa. Convenio Bancario. Día del bancario: feriado y bono. Descuentos en productos. Monto fijo de guarderías para madre y padres. Becas de grado y posgrado. Licencia por estudio. Más de 200 cursos y rutas de aprendizaje para capacitarte. Descuentos en SportClub. Campañas de vacunación. Descuento en Clínicas y consultas médicas virtuales. Kits escolares para tus hijos + regalo del día de las infancias Gratificación por matrimonio y por nacimiento.¿De qué fases consta el proceso de selección?Tendrás una primera entrevista con nuestra Recruiter, Rocío Albelo, para conocer tus experiencias laborales e intereses.Luego, participarás de dos entrevistas con nuestro cliente, conociendo al líder en primera instancia y a la Gerencia en segunda.', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '09-04-2026', '09-04-2026 16:34:10', '09-04-2026 16:34:10', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 19, 2621, 1, 'https://imgzj.jobscdn.com/portal/img/empresas/1/static/logoMainPic_570364_bum_v183b0a04.jpg', 0, 0, NULL, 1020, 'Aviso Select', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2179296.html', '2026-04-11T07:05:54.578781');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118227023, 10228958, 'Vendedores- ROSARIO', 'OneClick', 'OneClick es un distribuidor y proveedor de servicios autorizado de Apple (APR). Nuestras tiendas ofrecen la línea completa de productos Apple y proporcionan la experiencia de compra única que ha caracterizado a Apple a través de varios años de éxito sin precedentes. OneClick también ofrece soporte técnico para soluciones de hardware, software y soporte para almacenamiento de datos para cualquiera de los productos de Apple. Un Distribuidor Autorizado es un socio independiente de Apple Inc. que con el tiempo ha demostrado un conocimiento excepcional, consistente y completo de la tecnología de la marca, vende toda su línea de hardware y software, ofrece un servicio completo y soporte para sus productos y ha sido designado como un socio estratégico del fabricante.Contamos con tiendas en Rosario, CABA y Córdoba como también una fuerte presencia online. Somos tienda oficial Apple en Mercado Libre y estamos presentes en los principales marketplaces digitales del país. Estamos en la búsqueda de un vendedor para unirse a nuestro equipo en Rosario. Como vendedor, tendrás la oportunidad de formar parte de un equipo dinámico y apasionado, brindando una experiencia de compra excepcional a nuestros clientes.En esta posición, serás responsable de asesorar a los clientes, ofrecer soluciones personalizadas a sus necesidades y asegurarte de que disfruten de una experiencia única en nuestra tienda. Además, tendrás la oportunidad de trabajar con la línea completa de productos Apple, brindando soporte técnico y promoviendo la excelencia en el servicio al cliente.Buscamos a alguien apasionado por la tecnología, proactivo y con excelentes habilidades de comunicación. Si te consideras un apasionado de la venta y el servicio al cliente, ¡queremos conocerte! Requisitos: Deberá contar con un profundo compromiso por el servicio al cliente, personalidad emprendedora y habilidades para el trato interpersonal y el trabajo en equipo.Se valorarán experiencias previas en puestos similares y conocimientos de productos informáticos. Usuarios y/o conocedores de Apple bienvenidos!Buscamos disponibilidad FULL TIME, con posibilidades de trabajar fines de semana y feriados.Se valorará el conocimiento del idioma inglés. Beneficios Te ofrecemos Dos francos semanales Día de cumpleaños libre. ‍ Paternidad Extendida. ️ Excelente clima laboral ️ Club de Beneficios', 0, 'Rosario, Santa Fe', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 14:09:56', '10-04-2026 14:09:56', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 6, 35, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/0/0/1/0/2/2/8/9/5/8/logoMainPic_10228958_bum_v2a070a6d.jpg', 1, 0, NULL, 2013, 'Simples Hiring Room 30-60', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227023.html', '2026-04-11T07:05:54.578891');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118219726, 13233419, 'Asesor comercial Salud (ROSARIO)', 'ONIX HUMAN RESOURCES CONSULTING S.A.', 'Avalian es una empresa de medicina prepaga argentina que brinda cobertura médica a sus afiliados en todo el país. Originalmente se llamaba ACA Salud y ofrece una variedad de planes de salud, servicios como telemedicina (Avalian e-doc) y asistencia al viajero, y forma parte de un grupo cooperativo que incluye a la Asociación de Cooperativas Argentinas (ACA) y otras entidades. Asesor Comercial (para importante medicina prepaga) Ubicación: ROSARIO, SANTA FE Modalidad: HíbridoMisión del rolBrindar asesoramiento integral a potenciales asociados, impulsando la incorporación de nuevos clientes y contribuyendo al posicionamiento de la prepaga en la región, mediante una gestión comercial consultiva y orientada a resultados. Responsabilidades principales Realizar venta consultiva, brindando asesoramiento profesional sobre planes, coberturas y condiciones comerciales. Desarrollar acciones comerciales: prospección activa, llamados, entrevistas, envío de cotizaciones y gestión de referidos. Cumplir los objetivos mensuales y reportar avances al Coordinador/Líder Comercial. Analizar la región, competencia y oportunidades de mercado para detectar nuevos prospectos. Participar en reuniones de ventas, guardias en Centros de Atención y acciones comerciales. Actualizar el CRM (Salesforce) y mantener organizada la base de potenciales asociados. Trabajar en equipo con áreas internas: Administración de Ventas, Auditoría Médica, Operaciones y Legales, para garantizar un alta correcta del asociado. Prevenir situaciones de fraude y asegurar el cumplimiento de los procesos internos. Requisitos: Requisitos Secundario completo (excluyente). Terciario o universitario en curso o finalizado en carreras comerciales, administración, marketing, relaciones públicas o afines (no excluyente). Experiencia mínima de 2 años en ventas, idealmente en empresas de salud, seguros o servicios intangibles Manejo de Office (nivel intermedio) o salesforce (plus!) Conocimientos deseables: negociación, coberturas de planes de salud, procesos comerciales. Perfil orientado a resultados, con excelente comunicación, autonomía, proactividad y capacidad de trabajo en equipo. Poseer computadora propia! Beneficios Beneficios Capacitaciones constantes Prepaga para vos y tu familia Día libre de cumpleaños Programa de beneficios y descuentos Celular corporativo Descuentos en telefonía celular Descuentos en membresías de gimnasios Descuentos en ópticas, Beneficios en seguros Programa de salud integral anual', 0, 'Rosario, Santa Fe', 'Híbrido', 'Full-time', '06-04-2026', '06-04-2026 13:19:58', '09-04-2026 17:29:08', '2026-04-06', NULL, NULL, '2026-04-06T00:00:00-03:00', NULL, NULL, 10, 0, 6, 35, 1, NULL, 0, 0, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118219726.html', '2026-04-11T07:05:54.578988');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118226582, 13176203, 'Gerente de RRHH', 'B&B Consultores', '¡Atención San Nicolás y alrededores!¿Sos un líder con visión estratégica y amplia experiencia en relaciones laborales?Buscamos un Gerente de RRHH para liderar la profesionalización y ser el motor del cambio organizacional en una empresa referente del sector construcción en expansión. Ubicación: San Nicolás o localidades cercanas Horario: Jornada full time de lunes a viernesResponsabilidades: Cultura y clima: Ser embajador de los valores, impulsando el bienestar, la comunicación interna y actividades de integración. Transformación organizacional: Diseñar e implementar procesos que profesionalicen el área (estructuras, flujos de trabajo y mejora continua). Gestión sindical: Liderar las relaciones laborales, mediación de conflictos y cumplimiento normativo. Desarrollo de talento: Liderar planes de formación, inducción y atracción de talentos. Asesoría estratégica: Actuar como socio de la Dirección, Gerencia General y líderes de área en la toma de decisiones. Liderazgo de equipo: Coordinar equipo a su cargo. Requisitos: Formación: Lic. en Recursos Humanos, Relaciones Laborales, Administración o afines. Deseable Postgrado en Derecho Laboral o Relaciones Laborales. Experiencia: Mínimo de 4 a 6 años en posiciones similares, preferentemente en empresas constructoras o industriales. Conocimientos: manejo de convenio UOCRA, relaciones laborales y normativa laboral vigente. Habilidades: Capacidad de negociación, visión analítica, excelentes habilidades interpersonales y de organización. Beneficios Posición permanente con impacto real en los resultados y participación en decisiones estratégicas. Obra Social Prepaga: Swiss Medical (Plan para grupo familiar). Desarrollo: Posibilidades de crecimiento en un entorno de profesionalización constante. Ambiente: Excelente clima laboral y autonomía para proponer mejoras.', 0, 'San Nicolás de Los Arroyos, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 11:02:56', '10-04-2026 11:02:56', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 17, 48, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13176203_bum_vd10a9d43.jpg', 1, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118226582.html', '2026-04-11T07:05:54.579076');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118221370, 444640, 'Chequeador de camión de recolección zona Boulogne , San Isidro', 'Grupo Gestión', 'Importante empresa líder en el sector de ingeniería y construcción solicita Chequeador de camión de recolección.Requisitos deseables:Experiencia comprobable en mecánica de camiones de recolección.Responsabilidades:Realizar el control y verificación de los camiones de recolección, asegurando su correcto funcionamiento.Detectar y reportar fallas mecánicas.Colaborar en el mantenimiento preventivo y correctivo de la flota.El horario es rotativo turno mañana, tarde y noche (6.00hs a 14.00hs- 14.00hs a 22.00hs- 22.00hs a 06.00hs) (con posibilidad de realizar horas extras).Los horarios pueden varíar dependiendo del requerimiento del jefe de sector.Zona: Boulogne, San Isidro.Posición eventual con posibilidad de efectivizacion.', 0, 'San Isidro, Buenos Aires', 'Presencial', 'Full-time', '07-04-2026', '07-04-2026 12:48:00', '09-04-2026 09:22:35', '2026-04-07', NULL, NULL, '2026-04-07T00:00:00-03:00', NULL, NULL, 1, 0, 16, 70, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_444640_bum_vce78c1c9.jpg', 1, 0, 4.02, 70, 'Simples', 'bumeran', 'simple', 1, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118221370.html', '2026-04-11T07:05:54.579141');
