INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118221078, 945060, 'Analista Administrativo/a Contable Senior - Zona San Martin', 'Asoko Tempo SA', 'Nos encontramos en la búsqueda de un Analista Administrativo Contable para incorporarse a una empresa nacional lider en el rubro agroquimico con mas de 23 años de trayectoria.El objetivo de la posición es liderar operativamente el flujo de fondos y asegurar la eficiencia en las conciliaciones y la relación con terceros (bancos y proveedores).Responsabilidades Principales:Gestión de Tesorería: Manejo integral del flujo de fondos (Cash Flow), pagos a proveedores y gestión de cobranzas.Conciliaciones: Realización de conciliaciones bancarias y de cuentas corrientes.Interacción Institucional: Relacionamiento directo con entidades bancarias y negociación operativa con proveedores.Toma de Decisiones: Resolución autónoma de tareas operativas diarias para optimizar los procesos del área.Requisitos del Perfil:Formación Académica: Estudiantes avanzados o graduados de la carrera de Administración de Empresas, Contador Público o afines.Experiencia Técnica (Excluyente): Manejo avanzado y comprobable de sistema Tango Gestión.Conocimientos Específicos: Experiencia sólida en conciliaciones, manejo de bancos y circuitos de pagos/cobros.Proactividad: marcado perfil orientado a resultados y excelentes relaciones interpersonales.Autonomía: Capacidad para gestionar sus tareas con independencia y criterio profesional.Se Ofrece:Contrato eventual con posibilidad de efectivizacionPosibilidades de desarrollo profesional.Modalidad de trabajo: presencialZona de trabajo: Partido de San Martin', 0, 'San Martin, Buenos Aires', 'Presencial', 'Full-time', '07-04-2026', '07-04-2026 10:59:41', '10-04-2026 12:44:25', '2026-04-07', NULL, NULL, '2026-04-07T00:00:00-03:00', NULL, NULL, 1, 0, 1, 22, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_945060_bum_v5125d27a.jpg', 1, 0, 3.28, 70, 'Simples', 'bumeran', 'simple', 1, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118221078.html', '2026-04-11T07:05:54.579833');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118223346, 1729850, 'Analista SAP FICO', 'Megatlon', 'Encontrá el trabajo que buscás en la mayor red de gimnasios del país y formá parte de nuestro equipo de profesionales.Si sos dinámico, tenés vocación de servicio y pasión para lograr tus metas, podés unirte a nuestro Staff En MEGATLON nos encontramos en la búsqueda de un/a Analista SAP FICO cuya misión será participar en el proceso de mantenimiento del software existente y del desarrollo de los nuevos requerimientos sobre las herramientas informáticas de la Compañía. Asimismo, contribuir al cumplimiento de los objetivos del área de Desarrollo de la Gerencia de Transformación Digital, garantizando la entrega de productos de calidad dentro de cronograma y presupuestos establecidos.Las tareas principales del puesto son: Brindar soporte técnico y funcional en los módulos SAP FI y CO. Participar en el diseño, configuración, implementación y pruebas de soluciones SAP. Mejorar constantemente la eficiencia y la estabilidad de los módulos implementados Participar en el relevamiento de las necesidades, especificación de los trabajos requeridos, en el análisis de la situación y en el diseño de la solución a aplicar. Requisitos: Excluyente: +3 años de experiencia como Consultor SAP FICO. 1+ años de experiencia trabajando en S/4HANA. Estudiante o graduado/a en Contabilidad, Finanzas, Administración de Empresas, Sistemas o carreras afines. Experiencia como Consultor Técnico/Funcional, con conocimientos en relevamientos, customizing, diseños funcionales, análisis de soluciones custom, pruebas unitarias, análisis de incidencias, soporte a PU, puesta en productivo, post implementación. No Excluyente: Inglés intermedio / Avanzado. Conocimiento de SAP MM / SD / PS SAP Business Data Cloud Beneficios La oportunidad de formar parte de un equipo dinámico y apasionado Un ambiente de trabajo desafiante con posibilidad de desarrollo profesional Equilibrio entre vida personal y laboral Prepaga Medicus 1 día home office por semana Membresía a gimnasios Tarjeta de beneficio Club la Nación', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '08-04-2026', '08-04-2026 12:55:08', '08-04-2026 12:55:08', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 19, 34, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_1729850_bum_vfdfd1266.jpg', 1, 0, NULL, 40, 'Destacados', 'bumeran', 'tecnologia', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118223346.html', '2026-04-11T07:05:54.579923');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118220151, 319880, 'Analista de Gestión de Órdenes de Compra con conocimiento de SAP o S/4HANA (BSAS NORTE)', 'Randstad Argentina', '¡Esta propuesta te puede interesar! Analista de Gestión de Órdenes de Compra con conocimiento de SAP o S/4HANA (BSAS NORTE) Para Nuestro cliente, importante empresa de la industria alimenticia de BSAS Norte, nos encontramos en búsqueda de un analista en gestión de órdenes de compra que pueda prestar servicios de manera eventual durante 9 meses por la implementación del proyecto SAP S/4HANA; con personalidad proactiva, extrovertida, ganas de crecer y aportar en este proceso de cambio de sistema en un ambiente dinámico y demandante. La posición reportará al área de Customer Service, teniendo asignadas las siguientes responsabilidades: Gestión integral de órdenes de compra: Visualizar, entender y procesar los pedidos solicitados por los clientes. Análisis de stock: Realizar el "match" entre la demanda del cliente y el inventario disponible de la compañía para la correcta alocación de productos. Interacción inter área: Coordinar activamente con diferentes sectores de la organización para asegurar la fluidez de los procesos. Análisis de procesos: Identificar oportunidades de mejora en el flujo de gestión de pedidos, más allá de la ejecución transaccional. Requisitos: Experiencia técnica: Manejo de sistema SAP (cualquier versión es aceptable; SAP S/4HANA es un plus). Trayectoria laboral: Experiencia previa en posiciones de Customer Service, Order Management o gestión de pedidos. Residencia: Preferentemente en Capital Federal o GBA Norte (debido a la necesidad de presencialidad eventual). Formación: profesional de administración de empresas, contabilidad, economía, logística o carreras afines. Jornada de Trabajo y Modalidad: Horario: Lunes a jueves de 9:00 a 18:00 hs (esquema variable según necesidades del proyecto). Modalidad: Virtual con semanas de presencialidad. Normalmente se requieren 2 días en oficina, peroné ocasiones la presencialidad puede ser de semana completa según lo que requiera el proyecto. Eventualidad: Contratación eventual con Randstad; finalización estimada a fines de octubre. Si eres una persona desenvuelta, te apasionan los procesos y buscas un desafío que combine gestión administrativa con herramientas tecnológicas, ¡no dudes en postularte! Sobre Randstad En Randstad nos moviliza ayudar a las personas y a las organizaciones a desarrollar todo su potencial. Ese es el compromiso que asumimos como compañía en todo el mundo, un compromiso que nos impulsa a ir más allá para lograr que nuestros clientes y candidatos alcancen el éxito. ¿Cómo lo hacemos?, combinando nuestra pasión por las personas con el poder de la tecnología, creando experiencias más humanas, que nos permitan ser una fuente de inspiración y apoyo para quienes nos eligen. Porque estamos convencidos de que mejores personas hacen mejores.', 0, 'Victoria, Buenos Aires', 'Presencial', 'Full-time', '06-04-2026', '06-04-2026 16:17:05', '11-04-2026 04:17:22', '2026-04-06', NULL, NULL, '2026-04-06T00:00:00-03:00', NULL, NULL, 1, 0, 22, 36, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_319880_bum_vff58225f.jpg', 1, 0, 4.27, 70, 'Simples', 'bumeran', 'simple', 1, 0, 1, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118220151.html', '2026-04-11T07:05:54.580041');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118226794, 1013630, 'Scrum Master', 'ACCIONA IT', 'La modalidad es híbrida: presencialidad 2 veces (Parque Patricios) y 3 remoto.Conocimiento técnico: Certificación PSM I o CSM (obligatorio) / Kanban / técnicas de facilitación Graduado universitario (excluyente) Conocimientos básicos de Product Managment (Product Discovery) Técnicas de priorización)/ Comunicación, negociación y resolución de conflictos Conocimientos básicos técnicos (entornos, deuda técnica, automatización, despliegues, pruebas de software) Ingles intermedioMisión del Puesto Asegurar el entendimiento y aplicación de Scrum en los equipos scrum y en los stakeholders vinculados al equipo Facilitar y asegurar las dinámicas de trabajo asociadas a las metodologías ágiles Ayudar al equipo a evolucionar en su nivel de -madurez, logrando un mayor valor para el negocioPrincipales Responsabilidades: Velar por el correcto empleo y evolución de Scrum Facilitar las ceremonias scrum y ser el "garante" de su correcto uso Proteger al equipo de distracciones y trabas externas a su misión Detectar, monitorear y facilitar la remoción de los impedimentos que puedan surgir con respecto a su misión y a la metodología Asegurar la cooperación y comunicación dentro del equipo Comprender y ayudar a comprender la planificación empírica de incrementos de producto Acompañar al Product Owner y al Technical Leader de forma que puedan adoptar y practicar la agilidad, gestionar el backlog y maximizar el valor al negocio mediante la priorización y la inspección de resultados. Medir y dar visibilidad sobre métricas de desempeño y salud del equipo. Acompañar la gestión de dependencias y la coordinación entre equipos', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '10-04-2026', '10-04-2026 12:36:26', '10-04-2026 12:59:02', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 19, 2619, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_1013630_bum_v9c1aa214.jpg', 1, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'tecnologia', 0, 0, 0, NULL, 'https://certificaciones.greatplacetowork.com.ar/acciona-it', 'https://www.bumeran.com.ar/empleos/1118226794.html', '2026-04-11T07:05:54.580125');
