1, 'Capital Federal, Buenos Aires', 'Presencial', 'Part-time', '07-04-2026', '07-04-2026 16:16:27', '10-04-2026 11:09:20', '2026-04-07', NULL, NULL, '2026-04-07T00:00:00-03:00', NULL, NULL, 2, 0, 26, 2380, 1, NULL, NULL, NULL, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118221972.html', '2026-04-11T07:05:54.580287');
