INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118223131, NULL, 'Sereno con residencia en el establecimiento', 'Confidencial', 'Nos encontramos en la búsqueda de una persona responsable y confiable para desempeñarse como sereno en una quinta ubicada en Escobar, con residencia permanente en el lugar.El puesto implica la vigilancia y el cuidado integral de la propiedad, así como la realización de tareas de mantenimiento general, incluyendo corte de césped y conservación de los espacios.Se valorará especialmente la experiencia previa en funciones similares, la predisposición al trabajo, el orden y el compromiso con las tareas asignadas. Se ofrece vivienda en el establecimiento y un entorno de trabajo estable.Los interesados deberán enviar su currículum vitae, indicando referencias laborales comprobables (en caso de poseerlas) y remuneración pretendida.', 1, 'Escobar, Buenos Aires', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 12:49:02', '10-04-2026 08:23:04', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 22, 2612, 1, NULL, NULL, NULL, NULL, 70, 'Simples', 'bumeran', 'simple', 1, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118223131.html', '2026-04-11T07:05:54.582749');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118227517, 713080, 'Asesor de Servicios', 'AS Recursos Humanos', 'Misión del puestoBrindar una atención de excelencia a los clientes que ingresan al taller, asegurando una experiencia positiva desde el primer contacto hasta la entrega del vehículo. Responsabilidades: Recibir y atender a los clientes en el área de postventa. Escuchar sus necesidades, coordinar los trabajos con el taller y mantener una comunicación fluida durante todo el proceso. Explicar los servicios realizados y ofrecer productos o servicios adicionales que aporten valor al cliente. Trabajar en conjunto con el equipo técnico del taller para garantizar una atención rápida y eficaz. Requisitos: Secundario completo (excluyente) Experiencia en atención al cliente y/o asesoramiento comercial. Valoramos experiencia en concesionarios o rubros afines (servicios técnicos, talleres, posventa automotriz, etc.). Excelente trato interpersonal, actitud proactiva y orientación a resultados. Residencia en Santa Rosa o disponibilidad para radicarse.', 0, 'Santa Rosa, La Pampa', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 17:42:57', '10-04-2026 17:42:57', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 25, 2571, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/0/0/0/0/7/1/3/0/8/0/logoMainPic_713080.jpg', 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227517.html', '2026-04-11T07:05:54.582826');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118223052, 13200468, 'Asesor de Servicios', 'Matias Quintero', 'Somos un grupo empresarial que integra marcas líderes como Iruña, Autonet, Credinet, Oilbull, Akira, JAC, Chery y Hermes. Operamos en sectores estratégicos como la movilidad, las finanzas, el oil & gas y los servicios, y seguimos creciendo hacia nuevas oportunidades en tecnología, energía e industrias clave para el desarrollo de la región. Así nace Grupo Arvor: una identidad que potencia todo lo que hacemos. ¡Sumate a nuestro equipo como Asesor de Servicios!Como Asesor de Servicios, tu misión será ofrecer una atención al cliente excepcional en nuestro concesionario de vehículos, construyendo relaciones de confianza desde el primer contacto. Realizarás un checklist detallado de los vehículos.Coordinarás la apertura de órdenes de trabajo en el taller y supervisarás los procesos de siniestros para garantizar una resolución rápida y satisfactoria. Además, colaborarás estrechamente en la elaboración de cotizaciones para los servicios relacionados con siniestros.Si estás listo para formar parte de un equipo dinámico y contribuir al crecimiento de nuestra empresa, te invitamos a participar en nuestro proceso de selección. ¡Queremos conocerte! Requisitos: Ubicación: Neuquén Capital o alrrededoresEducación mínima requerida: Secundario completoConocimientos técnicos necesarios: Experiencia en atención al clienteOtros requerimientos: Carnet de conducir B1 vigente Beneficios Obra social prepaga de primer nivel, brindando cobertura médica integral.‍ Acceso a gimnasio mediante convenio corporativo. Día de cumpleaños libre, para que puedas disfrutarlo como quieras. Amplias oportunidades de desarrollo y crecimiento profesional dentro de la organización. Un entorno de trabajo que valora el aprendizaje, la proactividad y el trabajo en equipo.', 0, 'Neuquén, Neuquén', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 11:48:30', '08-04-2026 11:48:30', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 25, 2571, 1, NULL, 1, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118223052.html', '2026-04-11T07:05:54.582929');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118221751, NULL, 'Administrativo de servicios', 'Confidencial', '📢 Administrativo/a de Propiedades y Servicios – ¡Sumate a una Pyme en crecimiento!¿Sos organizado/a, detallista y tenés conocimientos contables? ¿Te interesa un rol con impacto directo en la gestión de propiedades y servicios? ¡Esta oportunidad es para vos!Buscamos una persona proactiva, con capacidad de análisis y seguimiento, para incorporarse a una Pyme en constante desarrollo.💼 Principales responsabilidades: Actualización y control de planilla de servicios. Seguimiento de vencimientos, gestión e impresión de facturas y pagos. Administración de seguros (vencimientos, renovaciones y actualización de valores). Liquidación y distribución de expensas. Actualización de alquileres (según IPC y condiciones contractuales). Seguimiento de cobranzas de alquileres, servicios e impuestos. Registración de gastos y cobranzas mensuales. Control del estado general de propiedades (mantenimiento edilicio). Solicitud y análisis de presupuestos para reparaciones. Supervisión de trabajos de mantenimiento. Control y seguimiento de contratos de alquiler. Emisión de reportes de libre deuda. Gestión de documentación y legajos (incluye automóviles).🕒 Horario:Lunes a viernes de 8:00 a 17:30 hs. com media hora para almuerzo. 🚀 ¿Qué ofrecemos? Estabilidad y aprendizaje continuo. Posibilidades reales de crecimiento. Participación activa en una Pyme donde tu gestión es clave.🎯 Buscamos: Perfil analítico, ordenado y metódico. Alta capacidad de seguimiento y control. Buen manejo de múltiples tareas. Responsabilidad y compromiso. Conocimientos contables. Se valorará experiencia en administración de propiedades o tareas similares.👉 Si querés desarrollarte en un rol clave dentro de una empresa en crecimiento, ¡postulate!', 1, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '07-04-2026', '07-04-2026 14:58:00', '07-04-2026 14:58:00', '2026-04-07', NULL, NULL, '2026-04-07T00:00:00-03:00', NULL, NULL, 1, 0, 1, 22, 1, NULL, NULL, NULL, NULL, 40, 'Destacados', 'bumeran', 'destacado', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118221751.html', '2026-04-11T07:05:54.583101');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118227312, 2585810, 'Jefe de Operaciones- Servicio Alimetación', 'Cook Master SRL', 'Somos una empresa líder en alimentación y servicios de consultoría alimentaria. Brindamos soluciones a la medida de cada cliente, ofreciéndole un estilo y atención personalizados.Somos una empresa joven pero contamos con más de 40 años de experiencia desarrollándonos en el ámbito gastronómico, y con el paso de los años hemos avanzado en nuestra forma de pensar y de establecer nuestro único objetivo: Garantizar una Alimentación de Calidad a grandes comunidades. Cook Master, empresa dedicada a brindar soluciones en servicios de alimentación se encuentra en búsqueda de Jefe de Operaciones Gastronómicas.Su principal tarea será gestionar las actividades operativas necesarias para cumplir con los contratos establecidos en los servicios asignados, lograr la satisfacción del cliente, el desarrollo de los equipos de trabajo y la sustentabilidad del negocio. Responsabilidades:-Coordinar y prever acciones con los mandos medios-Desarrollar planes reales de mantenimiento , equipamiento y sanidad en conjunto con el área de mantenimiento-Impulsar y colaborar con el crecimiento comercial de la operación-Revisar y medir los indicadores de cada servicio-Analizar las tendencias y oportunidades de mejoras-Trabajar alineado al Sistema de Gestión de Calidad-Cumplir con las normas de S&H en el trabajo-Detectar y sugerir oportunidades de mejora-Seleccionar, capacitar, desarrollar y evaluar a los colaboradores a su cargo.-Participar y gestionar las tareas del área alineadas con la estrategia de Responsabilidad Social y Sustentabilidad-Participar y gestionar las tareas del área alineadas con la normas ambientales Nos orientamos a la búsqueda de perfiles con marcada vocación de servicio para responder a nuestros clientes, liderazgo para llevar adelante grupos de trabajo con excelente clima, proactividad y orientación a resultados.Para un excelente trabajo en equipo con todas las áreas involucradas, esperamos que el candidato sea flexible y pueda adaptarse a los cambios ya que estamos en constante movimiento. Si te sentís identificado con la propuesta, esperamos tu postulación con remuneración pretendida. En Cook Master creemos que la diversidad nos enriquece y la inclusión nos fortalece.Como empresa B, estamos comprometidos con generar oportunidades laborales equitativas, valorando cada historia, cada talento y cada perspectiva.Todas las personas son bienvenidas a postularse, sin distinción de género, edad, origen, orientación sexual, discapacidad, identidad o trayectoria. Requisitos: Requisitos:-Experiencia en manejo de personal y liderazgo de equipos.-Capacidad de mantener una comunicación fluida respecto al estado del servicio con el resto de las áreas.-Contar con estudios terciarios o universitarios en Gastronomía, Administración, gestión de negocios, o afines.-Contar con mas de 3 años de experiencia en posiciones similares-Conocimiento de BPM, Normas ISO, Inocuidad de los Alimentos, - Nutrición.-Conocimiento de Herramientas Office Beneficios Beneficios:-Prepaga de primer nivel para titular y grupo familiar primario-Almuerzo a cargo de la empresa en oficinas centrales y servicios.-Capacitaciones y programas de formación.-Acceso a diferentes becas-Regalos para fechas especiales.', 0, 'Florencio Varela, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 16:15:56', '10-04-2026 16:15:56', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 10, 2350, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_2585810_bum_ve3fdcb36.jpg', 0, 0, NULL, 2013, 'Simples Hiring Room 30-60', 'bumeran', 'simple', 0, 0, 0, NULL, 'https://certificaciones.greatplacetowork.com.ar/cook-master', 'https://www.bumeran.com.ar/empleos/1118227312.html', '2026-04-11T07:05:54.583286');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224867, 13473059, 'Técnico en mantenimiento - Guardias de Servicio', 'PLControl', 'Importante empresa de servicios de mantenimiento técnico se encuentra en la búsqueda de 3 (tres) Técnicos para cubrir posiciones de Guardia Pasiva para un prestigioso contrato de mantenimiento en la Ciudad Autónoma de Buenos Aires.Descripción del Puesto:Buscamos perfiles técnicos proactivos y con alta responsabilidad para asegurar la continuidad operativa del servicio. Si bien uno de los puestos tendrá un horario fijo de 8:00 a 16:00 hs, los tres candidatos deben contar con la máxima disponibilidad para cubrir un esquema de guardias rotativas y reemplazos según necesidad.Requisitos Excluyentes: Disponibilidad Inmediata: Incorporación efectiva a partir del 1° de Noviembre de 2025. Disponibilidad Horaria: Total y real para cubrir guardias rotativas (esquema 24x7). Este requisito es indispensable. Residencia: Residir en CABA (preferentemente) o zonas aledañas de GBA con fácil y rápido acceso al centro. Edad: Entre 25 y 35 años.Se Valorará (No Excluyente): Formación: Título o conocimientos de Técnico Electromecánico, Eléctrico o Electrónico. Experiencia comprobable en empresas de mantenimiento de ascensores. Contar con movilidad propia.Se Ofrece: Contratación efectiva y en relación de dependencia. Estabilidad laboral vinculada a un contrato importante. Salario acorde a las responsabilidades.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 11:19:59', '09-04-2026 11:19:59', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 3, 0, 16, 70, 1, NULL, 0, 0, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224867.html', '2026-04-11T07:05:54.583447');
