s Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 07:10:31', '10-04-2026 07:10:31', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 16, 32, 1, NULL, 0, 0, NULL, 2001, 'Freemium', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2179324.html', '2026-04-11T07:05:54.584423');
