04-2026 12:24:57', '10-04-2026 21:09:15', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 6, 35, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13406034_bum_v39597a9d.jpg', 0, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1117947268.html', '2026-04-11T07:05:54.584930');
