INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225710, NULL, 'Analista Contable Sr', 'Confidencial', '🌟 ¡Sumate al equipo contable de una marca líder en Indumentaria! 👗✨¿Sos un apasionado de los números y te entusiasma el mundo de la moda? Estamos buscando un Analista Contable Sr con ganas de dar el siguiente paso en su carrera y ser protagonista de nuestro crecimiento.¿Qué desafíos te esperan? No solo vas a registrar datos, vas a ser el guardián de nuestra salud financiera: Gestión Integral: Liderarás el registro contable de ventas multicanal (e-commerce y locales), asegurando que cada operación cuente. Estrategia Impositiva: Armarás los papeles de trabajo clave y seguirás de cerca la agenda de vencimientos para que siempre estemos un paso adelante. Análisis y Control: Realizarás conciliaciones bancarias y facturación con visión analítica.¿Qué buscamos en vos? Formación: Graduados o estudiantes avanzados de Contador Público o Administración (¡valoramos que sigas estudiando!). Experiencia: Al menos 2 años en posiciones similares (si venís del rubro textil/retail, ¡tenés un plus!). Expertiz Técnica: Manejo fluido de plataformas (AFIP, ARBA, AGIP) y aplicativos (SIAP, SICORE). Soft Skills: Buscamos a alguien organizado, con "chispa" para trabajar en equipo y que no le escape a los entornos dinámicos.Lo que ofremos 📍 Ubicación: Nuestras oficinas centrales en CABA 🤝 Modalidad: Trabajo 100% presencial 🚀 Posibilidad real de crecimiento en una empresa en expansión. 👕 Descuentos exclusivos en nuestras colecciones. ¡Queremos conocerte! Postulate enviando tu CV y remuneración pretendida.', 1, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 16:15:43', '10-04-2026 15:59:19', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 1, 58, 1, NULL, NULL, NULL, NULL, 40, 'Destacados', 'bumeran', 'destacado', 1, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225710.html', '2026-04-11T07:05:54.585166');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225700, 13423936, 'Analista Contable Sr', 'Decidir Consulting', 'Brindamos soluciones adaptándonos a las necesidades de nuestros clientes, siendo colaboradores estratégicos en el desarrollo humano, procesos, cambio organizacional en línea con sus objetivos y decisiones clave.- Somos una empresa joven que tiene una visión ágil e integral de trabajo, que crece junto a sus clientes en el desarrollo y crecimiento del negocio.- Nuestro valor fundamental es la atención personalizada a cada cliente.- Nuestro objetivo es afianzar el vínculo colaborativo y la transmisión de cada cultura y política organizacional, buscando las ventajas competitivas para nuestros clientes.- ServiciosEstrategia de Búsqueda y SelecciónHead HuntingExecutive Search (Búsquedas de perfiles ejecutivas, Gerenciales y mandos medios)Recruitment Service (Búsqueda de analistas, administrativos y asistentes)Evaluaciones psicotécnicas y de potencial (Assessment center y técnicas Entrenamiento en liderazgo)Relevamiento de la Cultura OrganizacionalArmado y relevamiento de descripciones de puesto En Decidir Consulting ¡Estamos buscando un/a Analista contable SR! Súmate a una empresa del rubro de servicios.Objetivo del puesto:Garantizar el correcto registro y control de las operaciones contables e impositivas de la empresa, asegurando el cumplimiento de las normativas vigentes y la confiabilidad de la información financiera. Participar en la elaboración de cierres contables, reportes e impuestos, brindando soporte al Líder de Área y al estudio contable externo.Tus principales desafíos: Registrar y controlar los movimientos contables y bancarios en el sistema de gestión, realizando conciliaciones bancarias y de cuentas contables de forma periódica. Realizar asientos contables y provisiones mensuales de gastos, asegurando la correcta imputación de las operaciones. Registrar y dar seguimiento a planes de facilidades, moratorias, préstamos y otros compromisos financieros. Gestionar pólizas de seguros vigentes, controlando su correcta registración y renovación. Controlar que los libros contables y societarios se encuentren llevados en forma adecuada y actualizada. Gestionar trámites y documentación ante organismos e instituciones impositivas (ARCA, AGIP, ARBA, IGJ, entre otros). Controlar, registrar y dar seguimiento a declaraciones juradas de impuestos (IVA, Ingresos Brutos, Ganancias, SICORE, cargas sociales, entre otros). Controlar vencimientos impositivos y asegurar su pago en tiempo y forma. Elaborar reportes contables mensuales para el Líder del Área de Administración. Preparar información y documentación para auditorías internas y externas. Colaborar en la preparación del balance anual. Mantener actualizado el archivo físico y digital de documentación contable e impositiva.Qué esperamos de vos: Sólidos conocimientos en procesos contables. Buen manejo de herramientas informáticas, especialmente paquete Office. Alta capacidad de organización y planificación del trabajo. Atención al detalle y orientación a la calidad de la información financiera. Iniciativa y proactividad para mejorar procesos. Buenas habilidades de comunicación y relaciones interpersonales. Capacidad para trabajar en equipo y articular con distintas áreas. Requisitos: Experiencia mínima de 3 años en posiciones contables e similares. Formación en Administración, Contabilidad o carreras afines. Conocimiento avanzado de Excel. Uso de tecnologías y herramientas de gestión. Perfil orientado a la gestión organizada y al cumplimiento de plazos. Beneficios Se ofrece: Contratación en relación de dependencia. Obra social prepaga 1 día de home office Almuerzo y otros Modalidad full-time', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '09-04-2026', '09-04-2026 16:08:23', '09-04-2026 16:08:23', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 1, 58, 1, NULL, 0, 0, NULL, 2013, 'Simples Hiring Room 30-60', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225700.html', '2026-04-11T07:05:54.585287');
