LL, 1, 0, 1, 22, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13208524_bum_v97869ef9.jpg', 1, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118223795.html', '2026-04-11T07:05:54.585357');
