0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1117955914.html', '2026-04-11T07:05:54.585470');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224814, NULL, 'Analista Sr de Administración y Finanzas', 'Confidencial', 'Caballito | CABAHíbrido (3x2) - Lunes a Viernes de 9:00 a 18:00 hsBuscamos un perfil con experiencia en gestión financiera, administrativa y operativa en empresas del rubro comercial, que pueda aportar orden, control y análisis a los procesos administrativos, para una empresa en crecimiento dedicada al diseño, producción e innovación de productos vinculados al mate.Requisitos:- Experencia minima de 3 años en posiciones similares- Experiencia en planificación financiera, presupuestos y análisis de gestión- Formación (graduado o estudiante avanzado) en Administración, Contabilidad o carreras afines- Manejo avanzado de Excel y herramientas informáticas- Conocimientos en sistemas de gestión ERP- Perfil analítico, organizado, con capacidad de gestión y atención al detalle.Beneficios: Prepaga para el colaborador - Posibilidades de desarrollo y crecimiento dentro de la empresa.Funciones y responsabilidades:- Control de pagos, conciliaciones bancarias y de plataformas digitales- Carga, verificación y seguimiento de facturación- Gestión y coodinación con proveedores y clientes- Implementación y puesta en marcha del sistema de gestión ERP- Carga de datos y optimización de modulos (facturación, pagos, stock)- Definición y mejora de procesos administrativos- Generar reportes para la toma de desiciones- Seguimiento de pedidos y gestión operativa diaria- Propuestas de mejora para optimizar tiempos y procesos', 1, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '09-04-2026', '09-04-2026 10:44:44', '10-04-2026 12:48:26', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 1, 22, 1, NULL, NULL, NULL, NULL, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 1, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224814.html', '2026-04-11T07:05:54.585594');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118224030, NULL, 'Analista Contable Semi Sr', 'Confidencial', 'Imprtante empresa de rubro industrial en Zona General Pacheco, se encuentra en búsqueda de un/a Analista Contable SSr inicial, estudiante avanzado/a de carreras afines a Ciencias Económicas, para sumarse al equipo de Administración, reportando a la Jefatura de Administración. Valoramos especialmente buen manejo de Excel y ganas de desarrollarse.Responsabilidades: Registraciones contables y conciliaciones bancarias. Análisis simple de cuentas patrimoniales y de resultados; armado de papeles de trabajo. Colaborar en cierres mensuales (devengamientos y provisiones estandarizadas). Gestión documental y legajos contables. Mantenimiento y orden de los libros contables y documentación asociada (numeración, archivos físicos/digitales, respaldo y resguardo). Gestión de seguros: administración de pólizas, endosos, renovaciones y seguimiento de reclamos con el broker/aseguradora. Soporte en tareas impositivas recurrentes (IVA, IIBB) con supervisión.Requisitos: 1–3 años de experiencia en tareas contables en empresa o estudio. Estudiante avanzado/a de Ciencias Económicas (preferencia Contador/a; también Administración/Finanzas/Economía con base contable). Excel intermedio-avanzado: tablas dinámicas y BUSCARV o BUSCARX. Experiencia usando algún sistema/ERP (cualquiera) y buena adaptación a nuevos sistemas. Orden, atención al detalle y ompromiso con fechas de cierre.Deseable (no excluyente): Participación en cierres mensuales y conciliaciones bancarias con documentación prolija. Apoyo en documentación para auditorías.Condiciones generales de Contratación: Modalidad: 100% presencial. Horario: full Time Ubicación: General Pacheco', 1, 'General Pacheco, Buenos Aires', 'Presencial', 'Full-time', '08-04-2026', '08-04-2026 17:02:45', '09-04-2026 15:49:17', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 1, 58, 1, NULL, NULL, NULL, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118224030.html', '2026-04-11T07:05:54.585693');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118222857, 13490043, 'Analista Sr. de Tráfico Leisure', 'Unique Talent Solutions', 'Unique Talent Solutions somos una consultora de recursos humanos especializada en reclutamiento y selección para la industria de turismo y hotelería.Nos enfocamos en comprender en profundidad la cultura, los objetivos y las necesidades de cada cliente para atraer talento alineado tanto en lo profesional como en lo humano.Nuestro propósito es generar vínculos laborales sostenibles y de valor, conectando empresas con profesionales que potencien su crecimiento.Por que creemos en el poder de los talentos únicos. Nos encontramos en la búsqueda de profesionales con experiencia desarrollando tareas de Tráfico dentro del turismo receptivo, orientados a garantizar la correcta ejecución de servicios y brindar una experiencia de excelencia al pasajero.Valoramos perfiles dinámicos, resolutivos y con capacidad para anticiparse a imprevistos, con fuerte orientación al detalle y al trabajo en equipo dentro de entornos de alta exigencia.Principales responsabilidades: Seguimiento de Pasajeros en destinos y gestión de eventualidades. Armado de documentación y materiales de bienvenida. Confirmación diaria de vuelos, hoteles y servicios. Gestión operativa de servicios: web check-in, servicios adicionales y asignación de guías. Coordinación con guías, transportistas y proveedores durante las operaciones. Soporte operativo a distintas áreas de la empresa. Participación en el armado y ejecución de experiencias fuera de oficina Control de stock y compras operativas. Guardias rotativas. Requisitos: Experiencia mínima de 3 a 5 años en posiciones similares dentro del rubro turismo (DMC, agencias receptivas o aerolíneas). Buen dominio del idioma inglés, oral y escrito (excluyente). Conocimiento de sistemas de reservas (Sabre/Amadeus) y herramientas de gestión como Turplan y Excel. Proactividad y con capacidad de anticipación frente a cambios operativos y resolución de imprevistos. Capacidad para trabajar bajo presión y gestionar múltiples tareas en simultáneo. Excelentes habilidades interpersonales y orientación al servicio. Beneficios Modalidad híbrida: tres veces por semana en nuestras oficinas de CABA (presencial los primeros 3 meses). Día de cumpleaños libre. Clases de inglés con profesor nativo.Si te interesa formar parte de un equipo orientado a la excelencia operativa y crear experiencias de viaje memorables.¡Queremos conocerte! Envíanos tu CV a recruiter2@unqtalent.com – REF: CV Tráfico Leisure', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '08-04-2026', '08-04-2026 10:21:56', '10-04-2026 15:07:57', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 10, 2360, 1, NULL, NULL, NULL, NULL, 2013, 'Simples Hiring Room 30-60', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118222857.html', '2026-04-11T07:05:54.585815');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2179322, 570364, 'SRE (Site Reliability Engineer)- Híbrido - 1824', 'Aliantec', '¿Qué hace la compañía?Compañía global con fuerte presencia en el sector financiero, enfocada en brindar soluciones tecnológicas para el negocio de Global Markets. Trabaja con plataformas críticas de alto impacto, priorizando la estabilidad, confiabilidad y eficiencia operativa de sus sistemas.¿Qué necesitás para ser parte del equipo?A nivel personal: Perfil proactivo, con fuerte orientación a la resolución de problemas. Capacidad de trabajo en equipo y colaboración con múltiples stakeholders. Buenas habilidades de comunicación. Autonomía y mentalidad orientada a la mejora continua.A nivel técnico: Experiencia de al menos 6 años como SRE / Production Support / Application Support en entornos críticos. Experiencia trabajando con AWS y entornos cloud | Excluyente. Conocimientos en programación (Python o Java/Spring Boot). Experiencia con herramientas de CI/CD (Jenkins, GitLab, Terraform u otras). Fuerte conocimiento en observabilidad y monitoreo (Grafana, Dynatrace, Splunk, Prometheus, Datadog, etc.). Experiencia con Airflow / Astronomer (deseable). Conocimientos en contenedores y orquestación (ECS, Kubernetes). Experiencia en automatización de procesos y reducción de tareas manuales (toil). Nivel de inglés avanzado | Excluyente.¿Qué vas a hacer?Como SRE Engineer, serás responsable de: Brindar soporte diario (BAU) asegurando la estabilidad y disponibilidad de la aplicación. Actuar como punto de contacto principal para incidentes productivos. Evaluar la madurez de la aplicación en términos de confiabilidad, soporte y observabilidad. Identificar mejoras y definir planes de acción. Implementar y mejorar monitoreo y alertas en herramientas como Dynatrace, Splunk y Grafana. Automatizar tareas operativas para mejorar la eficiencia. Reducir el trabajo manual repetitivo (toil). Generar documentación técnica y runbooks. Liderar el proceso de transición y handover al equipo permanente.¿Con qué herramientas trabajarás? AWS y plataformas cloud internas Astronomer (Airflow) Dynatrace Splunk Grafana Geneos Herramientas de CI/CD¿Con quién trabajarás?Formarás parte de un equipo de Production Management dentro del área de Sales & Research, colaborando con equipos globales y stakeholders del negocio financiero.¿Cuándo y dónde trabajarás?Trabajarás bajo un esquema híbrido en Belgrano, CABA, de lunes a viernes de 9 a 18hs.¿Qué ofrecen? Modalidad contractor Pago en USD Trabajo en un entorno global de alta exigencia técnica Participación en proyectos críticos del negocio financiero¿De qué fases consta el proceso de selección?Tendrás una primera entrevista con Lorena Dos Santos para conocer tu experiencia y expectativas.Luego, el proceso continúa con 3 entrevistas con la empresa empleadora, que incluye: una instancia técnica, una segunda de validación técnica y una tercera con el cliente asignado. Finalmente, en caso de poder avanzar se finaliza con las evaluaciones finales y exámenes médicos correspondientes.', 0, 'Capital Federal, Buenos Aires', 'Híbrido', 'Full-time', '09-04-2026', '09-04-2026 22:28:18', '09-04-2026 22:42:14', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 19, 105, 1, 'https://imgzj.jobscdn.com/portal/img/empresas/1/static/logoMainPic_570364_bum_v183b0a04.jpg', 0, 0, NULL, 1020, 'Aviso Select', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2179322.html', '2026-04-11T07:05:54.585926');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225193, 13110602, 'Analista Contable Ssr', 'Bumeran Selecta', 'Importante empresa de servicios orientada a los espacios de trabajo y la industria con más de 55 años de trayectoria en el mercado. La organización integra departamentos de ingeniería y arquitectura que confluyen para garantizar resultados de óptima calidad proyectual y constructiva en todas sus obras. Nos encontramos en la busqueda de un Analista Contable Ssr para brindar soporte integral en la gestión administrativa y contable, asegurando el correcto registro, control y conciliación de las operaciones administrativas contable de la organización. Responsabilidades Principales Gestionar el circuito de Pago a Proveedores. Administrar y dar seguimiento a cuentas corrientes de proveedores y clientes. Realizar conciliaciones bancarias, identificando y resolviendo desvíos. Controlar y conciliar tarjetas de crédito corporativas, verificando consumos y documentación respaldatoria. Participar en la elaboración y seguimiento del Cash Flow, colaborando en la proyección de ingresos y egresos. Colaborar con tareas de facturación y cobranzas, asegurando la correcta emisión y registro. Brindar soporte en temas básicos de impuestos, control documental y cumplimiento de obligaciones. (Deseable) Requisitos: Experiencia previa en posiciones administrativas contables (+5 años) Conocimientos en conciliaciones bancarias y manejo de cuentas corrientes. Nociones de facturación, cobranzas e impuestos. Conocimientos de Cash Flow. Manejo de herramientas informáticas (Excel y sistemas de gestión). Perfil ordenado, analítico y con atención al detalle. Horario de Trabajo: Lunes a viernes de 9 a 18hs. Zona: Chacarita CABA Modalidad: Presencial. Edad: +30 años Sexo: Femenino Nivel de Estudios: Secundario completo, deseable: Universitario o Técnico en carreras a fines Beneficios Puesto bajo convenio:UECARA Puesto Efectivo. Excelente ambiente laboral. Posibilidad de desarrollarse profesionalmente.', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 12:53:40', '09-04-2026 12:53:40', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 1, 22, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13110602_bum_vab9a2cbb.jpg', 1, 0, 3.7, 10, 'Home', 'bumeran', 'home', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225193.html', '2026-04-11T07:05:54.586011');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118222817, 624030, 'Analista Ssr de Nóminas', 'La Anónima', 'Somos La Anónima, una empresa nacional con más de 117 años de trayectoria y un equipo de más de 11.500 personas que todos los días trabaja con un propósito, acercar un futuro mejor a nuestros clientes y comunidades. Estamos orgullosos de ser la primera gran cadena de América certificada como Empresa B, lo que significa que cumplimos con los más altos estándares de desempeño social y ambiental. Operamos con transparencia, generamos impacto positivo en las comunidades y asumimos un compromiso con el desarrollo sostenible. Somos #MuchoMásQueUnSuper porque contamos con un ecosistema de negocios: +165 sucursales en todo el país Una red logística de excelencia, con 1 base de transferencia y 11 centros de distribución regionales 2 plantas frigoríficas y 1 planta industrial de feteados. 1 centro de panificados de elaboración propia. 3 mercados concentradores de frutas y verduras. Nuestro e-commerce La Anónima Online. Y nuestra propia fintech: La Anónima Fintech. También, trabajamos en co-construir una cultura diversa e inclusiva, basada en el respeto y buena convivencia. #Descubrí La Anónima, #Sentí lo que es ser parte de un gran equipo y #Evolucioná con nosotros. #SomosLaAnónima #MuchoMásQueUnSuper Te estamos buscando para trabajar en el equipo de Administración de Personal.Si sos un profesional: Con marcado perfil analítico y minucioso. Que disfruta de trabajar en equipo. Orientado a resultados. Que presenta actitud de servicio hacia áreas internas. y que lo/la moviliza el orgullo de pertenecer a una Compañía en constante crecimiento.¡Sumate a nuestro equipo para seguir haciendo historia juntos!Estos son los desafíos para vos: Ejecutar el proceso de liquidación de sueldos según CCT vigentes. Cargar y controlar novedades de liquidación en el sistema, verificando consistencia con la normativa aplicable y particularidades de cada zona. Controlar reportes y corregir desvíos. Realizar liquidaciones finales y borradores para análisis de costos. Aplicar acuerdos locales y normativa laboral vigente. Análisis y liquidación de cargas sociales, LSD y aplicativos ARCA. Análisis, liquidación y control del Impuesto a las Ganancias (4ta categoría). Dar soporte a Encargados de Personal en las zonas de trabajo. Participar en cierres contables y conciliaciones. Requisitos: Para este rol necesitamos que: Seas estudiante avanzado/a o graduado/a de Cs. Económicas o afines (excluyente). Excel intermedio (excluyente), apliacado a IA (preferentemente). Cuentes con 3 años de experiencia en liquidación de sueldos y gestión masiva de nóminas. Poseas conocimientos sólidos en CCT (Comercio 130/75, Camioneros 40/89, Carne) y personal fuera de Convenio. Tengas experiencia en liquidación de cargas sociales, LSD, impuesto a las ganancias (4ta categoría) y administración de acuerdos. Cuentes con conocimientos de SAP HR (deseable). Beneficios Sabemos combinar la vida profesional con la personal, por eso te ofrecemos: Modalidad Hibrida.( 3 días presenciales y 2 días home office) Jornada Flexible (con posibilidad de ingresar de 8 a 10 hs los días de oficina). Prepaga de primer nivel para vos y tu grupo familiar. Servicio de comedor completo, variado y sin costo. Estacionamiento gratuito. Reintegro mensual de abono de internet. Programa de asistencia gratuito para el empleado y el grupo familiar. Capacitación continua, para fomentar tu desarrollo y estés constantemente actualizado. Descuentos corporativos, descuentos en Sport Club, refrigerios saludables, ¡y más!Desde La Anónima asumimos el compromiso de acercar un futuro mejor a nuestros clientes y comunidades y tenemos la convicción que el camino para lograrlo es a través de una cultura cada día más inclusiva. Somos un equipo que crece, se transforma y potencia en la diversidad y para lograrlo brindamos iguales oportunidades en nuestros procesos de selección a todas las personas, valorando su talento sin distinciones, exclusiones o preferencias.¡Te esperamos para continuar transitando este camino y generar un impacto positivo en nuestros entornos!Sigamos construyendo futuro juntos.#SomosLaAnónima #SomosUnGranEquipowww.laanonima.com.ar', 0, 'Ituzaingó, Buenos Aires', 'Híbrido', 'Full-time', '08-04-2026', '08-04-2026 09:55:12', '10-04-2026 09:57:11', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 1, 0, 17, 2637, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_624030_bum_vbdd6e3bd.jpg', 1, 1, 4.75, 10, 'Home', 'bumeran', 'home', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118222817.html', '2026-04-11T07:05:54.586144');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118222796, 981150, 'Analista Ssr. de Business Intelligence', 'Coppel S A', 'PROPÓSITO"Acompañarte en tus necesidades y deseos, acercándote un mundo de posibilidades para que mejores tu vida".VISIÓNSer la tienda omnicanal y de servicios financieros personales y digitales, favorita del mercado masivo, que ofrece una gran variedad de categorías de productos y servicios útiles, atractivos y accesibles, de marcas líderes, que atiende las necesidades, así como los deseos de los clientes.VALORESConfianzaResponsabilidadAtención y ServicioEficiencia y SencillezInnovación Nos encontramos en la búsqueda de un/a Analista Ssr. para sumarse al equipo de BI, con foco en el análisis de información estratégica, el desarrollo de tableros y la mejora continua de procesos de reporting.Responsabilidades: Analizar información clave (performance, objetivos, presupuestos y variaciones comerciales), detectando desvíos y generando insights para mejorar la toma de decisiones. Diseñar y desarrollar tableros de Business Intelligence que faciliten la visualización de indicadores y contribuyan a una toma de decisiones ágil y basada en datos. Colaborar con los equipos de Contabilidad, Finanzas, Marketing, Comercial y Operaciones para alinear procesos, consolidar datos y definir metodologías comunes de análisis. Optimizar y automatizar procesos de reporting, reduciendo tiempos operativos y minimizando errores en la generación de información. Requisitos: Estudiantes avanzados/as o graduados/as de carreras como Ingeniería Industrial, Administración de Empresas, Economía, Contador/a, Sistemas o afines. Experiencia mínima de 3 años en roles similares, con participación activa en análisis de datos, elaboración de reportes y armado de tableros. Dominio de herramientas de BI (Power BI, Tableau, Qlik u otras). Residencia en Zona Norte o cercanías. Modalidad de trabajo: 100% presencial en nuestras oficinas de Pacheco. ¿Querés ser parte del desafío? Postulate ahora y sumate a Coppel Argentina para seguir transformando el futuro juntos!¡La unica tienda donde todo se encuentra!#MejoraTuVida Beneficios Cobertura médica OSDE para la persona contratada y su grupo familiar primario. Capacitación constante y oportunidades de desarrollo. Día de cumpleaños libre. Días libres adicionales. Plataforma Club de Beneficios con descuentos en distintas marcas. Descuentos en productos de la compañía.', 0, 'General Pacheco, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 11:38:31', '09-04-2026 11:38:33', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 19, 2647, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_981150_bum_ve0658e62.jpg', 0, 0, 3.81, 40, 'Destacados', 'bumeran', 'tecnologia', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118222796.html', '2026-04-11T07:05:54.586240');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118225043, 13277993, 'Analista de Administración de Personal Ssr', 'Consultora D''Amelio', 'Cuenta Demo de Hiring Room, el software de reclutamiento y selección para profesionales hiperconectados.https://hiringroom.com/ Prueba demo Descripción del puesto: Analista de Administración de Personal SsrEn nuestro equipo de Recursos Humanos y Capacitación en Buenos Aires, Argentina, estamos en búsqueda de dos Analistas de Administración de Personal Semi senior.Buscamos personas proactivas y organizadas, con capacidad para gestionar procesos relacionados con la administración de personal de manera eficiente y en cumplimiento de las normativas vigentes.El Analista de Administración de Personal Ssr será responsable de llevar a cabo tareas como la gestión de nóminas, control de ausentismo, seguimiento de contratos, elaboración de informes y análisis de métricas del área.Es fundamental que el candidato cuente con una formación universitaria completa y experiencia previa en posiciones similares. Además, deberá tener sólidos conocimientos en legislación laboral y manejo de herramientas informáticas específicas.Si te consideras una persona comprometida, con capacidad para trabajar en equipo y con habilidades para la resolución de problemas, ¡te estamos buscando!Modalidad de trabajo: PresencialEducation Level: Universitario (Graduado)Tipo de trabajo: Full-time Requisitos:', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '09-04-2026', '09-04-2026 12:10:09', '09-04-2026 12:10:09', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 2, 1, 17, 2637, 1, NULL, 0, 0, NULL, 2013, 'Simples Hiring Room 30-60', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118225043.html', '2026-04-11T07:05:54.586313');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118221812, 10105582, 'Ingeniero/a de Verificación de Producto Ssr', 'Kinetic SA', 'Empresa cliente dedicada al diseño y fabricación de tecnología médica de alta complejidad. Desde Kinetic Talent, estamos en búsqueda de un/a Ingeniero/a de Verificación de Producto Sr para sumar a empresa cliente del rubro del desarrollo y fabricación de equipamiento médico. Las principales responsabilidades serán: Generar y ejecutar planes de prueba en conjuntos y equipos médicos durante las etapas de Diseño y Desarrollo. Liderar la transición hacia la automatización de casos de prueba y la integración de herramientas de IA en los procesos de verificación. Asegurar que cada diseño cumpla con las especificaciones técnicas y los requisitos de seguridad. Coordinar ensayos en laboratorios internos/externos y documentar resultados con evidencia objetiva. Identificar bugs y proponer oportunidades de mejora en los requisitos técnicos desde una perspectiva de sistemas. Requisitos: ​​​​​​​Excluyentes: Graduado/a de Ing. Electrónica / Ing. en Computación, Sistemas o afines. Al menos 2 años de experiencia en posiciones similares, de diseño y desarrollo, laboratorio de ensayos. Implementación de herramientas de IA en los procesos de verificación. Inglés nivel intermedio. Lectura de documentación técnica (planos, hojas de datos, reportes). Manejo de instrumentos de medición eléctrica y neumática básica. Desarrollo de casos de prueba.Deseables: Tener experiencia en ensayos, mediciones eléctricas, ensayos funcionales (Valorable). Herramientas de gestión de proyecto (Deseable). Manejo de instrumentos de medición neumáticos / Mecánicos (Deseable). Beneficios Obra social Osde 210. Almuerzo en planta. 3 semanas de vacaciones. Día off por cumpleaños y aniversario de la empresa.', 0, 'Córdoba, Córdoba', 'Híbrido', 'Full-time', '09-04-2026', '09-04-2026 13:37:26', '09-04-2026 13:37:26', '2026-04-09', NULL, NULL, '2026-04-09T00:00:00-03:00', NULL, NULL, 1, 0, 30, 2631, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/0/0/1/0/1/0/5/5/8/2/logoMainPic_10105582_bum_vc6efcae3.jpg', 0, 0, NULL, 2001, 'Freemium', 'bumeran', 'freemium', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118221812.html', '2026-04-11T07:05:54.586432');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (2179114, 445603, 'Subjefe De Mantenimiento', 'EMC & Asociados', 'Nuestro cliente, una importante empresa dedicada a la fabricación de aberturas metálicas y de madera, ubicada en la zona de González Catán / Virrey del Pino, nos ha encomendado la búsqueda de un/a Subjefe de Mantenimiento.Nos orientamos a un perfil con sólida experiencia en mantenimiento industrial, que cuente con capacidad para liderar equipos de trabajo, organizar tareas y asegurar el correcto funcionamiento de los equipos productivos, con foco en la mejora continua y la eficiencia operativa.Sus principales responsabilidades serán: Supervisar el desarrollo de los trabajos mecanizados dentro de la planta. Gestionar la distribución de órdenes de trabajo y realizar el seguimiento de sus resultados. Coordinar con el área de compras la gestión de insumos y repuestos. Recepcionar y supervisar al personal externo (tercerizado) en sus tareas. Llevar adelante los planes de mantenimiento preventivo. Analizar anomalías y fallas de maquinaria, proponiendo mejoras y procedimientos que minimicen dichos eventos. Requisitos: Disponibilidad para trabajar de lunes a viernes de 7 a hs Formación en Ingeniería Mecánica o Electromecánica (preferentemente, no excluyente). Experiencia mínima de 5 años en mantenimiento industrial. Manejo de instrumentos de medición y lectura de planos. Conocimientos de AutoCAD o programas similares. Capacidad de liderazgo, organización y orientación a resultados. Beneficios Obra social a cargo de la empresa. Comedor en planta. Estacionamiento dentro del predio.Si te interesa esta oportunidad, envianos tu CV indicando remuneración pretendida.', 0, 'La Matanza, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 07:27:29', '10-04-2026 07:27:29', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 1, 0, 16, 70, 1, 'https://imgzj.jobscdn.com/portal/img/empresas/1/static/logoMainPic_445603_bum_v2032d79c.jpg', 1, 0, NULL, 2001, 'Freemium', 'zonajobs', 'zonajobs', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/2179114.html', '2026-04-11T07:05:54.586616');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118219213, 13239433, 'Responsable de Sucursal - rubro automotor', 'LinkUp Group', 'Importante empresa del rubro automotor se encuentra en la búsqueda de un Responsable de Sucursal para liderar integralmente la operación.Buscamos un perfil con fuerte impronta comercial, con experiencia en el rubro que pueda gestionar tanto el negocio como el equipo de trabajo.Principales responsabilidades:Gestión comercial integral Venta de repuestos en salón y en terreno (flotas, transportistas, clientes corporativos). Desarrollo, fidelización y ampliación de cartera de clientes. Identificación de oportunidades de negocio en el mercado local.Supervisión de servicios técnicos Coordinación de servicios de taller. Control de calidad y cumplimiento de tiempos de trabajo. Resolución de situaciones técnicas y atención de reclamos.Liderazgo de equipo Conducción de un equipo multidisciplinario (taller, administración y ventas). Organización de tareas, turnos y seguimiento de desempeño. Capacitación y desarrollo del equipo.Gestión operativa Control de stock Coordinación con proveedores y gestión de compras. Supervisión del orden y funcionamiento general del local.Atención al cliente Asesoramiento técnico-comercial. Garantizar una experiencia de servicio de calidad. Seguimiento postventa.Gestión administrativa y de resultados Seguimiento de indicadores comerciales, márgenes y rentabilidad. Control de facturación y gestión de caja. Reporte de resultados a la gerencia. Análisis de mercado y competencia en Mendoza.Requisitos Experiencia previa en posiciones similares dentro del rubro servicios automotrices (excluyente). Perfil comercial con experiencia en venta consultiva. Experiencia liderando equipos de trabajo. Orientación a resultados y gestión integral del negocio. Manejo de herramientas informáticas, excel intermedio -avanzadoBeneficios Posición con alto nivel de autonomía y responsabilidad. Desarrollo profesional en una empresa en crecimiento. Condiciones acordes al mercado + esquema de incentivos. (pre paga, movilidad, entre otras).', 0, 'Mendoza, Mendoza', 'Presencial', 'Full-time', '06-04-2026', '06-04-2026 10:07:34', '10-04-2026 10:24:04', '2026-04-06', NULL, NULL, '2026-04-06T00:00:00-03:00', NULL, NULL, 1, 0, 6, 2628, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13239433_bum_ve5e6c0cc.jpg', 0, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118219213.html', '2026-04-11T07:05:54.586724');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118219919, NULL, 'Encargada/o de Sucursal- Z/ Berazategui/Quilmes', 'Confidencial', 'Importante Compañìa Financiera incorpora: Encargada/o de sucursal para la zona de Berazategui/QuilmesQuien ocupe la posiciòn serà responsable de la la totalidad de la operatoria diaria de la sucursal, siendo el nexo con la casa central y teniendo a su cargo, entre otras, las siguientes tareas:Planificar e Implementar las estrategias y acciones de venta necesarias para alcanzar los objetivos mensuales previstos.Coordinar y supervisar la labor de las personas a su cargo, con el fin de asegurar la calidad de atención al cliente.Atenciòn y asesoramiento a clientes, tanto presencial como telefònicamente ásí como también a través de redes sociales y canales digitales, ya sea por ventas, pagos o reclamos.Evaluaciòn y análisis de riesgo crediticio.Ventas de servicios financieros.Chequeo y verificaciòn de documentaciòn.Cobranzas de cuotas, manejo de efectivo y links de PagoFidelización de clientes.Colaborar con la Casa Central en todas las gestiones administrativas relativas al punto de venta (habilitaciones,permisos, etc)Orientamos nuestra bùsqueda a candidata/os resolutiva/os y autònoma/os, que cuenten con experiencia en ventas ; que posean un alto sentido de compromiso y sean capaces de trabajar bajo presión .', 1, 'Berazategui, Buenos Aires', 'Presencial', 'Full-time', '06-04-2026', '06-04-2026 14:29:30', '10-04-2026 13:18:25', '2026-04-06', NULL, NULL, '2026-04-06T00:00:00-03:00', NULL, NULL, 1, 0, 6, 35, 1, NULL, NULL, NULL, NULL, 70, 'Simples', 'bumeran', 'simple', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118219919.html', '2026-04-11T07:05:54.586851');
INSERT OR IGNORE INTO ofertas (id_oferta, id_empresa, titulo, empresa, descripcion, confidencial, localizacion, modalidad_trabajo, tipo_trabajo, fecha_publicacion_original, fecha_hora_publicacion_original, fecha_modificado_original, fecha_publicacion_iso, fecha_hora_publicacion_iso, fecha_modificado_iso, fecha_publicacion_datetime, fecha_hora_publicacion_datetime, fecha_modificado_datetime, cantidad_vacantes, apto_discapacitado, id_area, id_subarea, id_pais, logo_url, empresa_validada, empresa_pro, promedio_empresa, plan_publicacion_id, plan_publicacion_nombre, portal, tipo_aviso, tiene_preguntas, salario_obligatorio, alta_revision_perfiles, guardado, gptw_url, url_oferta, scrapeado_en) VALUES (1118223547, 13135046, 'Operador de venta telefónica (sueldo convenio de comercio + plan comisional sin tope) Turno Tarde', 'Verisure Argentina', '¡Hagamos Match para Potenciarnos!🚀 Nuestro equipo continúa creciendo y vos podes formar parte. Buscamos una persona dinámica, proactiva y que esté lista para los desafíos que tiene el equipo de Televenta y Telecierre.Te invitamos a formar parte de una compañía multinacional líder en el sector de Sistemas de Seguridad, cuyo posicionamiento se centra en sus soluciones tecnológicas innovadoras, la conectividad de sus sistemas y la experiencia de cliente. Estamos presentes en 18 países alrededor del mundo y contamos con una trayectoria de más de 35 años en el mercado.Estamos en la búsqueda de Vendedores Telefónicos para el equipo de Televenta y Telecierre para incorporarse al área de Marketing 👩🏼‍💻 Días y Horario: De lunes a Viernes de 15 a 21hs (100% presencial). Lugar de trabajo: Palermo✅Principales desafíos Emisión y/o recepción de llamadas comerciales para captación de nuevos clientes. Gestión y seguimiento durante todo el proceso. Trabajo con objetivos semanales / mensuales.🔎¿Qué buscamos? Experiencia en Call Center de Ventas (Excluyente) Experiencia trabajando por objetivos (Excluyente) Experiencia en venta de seguros, portabilidad, planes de ahorro o similares (Excluyente) Perfil extrovertido, dinámico, proactivo, con alta capacidad de negociación. Muy buen manejo de PC y plataformas digitales. Buenas habilidades orales y escritas. Estudios secundarios finalizados (Excluyente)¿Qué ofrecemos? 💰Sueldo bruto por convenio de comercio. 💸Plan de comisiones sin tope. 👩‍⚕️Swiss Medical prepaga para vos y grupo familiar primario a partir del septimo mes. 🍬Tarjeta de snacks mensual. 📚Beneficios corporativos (Descuentos en Universidades, Institutos de idioma, Telefonía, etc.) 🤟🏽Plan de carrera y capacitación continua.Sabemos que la cultura organizacional es clave para elegir tu próximo desafío profesional. Por este motivo, te queremos presentar el ADN de Verisure Argentina para que conozcas nuestra propuesta de valor que nos hace una de las mejores empresas para trabajar en nuestro país🚀:- Pasión en todo lo que hacemos.- Compromiso para marcar la diferencia.- Innovación constante.- Ganando como equipo.- Confianza y responsabilidad.¡Si considerás que compartís estos valores con nosotros, te invitamos a ser parte de Verisure Argentina para proteger juntos lo que más nos importa! ⚡En Verisure, nos comprometemos a fomentar un entorno de trabajo diverso e inclusivo, reconociendo que la diversidad de pensamiento y origen fortalece a nuestros equipos y los hace más innovadores. Rechazamos toda forma de discriminación y prejuicio, y creemos en el acceso a oportunidades para todos, independientemente de su género, edad, discapacidad, raza, orientación sexual o cualquier otra condición.', 0, 'Buenos Aires, Buenos Aires', 'Presencial', 'Part-time', '08-04-2026', '08-04-2026 13:54:18', '08-04-2026 13:54:18', '2026-04-08', NULL, NULL, '2026-04-08T00:00:00-03:00', NULL, NULL, 15, 0, 6, 35, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13135046_bum_v8f08de73.jpg', 1, 0, NULL, 40, 'Destacados', 'bumeran', 'destacado', 1, 0, 0, NULL, 'https://certificaciones.greatplacetowork.com.ar/verisure', 'https://www.bumeran.com.ar/empleos/1118223547.html', '2026-04-11T07:05:54.587076');
