buenas condiciones de contratación Posibilidades reales de desarrollo y crecimiento', 0, 'Capital Federal, Buenos Aires', 'Presencial', 'Full-time', '10-04-2026', '10-04-2026 14:58:24', '10-04-2026 14:58:24', '2026-04-10', NULL, NULL, '2026-04-10T00:00:00-03:00', NULL, NULL, 2, 0, 4, 2642, 1, 'https://imgbum.jobscdn.com/portal/img/empresas/1/static/logoMainPic_13004871_bum_v74df1f84.jpg', 0, 0, NULL, 1020, 'Aviso Talento', 'bumeran', 'talento', 0, 0, 0, NULL, NULL, 'https://www.bumeran.com.ar/empleos/1118227142.html', '2026-04-11T07:05:54.587223');
